SELECT 'moj-all-verified-judgments-review-002-chunk-075' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b698b1a8-2457-5936-860e-b3a357413841","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -ثبوت إدانة املدعى عليه -ندم -نزول عن احلد األدنى للعقوبة -مقاومة رجال األمن -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر -تعزير تخدمني يف اجلرمية- مبصادرة الهاتف اجلوال وشريحته املس ظروف مخففة للعقوبة.","document_number":"3425538","case_number":"34186011","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/28","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -ثبوت إدانة املدعى عليه -ندم -نزول عن احلد األدنى للعقوبة -مقاومة رجال األمن -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر -تعزير تخدمني يف اجلرمية- مبصادرة الهاتف اجلوال وشريحته املس ظروف مخففة للعقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3425538:‬تاريخه‪1434/01/28 :‬هـ‬\n                   ‫رقم الدعوى‪34186011:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪3446381‬تاريخه‪1434/02/24:‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة‪ -‬ثبــوت إدانــة املدعــى عليــه‪ -‬نــدم‬\n‫‪-‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬مقاومــة رجــال األمــن ‪ -‬تعزيــر‬\n‫املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر ‪ -‬تعزيــر‬\n‫ـتخدمني يف اجلرميــة‪-‬‬‫َ‬       ‫مبصــادرة الهاتــف اجلــوال وشــريحته املسـ‬\n                                                ‫ظــروف مخففــة للعقوبــة‪.‬‬\n\n\n\n\n‫فقــرة ‪ 2‬مــن املــادة ‪ ، 3‬املــادة (‪ ، )38‬املــادة (‪ ، )56‬املــادة (‪ )60‬مــن نظــام‬\n                                 ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫أقــام املدعــي العــام دعــواه ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات‬\n‫اإلمفيتامــن ‪ ،‬بقصــد الكســب املــادي ‪ ،‬حيــث مت القبــض علــى املدعــى‬\n‫عليــه وهــو يــروج حبــوب االمفيتامــن وأقــر املدعــى عليــه بصفــة الترويــج‬\n‫وأثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n‫اإلمفيتامــن وطلــب املدعــي العــام احلكــم علــى املدعــى عليه‪،‬بعقوبــة‬\n‫تعزيريــة واملنــع مــن الســفر خــارج البــاد بعــد تنفيــذ العقوبــة ومصــادرة‬\n‫جهــاز اجلــوال املســتخدم يف الترويــج وإلغــاء الشــريحة املســتخدمة يف‬\n‫الترويــج لنفــس املدعــى عليــه‪ ،‬إقــرار املدعــى عليــه بالدعــوى ‪ -‬قــررت‬\n\n                                                                                       ‫‪398‬‬\n\f      ‫احملكمــة بثبــوت إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة‪،‬‬\n      ‫حكمــت احملكمــة علــى املدعــى عليــه بســجنه ســنة وســتة أشــهر تبــدأ‬\n      ‫مــن تاريــخ توقيفــه يف هــذه القضيــة‪ ،‬وجلــده خمســن جلــدة مفرقــة علــى‬\n      ‫دفعــات كل دفعــة خمســون جلــدة بينهمــا عشــر أيــام‪ ،‬وإلزامــه بدفــع‬\n      ‫غرامــة ماليــة قدرهــا ثالثــة آالف ري ــال‪ ،‬واملنــع مــن الســفر خــارج البــاد‬\n      ‫مــدة ســنتني تبــدأ بعــد انتهــاء عقوبة ســجنه‪ ،‬ومصــادرة اجلوال املســتخدم‬\n      ‫يف الترويــج وإلغــاء الشــريحة وعــدم صرفهــا لنفــس املتهــم‪ ،‬وعقوبــة‬\n      ‫تعزيريــة لقــاء توجيــه التهمــة عليــه مبقاومــة رجــال الفرقــة القابضــة‬\n      ‫بجلــده خمســن جلــدة دفعــة واحــدة‪ ،‬قــرر املدعــي العــام عــدم قناعتــه‬\n      ‫باحلكــم ‪،‬وقنــع املدعــى عليــه وجــرى تصديــق احلكــم مــن محكمــة‬\n                                                                          ‫االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬‬\n      ‫وتاريــخ ‪1434/01/21‬هاملقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ‬\n      ‫‪1434/01/21‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/01/27‬ه ـ حضــر‬\n      ‫ا‬\n      ‫املدعــي العــام‪.......... /‬املشــار إلــى تكليفــه يف الضبــط وادعــى قائ ـ ً‬\n      ‫دعــواي هــي مــا ورد يف الئحــة الدعــوى العامــة املتضمنــة االدعــاء علــى‪/‬‬\n      ‫‪...................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)..........‬‬\n      ‫حيــث أنــه بتاريــخ ‪1433/12/15‬ه ـ مت القبــض عليــه لترويجــه احلبــوب‬\n      ‫احملظــورة وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام لــه بترويــج ثــاث‬\n\n‫‪399‬‬\n\f‫حبــات مــن حبــوب االمفيتامــن املنبهــة احملظــورة عن طريــق البيع وحيازة‬\n‫حبــة بقصــد الترويــج واملجــرم مبوجــب املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة وتوجيــه االتهــام لــه مبقاومــة رجــال األمــن‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪-1 :‬مــا ورد بإقــراره املــدون علــى الصفحــة‬\n‫رقــم (‪ )3‬مــن دفتــر التحقيــق رقــم (‪ )1‬وعلــى الصفحــة رقــم(‪ )18‬مــن ملف‬\n‫إجــراءات االســتدالل رقــم(‪ -2 )1‬مــا تضمنــه محضــر القبــض والتفتيــش‬\n‫املــدون علــى الصفحــة رقــم (‪ )11‬مــن ملــف إجــراءات االســتدالل املرفــق‬\n‫لفــه رقــم (‪ -3 )1‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املرفــق لفــه‬\n‫رقــم(‪ )13‬وبالبحــث عمــا إذا كان لــه ســوابق اتضــح عــدم وجــود ســوابق‬\n‫مســجلة عليــه وحيــث أن مــا أقــدم عليــه املذكــور فعــل محــرم شــرع ًا‬\n‫ومجــرم ومعاقــب عليــه نظام ـ ًا مبوجــب نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا‬\n‫يلــي‪-1 :‬عقوبــة تعزيزيــه وفقـ ًا ملــا ورد فاملــادة (‪ )1/38‬مــن النظــام املشــار‬\n‫إليــه لقــاء مــا أســند إليــه ‪ -2‬منعــه مــن الســفر خــارج اململكــة بعــد‬\n‫تنفيــذ العقوبــة وفق ـ ًا ملــا ورد يف املــادة (‪ )56‬الفقــرة األولــى مــن النظــام‬\n‫املشــار إليــه ‪ -3‬مصــادرة جهــازي اجلــوال ذوي الرقمــن املصنعــي رقــم‬\n‫(‪ )..........‬ورقــم(‪ )..........‬وذلــك الســتعمالها يف قضيــة الترويــج وفق ـ ًا ملــا‬\n‫ورد يف املــادة (‪ )1/53‬مــن النظــام املشــار إليــه وإلغــاء رقــم الشــريحة‬\n‫(‪ )..........‬لنفــس املدعــى عليــه وفق ـ ًا لتعميــم صاحــب الســمو امللكــي‬\n‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪ -4‬عقوبــة‬\n‫تعزيريــة لقــاء مقاومتــه لرجــال األمــن عنــد القبــض عليــه هــذه دعــواي‬\n‫ا‬ ‫ويف هــذه اجللســة حضــر املدعــى عليــه وبســؤاله اإلجابــة أجــاب قائ ـ ً‬\n‫مــا نســب لــي يف دعــوى املدعــي العــام كلــه صحيــح إذ قمــت بترويــج‬\n\n\n                                                                                         ‫‪400‬‬\n\f      ‫الكميــة املشــار إليهــا يف الدعــوى مقابــل مبلــغ قــدره مائتــا ريــال وســلمت‬\n      ‫الكميــة واســتلمت املبلــغ واســتخدمت اجلــوال وشــريحة اإلتصــال املشــار‬\n      ‫إليهمــا يف الدعــوى يف التنســيق لهــذه العمليــة وأمــا مــا نســب لــي مــن‬\n      ‫مقاومــة رجــال الفرقــة فهــذا غيــر صحيــح فلــم أقاومهــم وليــس لــي‬\n      ‫ســوابق وأنــا تائــب إلــى اهلل وأتعهــد بعــدم العــودة لذلــك هــذه إجابتــي‬\n      ‫وجــرى االطــاع علــى األدلــة والقرائــن املشــار إليهــا يف دعــوى املدعــي‬\n      ‫العــام فوجــد مضمونهــا كمــا ذكــر ووجــد يف محضــر القبــض يف امللــف‬\n      ‫املرفــق باملعاملــة لفــة رقم(‪)1‬أنــه أثنــاء القبــض علــى املدعــى عليــه قــاوم‬\n      ‫مقاومــة عنيفــة ووجــد أن التقريــر الكيميائــي الشــرعي رقــم ‪..........‬لعــام‬\n      ‫‪1433‬ه ـ املرفــق باملعاملــة لفــة رقم(‪)12‬يتضمــن أنــه بتحليــل عينــة ممــا‬\n      ‫مت ضبطــه مــع املدعــى عليــه ثبــت إيجابيهــا ملــادة االمفيتامــن املخــدر‬\n      ‫احملظــور فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى‬\n      ‫عليــه ومصادقتــه علــى مــا نســب لــه يف الدعــوى عــدا إنــكاره مقاومــة‬\n                                                   ‫ـاء علــى مــا يلــي‪:‬‬\n                                                                     ‫الفرقــة القابضــة وبنـ ً‬\n      ‫‪-1‬ترويــج املدعــى عليــه حلبــوب االمفيتامــن احملظــورة فعــل محرم شــرع ًا‬\n      ‫ومجــرم نظامـ ًا ملــا نصــت عليــه الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومعاقــب عليــه بالعقوبة األصلية‬\n      ‫الــواردة يف املــادة الثامنــة والثالثــن والعقوبــة التكميليــة الــواردة يف‬\n      ‫املــادة السادســة واخلمســن مــن النظــام املشــار إليــه ‪-2‬ماتضمنــه التقريــر‬\n      ‫الكيميائــي املشــار إليــه ‪-3‬مــا قــرره املدعــى عليــه مــن التوبــة وتعهــده‬\n      ‫بعــدم تكــرر الفعــل منــه وعــدم وجــود ســوابق عليــه ولقلــة الكميــة‬\n      ‫ولصغــر ســنه هــذا كلــه يســتوجب تخفيــف العقوبــة عليــه والنــزول عــن‬\n      ‫احلــد األدنــى املقــرر يف املــادة الثامنــة والثالثــن وفقــا ملــا ورد يف املــادة‬\n\n\n‫‪401‬‬\n\f‫الســتني مــن النظــام املشــار إليــه ‪ - 4‬اســتخدام املدعــى عليــه للجــوال‬\n‫وشــريحة اإلتصــال املشــار إليهــا يف الدعــوى يســتوجب مصادرتــه وفق ـ ًا‬\n‫ملــا نصــت عليــه املــادة الثالثــة واخلمســن مــن النظــام املذكــور ووفق ـ ًا‬\n‫لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة املشــار إليــه ‪-5‬توجــه‬\n‫التهمــة علــى املدعــى عليــه مبقاومــة رجــال الفرقــة القابضــة وذلــك ملــا‬\n‫تضمنــه محضــر القبــض لــذا فقــد تقــرر مــا يلــي ‪:‬أو ًال ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بترويــج ثــاث حبــات مــن حبــوب االمفيتامــن املنبهــة‬\n‫احملظــورة عــن طريــق البيــع وحيــازة حبــة بقصــد الترويــج وقــررت تعزيــره‬\n‫علــى ذلــك بســجنه مــدة ســنة وســتة أشــهر تبــدأ مــن تاريــخ توقيفــه يف هذه‬\n‫القضيــة وجلــده مئــة وخمســن جلــدة مفرقــة علــى دفعــات كل دفعــة‬\n‫خمســون جلــدة وبينهمــا عشــرة أيــام وإلزامــه بدفــع غرامــة ماليــة قدرهــا‬\n‫ألــف ريــال خلزينــة الدولــة ومنعــه مــن الســفر إلــى خــارج هــذه البــاد مــدة‬\n‫ســنتني تبــدأ بعــد انتهــاء عقوبــة ســجنه املنصــوص عليهــا أعــاه ثاني ـاً‪:‬‬\n‫ثبــت لــدي اســتخدام املدعــى عليــه للجــوال وشــريحة االتصــال املشــار‬\n‫إليهــا وقــررت مصــادرة ذلــك وعــدم صــرف شــريحة االتصــال لنفــس‬\n‫املســتخدم ثالث ـاً‪ :‬قــررت تعزيــر املدعــى عليــه لقــاء توجــه التهمــة عليــه‬\n‫مبقاومــة رجــال الفرقــة القابضــة وذلــك بجلــده خمســن جلــدة دفعــة‬\n‫واحــدة وبذلــك حكمــت وبعــرض احلكــم علــى املدعــي العــام قــرر‬\n‫اعتراضــه علــى احلكــم وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة‬\n‫اعتراضيــه وبعرضــه علــى املدعــى عليــه قــرر قناعتــه باحلكــم وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪ 1434/01/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n\n\n                                                                                       ‫‪402‬‬\n\f      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n      ‫‪..........‬وتاريــخ ‪1434/2/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ‪.......... /‬برقــم ‪..........‬وتاريخ ‪1434/1/28‬هـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد‪.......... /‬يف قضيــة (مخــدرات) علــى‬\n      ‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n      ‫املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                    ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪403‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":398,"source_page_end":403,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dc91a1a5f71ac4932635d3c8cdf9d9d65383da039a7830d8533281090c5cca7a","normalized_text_hash":"f37979a7aa1130f8d6ee93bbb0b4eed2b2c6013eec447bb3e801fb874309f24d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p398-3425538"},{"id":"0577d345-eef2-59ea-adf0-50e9e8002568","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -قات -األصل براءة الذمة -اخلطأ يف العفو خير من اخلطأ يف العقوبة -حكم برد الدعوى -سند شرعي -بينة","document_number":"34207894","case_number":"34187484","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/6","year":"1434","subject":"مخدرات -ترويج -قات -األصل براءة الذمة -اخلطأ يف العفو خير من اخلطأ يف العقوبة -حكم برد الدعوى -سند شرعي -بينة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34207894 :‬تاريخه‪1434/5/6 :‬هـ‬\n                  ‫رقم الدعوى‪34187484:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34223297‬تاريخه‪1434/05/26:‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج ‪ -‬قــات ‪ -‬األصــل بــراءة الذمــة ‪ -‬اخلطــأ يف العفــو‬\n‫خيــر مــن اخلطــأ يف العقوبــة ‪ -‬حكــم بــرد الدعــوى ‪ -‬ســند شــرعي‪ -‬بينــة‬\n                                                               ‫غيــر موصلــة‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعالــى ( ومــا يتبــع أكثرهــم إال ظن ـ ًا إن الظــن ال يغنــي مــن‬\n                                  ‫احلــق شــيئا إن اهلل عليــم مبــا يفعلــون )‬\n‫‪ -2‬قولــه صلــى اهلل عليــه وســلم ( ادرؤوا احلــدود عــن املســلمني مــا‬\n‫اســتطعتم فــإن كان لــه مخــرج فخلــوا ســبيله فــإن اإلمــام أن يخطــئ‬\n                         ‫يف العفــو خيــر مــن أن يخطــئ يف العقوبــة ) ‪.‬‬\n                     ‫‪ -3‬األصل البراءة وال يزول هذا األصل إال بيقني ‪.‬‬\n                       ‫‪ -4‬القاعدة الشرعية ‪ :‬اليقني ال يزول بالشك ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج قــات عــن طريــق البيــع‬\n‫فطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة وإلغــاء‬\n‫شــريحة االتصــال املســتخدمة يف الترويــج وإعــادة املبلــغ احلكومــي‬\n‫املفقود‪،‬حيــث مت االتصــال علــى املدعــى عليــه مــن قبــل املصــدر وطلــب‬\n‫منــه حزمــة قــات فطلــب مــن املصــدر احلضــور إلــى منزلــه ثــم جــرى بعــد‬\n‫ذلــك االســتالم والتســليم ثــم دخــل املدعــى عليــه املنــزل وأقفــل البــاب‬\n                                                                                  ‫‪404‬‬\n\f      ‫فتأجــل القبــض عليــه ويف يــوم آخــر قبــض علــى املدعــى عليــه وأثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات‬\n      ‫احملظــور وأنكــر املدعــى عليــه الدعــوى‪ ،‬حيــث إن بينــة املدعــي العــام‬\n      ‫شــهادة الشــهود ‪ .‬حكــم بــرد الدعــوى وقنــع املدعــى عليــه واعتــرض‬\n      ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬      ‫املدعــي العــام بــدون الئحــة ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪ 34187484‬وتاريــخ‬\n      ‫‪ 1434/04/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341000650‬وتاريــخ‬\n      ‫‪ 1434/04/23‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/04/29‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي العــام ‪.....‬املكلــف مــن‬\n      ‫مرجعــه باخلطــاب برقــم ‪.....‬يف ‪1430/5/8‬ه ـ وحضــر حلضــوره املدعــى‬\n      ‫عليــه ‪.....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ ).....‬وادعــى املدعــي‬\n      ‫العــام يف دعــواه احملــررة لدينــا أنــه يف متــام الســاعة الثالثــة عصــرا مــن‬\n      ‫يــوم اخلميــس املوافــق ‪1434/03/19‬ه ـ وأثنــاء توفــر معلومــات ملكافحة‬\n      ‫املخــدرات بخميــس مشــيط مــن أحــد مصادرهــا الســرية عــن قيــام املتهــم‬\n      ‫املذكــور بترويــج نبــات القــات مت االتصــال عليــه مــن قبــل املصــدر ومت‬\n      ‫علــى جوالــه رقــم (‪).....‬علــى مســمع مــن أفــراد الفرقــة وطلــب منــه حزمــة‬\n      ‫مــن نبــات القــات مببلغ(‪)300‬ريــال فطلــب من املصدر احلضــور إلى منزله‬\n      ‫ومت تكليــف أحــد األفــراد بالتنكــر ومرافقــة املصــدر ومت تزويدهــم‬\n      ‫مببلــغ حكومــي مرقــم وعنــد وصولهــم إلــى املنــزل خــرج عليهــم املتهــم‬\n\n‫‪405‬‬\n\f‫املذكــور وســلم املصــدر حزمــة ملفوفــة يف قطعــة قمــاش أخضــر بلــغ‬\n‫وزنهــا (‪)445‬جــم واســتلم املبلغ احلكومــي ودخل منزله وأغلق الباب ومت‬\n‫تأجيــل القبــض عليــه إلــى وقت الحق ويف اليــوم املوافق ‪1434/04/05‬هـ‬\n‫مت القبــض علــى املتهــم املذكــور وهــو خــارج مــن منزلــه وباســتجواب‬\n‫املتهــم املذكــور بعــد إحاطتــه بالتهــم املوجهــة لــه وبجهــة التحقيــق أقــر‬\n‫باســتعمال القــات احملظــور منــذ عــام وبتحليــل عينــة ممــا مت ضبطــه ثبــت‬\n‫احتواءهــا علــى القــات مبوجــب التقريــر الكيميائــي الشــرعي رقــم(‪).....‬‬\n‫لعــام الصــادر مــن مركــز الســموم والكيميــاء مبنطقــة عســير والقــات‬\n‫مــن املــواد املدرجــة باجلــدول رقــم(‪ )4‬فئــة (أ‪،‬ج) املــواد املخــدرة امللحقــة‬\n‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد انتهــى التحقيــق مــع‬\n‫املدعــى عليــه إلــى توجيــه االتهــام لــه بترويــج حزمــة نبــات قــات محظــور‬\n‫بلــغ وزنــه (‪445‬جــم) عــن طريــق البيــع واســتخدامه لــه يف الســابق وذلــك‬\n‫لألدلــة والقرائــن التالية‪-1:‬مــا جــاء يف محضــر اســتجوابه املنــوه عنــه‬\n‫علــى الصفحتــن رقــم(‪ )2-1‬مــن ملــف التحقيــق املرفــق علــى لفــة رقــم‬\n‫(‪ )13‬واملتضمــن اســتعماله للقــات يف الســابق ‪ -2‬مــا تضمنــه محضــر‬\n‫الشــراء املنــوه عنــه واملــدون علــى الصفحتــن رقمــي(‪ )12-2‬مــن ملــف‬\n‫االســتدالل املرفــق علــى اللفــة(‪ -3 )1‬مــا تضمنــه التقريــر الكيميائــي‬\n‫الشــرعي املنــوه عنــه برقــم (‪/629‬م) لعــام ‪1434‬ه ـ املرفــق لفــه(‪)7‬‬\n‫وبالبحــث عــن ســوابقه اتضــح عــدم وجــود ســوابق مســجلة علــى املدعــى‬\n‫عليــه وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم شــرعا ومعاقــب‬\n‫عليــه نظامــا وقــد أقــدم عليــه وهــم بكامــل أهليتــه املعتبــرة شــرعا لــذا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا‪ -1:‬قضــى بــه األمــر‬\n‫الســامي الكــرمي رقــم (‪ )59366‬وتاريــخ ‪1432/12/09‬ه ـ ‪ -2‬إلزامــه‬\n\n\n                                                                                      ‫‪406‬‬\n\f      ‫بدفــع قيمــة املبلــغ احلكومــي املفقــود والبالغ(‪)300‬ريــال ‪ -3‬إلغــاء‬\n      ‫الشــريحة رقــم (‪ ).....‬وعــدم صرفهــا لنفــس املســتخدم اســتنادا لتعميــم‬\n      ‫وزيــر الداخليــة رقــم(‪ )9798‬وتاريخ‪1428/02/10-9‬ه ـ هكــذا ادعــى‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه افــاد قائــا ماذكــره‬\n      ‫املدعــي العــام يف دعــواه مــن ترويجــي القــات املخــدر فغيــر صحيــح وامــا‬\n      ‫اجلــوال املذكــور يف الدعــوى فصحيــح أنــه عائــد لــي لكــن يتصــل علــى‬\n      ‫أشــخاص وال أعلــم مــن املتصــل هكــذا أجــاب وبعــرض إجابــة املدعــى‬\n      ‫عليــه علــى املدعــي العــام وســؤاله البينــة علــى صحــة دعــواه أفــاد أن لــدي‬\n      ‫بينــة ســأحضرها اجللســة القادمــة ورفعــت اجللســة وحــدد لــه موعــد يــوم‬\n      ‫االحد املوافق ‪1434/5/5‬هـ الســاعة العاشــرة اختتمت اجللســة الســاعة‬\n      ‫احلاديــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                       ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪ 34187484‬وتاريــخ‬\n      ‫‪ 1434/04/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341000650‬وتاريــخ‬\n      ‫‪ 1434/04/23‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/05/05‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة وفيهــا حضــر املدعــي العــام واملدعــي عليــه‬\n      ‫وبســؤال املدعــى العــام هــل أحضــر مــا اســتمهل مــن أجلــه أفــاد قائــل نعــم‬\n      ‫واحضــر لشــهادة كل مــن ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪.....‬مــن مواليــد عــام ‪1410‬ه ـ ويعمــل مبكافحــة املخــدرات مبنطقــة‬\n      ‫خميس مشــيط ومن ســكانها وبســؤاله عما لديه من شــهادة قال أشــهد‬\n      ‫بــاهلل العظيــم أنــه يف يــوم اخلميــس املوافــق ‪ 1434/3/19‬مت اإلتصــال‬\n\n\n‫‪407‬‬\n\f‫علــى املدعــى عليــه ‪ .....‬علــى جوالــه رقــم (‪ ).....‬مــن قبــل املصــدر ومت‬\n‫االنتقــال إلــى منزلــه الكائــن يف حــي ‪ .......‬يف ‪ .........‬وخــرج املدعــى عليــه‬\n‫ثــم دخــل املصــدر معــه داخــل احلــوش وخــرج املصــدر بحزمــة مــن القــات‬\n‫احملظــور علمــا انــه مت تفتيــش املصــدر قبــل نزولــه ولــم أرى االســتالم‬\n‫والتســليم للقــات احملظــور هكــذا شــهد وبعــرض شــهادة الشــاهد علــى‬\n‫املدعــى عليــه قــال أمــا الشــاهد فــا أعرفــه ولــم أشــاهده مــن قبــل لــذا‬\n‫جــرى تعديــل الشــاهد مــن قبــل كل مــن ‪.....‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪.....‬مــن مواليــد ‪1393‬ه ـ ويعمــل يف مبكافحــة املخــدرات‬\n‫بخميــس مشــيط و‪.....‬ســعودي مبوجــب الســجل املدنــي رقــم ‪.....‬مــن‬\n‫مواليــد ‪1407‬ه ـ يعمــل مبكافحــة املخــدرات بخميــس مشــيط وشــهدا‬\n‫بــان الشــاهد ثقــة عــدل مقبــول الشــهادة هكــذا شــهدا وبســؤال املدعــي‬\n‫العــام هــل لديــك مزيــد بينــة أفــاد قائــا ال ســوى مــا يف أوراق املعاملــة‬\n‫هكــذا أفــاد وللرجــوع إلــى أوراق املعاملــة رفعــت اجللســة وحــدد لهــم‬\n‫موعــد يــوم االثنــن املوافــق ‪1434/5/6‬ه ـ الســاعة العاشــرة أختتمــت‬\n‫اجللســة الســاعة العاشــرة وخمــس وأربعــن دقيقــة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                              ‫‪ 1434/05/05‬ه ـ‬\n‫احلمــدهلل وحــده وبعــد ويف هــذا اليــوم الثنــن املوافــق ‪1434/05/06‬ه ـ‬\n‫أفتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر املدعــي العــام وحضــر‬\n‫املدعــى عليــه وبعــد تأمــل الدعوى ودراســة أوراق املعاملــة وبالرجوع إليها‬\n‫لــم اجــد اعتــراف او اقــرار ان املدعــي قــام بترويــج القــات احملظــور لــذا‬\n‫وبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة وبعــد اإلطــاع علــى املعاملــة‬\n‫اخلاصــة بهمــا وبنــاء علــى إنــكار املدعــى عليــه دعــوى املدعــي العــام‬\n\n\n                                                                                        ‫‪408‬‬\n\f      ‫ودفــع بــإن اجلــوال الــذي مت التنســيق بــه يف شــراء احلبــوب احملظــورة لــه‬\n      ‫وقــت الشــراء وان الــذي يتصــل عليــه أشــخاص اليعــرف منهــم وبنــاء على‬\n      ‫شــهادة الشــاهد الغيــر موصلــة حيــث شــهد بأنــه لــم يشــاهد املدعــى عليــه‬\n      ‫وقــت إســتالم وتســليم القــات احملظــور وأنــه إمنــا كان التنســيق باجلــوال‬\n      ‫الــذي مت قبــض املدعــى عليــه وهــو بحوزتــه واحلضــور إلــى بيتــه ودخــول‬\n      ‫املصــدر احلــوش ولكــون املدعــي العــام ال بينــة لديــه ســوى مــا أحضــر‬\n      ‫و أوراق املعاملــة ولــم أجــد يف أوراق املعاملــة مــا يؤكــد اتهــام املدعــى‬\n      ‫عليــه ســوى شــهادة الشــاهد واإلتصــال باجلــوال الســيما أن مــن أوراق‬\n      ‫املعاملــة لــم يتضــح ان احلديــث احلاصــل هــو ترويــج القــات احملظــور وبنــاء‬\n      ‫علــى ان اليقــن القــوي ال يرتفــع بالشــك الضعيــف والثابــت بيقــن بــراءة‬\n      ‫(((و َمــا َي َّت ِبـ ُـع‬\n                           ‫املتهــم ألنهــا أصــل فــا تــزول براءتــه إال بيقــن ولقولــه تعالــى َ‬\n      ‫بــا‬                    ‫الـ ِّـق َش ـ ْيئًا ِإ َّن َّ َ‬\n            ‫الل َع ِليـ ٌـم ِ َ‬                            ‫الظـ َّـن َل ُي ْغ ِنــي مِ ـ َـن ْ َ‬\n                                                                                             ‫كث َُر ُهـ ْـم ِإ َّل َظ ًّنــا ِإ َّن َّ‬ ‫َأ ْ‬\n      ‫ـون)) وعــن عائشــة رضــي اهلل عنهــا قالــت‪ :‬قــال رســول اهلل صلــى‬                                                    ‫َي ْف َع ُلـ َ‬\n      ‫اهلل عليه وســلم ‪« :‬ادْ َرؤوا احلُدو َد عن املســلمني ما اســتطعتم‪ ،‬فإن كان‬\n      ‫لــه مخــرج‪ ،‬فخلــوا ســبيله‪ .‬فــإن اإلمــام أن يخطــئ يف العفــو‪ ،‬خيــر مــن أن‬\n      ‫يخطــئ يف العقوبــة» رواه الترمــذي مرفوع ـ ًا والقاعــدة الشــرعية تقــول‬\n      ‫اليقــن ال يــزول بالشــك واألصــل يف املتهــم البــراءة وبنــاء علــى انــه متــى‬\n      ‫تطــرق الشــك واالحتمــال إلــي قرائــن اإلدانــة وجــب احلكــم ببــراءة املتهــم‬\n      ‫لعــدم كفايــة األدلــة إذ الشــك يفســر ملصلحــة املتهــم وحيــث اليوجــد‬\n      ‫ســوابق مســجلة علــى املدعــى عليــه لذلــك كلــه فقــد رددت دعــوى‬\n      ‫املدعــى العــام وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى هــذا مــا‬\n      ‫ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه‬\n      ‫بــه وأمــا املدعــي العــام فقــرر املعارضــة وطلــب رفــع احلكــم لالســتئناف‬\n\n\n‫‪409‬‬\n\f‫بــدون الئحــة اعتراضيــة وأمــرت بتنظيــم القــرار الــازم لذلــك ورفــع‬\n‫كامــل اوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم واختتمــت‬\n‫اجللســة الســاعة العاشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/6‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط رقــم‬\n‫‪ 341000650‬وتاريــخ ‪1434/5/8‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ..... /‬رقــم ‪34207894‬‬\n‫وتاريــخ ‪1434/5/6‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ (...../‬ســعودي‬\n‫اجلنســية ) يف قضيــة ( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪410‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":404,"source_page_end":410,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d095c3f12f834ff61ece31a6f36c4f5546921ecc4ddde5e41327917116d02848","normalized_text_hash":"399ae251eb4299f3892380776b03a43bb330c506dbd36e1384f62faf986d9a2b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p404-34207894"},{"id":"dffa5fa4-2a4c-5797-b4ea-509a41f78380","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -املدعى عليه أجنبي يتحدث العربية -عدم مصادرة املبلغ -األصل فيما بيد املسلم فهو ملكه.","document_number":"34223849","case_number":"34203476","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة برجال أملع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -املدعى عليه أجنبي يتحدث العربية -عدم مصادرة املبلغ -األصل فيما بيد املسلم فهو ملكه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34223849:‬تاريخه‪1434/5/27:‬هـ‬\n                        ‫رقم الدعوى‪34203476:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34324940‬تاريخه‪1434/07/17:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬نقــل بقصــد الترويــج ‪ -‬قــات ‪ -‬املدعــى عليــه أجنبــي يتحــدث‬\n       ‫العربيــة ‪ -‬عــدم مصــادرة املبلــغ ‪ -‬األصــل فيمــا بيــد املســلم فهــو ملكــه‪.‬‬\n\n\n\n\n      ‫‪ -1‬جــاء يف مطالــب أولــي النهــى (‪ )67/4‬مــا نصــه (األصــل فيمــا بيــد‬\n                                                            ‫املســلم أنــه ملكــه ) ‪.‬‬\n                                                        ‫‪ -2‬األصل براءة الذمة ‪.‬‬\n      ‫‪ -3‬وملــا جــاء يف املــادة الثالثــة بفقرتهــا الثالثــة مــن نظــام املخــدرات‬\n      ‫الســابق يف القــرار رقــم (‪ )11‬تاريــخ ‪1374/2/1‬ه ـ ونصهــا‪(:‬كل شــخص‬\n      ‫مــن غيــر الصيادلــة واملرخــص لهــم باالجتــار باجلواهــر املخــدرة ثبتــت‬\n      ‫حيازتــه لشــيء مــن املخــدرات أو توســط يف تصريفهــا بالبيــع أو اإلرســال‬\n      ‫أو اإلهــداء أو النقــل مــن جهــة أخــرى يعاقــب بالســجن ملــدة خمــس‬\n      ‫ســنوات ويغــرم بغرامــة ماليــة قدرهــا عشــرة آاللف ريال عربي ســعودي)‪.‬‬\n       ‫‪ -4‬املادة الثالثة من القرار الوزاري رقم (‪ )2057‬وتاريخ ‪1404/5/26‬هـ‪.‬‬\n      ‫‪ -5‬املادة الرابعة من القرار الوزاري رقم (‪ )2057‬وتاريخ ‪1404/5/26‬هـ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات مقابــل مبلــغ مالــي‬\n      ‫بقصــد االجتــار وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n\n‫‪411‬‬\n\f‫تعزيريــة واحلكــم بإبعــاده عــن البــاد ‪،‬حيــث مت االشــتباه مــن مقبــل‬\n‫فرقــة الضبــط األمنــي بشــاحنة يقودهــا املدعــى عليــه وبتفتيــش ضبــط‬\n‫معــه مبلــغ مالــي وبتفتيشــه الشــاحنة ضبــط بهــا كميــة مــن نبــات يشــتبه‬\n‫أن يكــون نبــات القــات وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n‫العينــة املضبوطــة لنبــات القــات احملظــور ‪،‬صــادق املدعــى عليــه علــى‬\n‫الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بســجن املدعــى عليه‬\n‫ملــدة ســنتني وبغرامــة ماليــة قدرهــا ألــف ريــال وبإبعــاده عــن اململكــة‬\n‫بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه وأن ال يســمح لــه بالعــودة‬\n‫إليهــا فيمــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة ‪،‬ســقوط طلــب‬\n‫املدعــي العــام بطلــب مصــادرة املبلــغ املذكــور يف الدعــوى و قنــع املدعــى‬\n‫‪،‬وصــدق احلكــم مــن‬ ‫عليــه باحلكــم واعتــرض املدعــي العــام بالئحــة ُ‬\n                                                       ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬رئيــس احملكمــة العامــة برجــال أملــع‬\n‫وبناء على املعاملة احملالة لنا برقم ‪ 34203476‬وتاريخ ‪1434/05/04‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 341085145‬وتاريــخ ‪ 1434/05/04‬ه ـ‬\n‫ففي يوم الثالثاء املوافق‪ 1434/05/21‬هـ افتتحت اجللســة الســاعة ‪00‬‬\n‫‪ 12 :‬وكانــت املعاملــة قــد وردتنــا مــن رئيــس دائــرة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة ‪ .....‬برقــم‪.....‬يف ‪1434/5/1‬ه وعليــه حضــر املدعــي‬\n‫العــام بدائــرة التحقيــق واالدعــاء العــام مبحافظــة ‪..... ....‬لتمثيــل االدعــاء‬\n‫العــام والقيــام باعمــال املرافعــة اثنــاء اجللســات واملكلــف باالدعــاء العــام‬\n‫مبوجــب خطــاب رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة ‪....‬‬\n\n                                                                                       ‫‪412‬‬\n\f      ‫رقــم ‪.....‬يف ‪1434/3/12‬ه وادعــى علــى احلاضــر معــه ‪.....‬باكســتاني‬\n      ‫اجلنســية مبوجــب االقامــة رقــم ‪.....‬قائــا يف دعــواه عليــه بصفتــي مدعيـ ًا‬\n      ‫عام ـ ًا بدائــرة التحقيــق واالدعــاء العــام مبحافظــة (‪ )...‬أدعــى علــى ‪...../‬‬\n      ‫‪.....‬باكســتاني اجلنســية برخصــة اإلقامــة رقــم (‪ ).....‬البالــغ مــن العمــر‬\n      ‫(‪ )37‬عام ـ ًا ســائق شــاحنة متعلــم مســلم يتحــدث العربيــة‪ -‬املقبــوض‬\n      ‫عليــه بتاريــخ ‪1434/3/9‬ه ـ واملــودع بوحــدة ســجن محافظــة ‪ ....‬مبوجــب‬\n      ‫أمــر متديــد التوقيــف رقــم (‪ ).....‬وتاريــخ ‪1434/3/23‬ه ـ اســتناد ًا للمــادة‬\n      ‫(‪ )114‬مــن نظــام اإلجــراءات اجلزائيــة حيــث أنــه عنــد الســاعة السادســة‬\n      ‫مــن صبــاح يــوم االثنــن املوافــق ‪1434/3/9‬ه ـ مت االشــتباه مــن قبــل فرقة‬\n      ‫الضبــط األمنــي مبركــز ‪.....‬بســيارة شــاحنه نــوع ( ‪ ).......‬اللــون (أزرق)‬\n      ‫صنــع عــام (‪2000‬م) حتمــل اللوحــة رقــم (‪ ).....‬بقيــادة املدعــى عليــه‬\n      ‫وبتفتيشــه ضبــط معــه مبلــغ مالــي قــدره( ‪ )13000‬ثالثــة عشــر ألــف‬\n      ‫ريــال وبتفتيــش الشــاحنة ضبــط بهــا (‪ )380‬ثالثمائــة وثمانــون حزمــة‬\n      ‫يشــتبه أنهــا مــن نبــات القــات احملظــور تــزن(‪ )115‬مائــة وخمســة عشــر‬\n      ‫كيلــو مخبــأة بداخــل صهريــج الديــزل وبالــدرج اجلانبــي للتيــدر وقــد‬\n      ‫أثبــت التقريــر الكيمائــي الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1434/4/22‬ه ـ‬\n      ‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n      ‫مبنطقــة عســير أن العينــة إيجابيــة لنبــات القــات وهــو مــن املــواد املدرجــة‬\n      ‫بجــداول املخــدرات واملؤثــرات العقليــة باجلــدول (‪ )4‬الرابــع الفئــة (‪)5‬‬\n      ‫اخلامســة املرفــق بتعميــم صاحــب الســمو امللكــي النائــب الثانــي لرئيــس‬\n      ‫مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )74831‬وتاريــخ ‪1431/7/9‬ه ـ‬\n      ‫وباســتجوابه املدعــى عليــه ‪/‬أقــر بنقــل (‪ )380‬ثالثمائــة وثمانــون حزمــة‬\n      ‫تــزن(‪ )115‬مائــة وخمســة عشــر كيلــو مــن نبــات القــات احملظــور مــن‬\n\n\n‫‪413‬‬\n\f‫محافظــة ‪ ....‬إلــى محافظــة ‪ ......‬مقابــل (‪ )7000‬ســبعة آالف وانتهــى‬\n‫التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه ‪/‬بنقــل (‪ )380‬ثالثمائــة‬\n‫وثمانــون حزمــة تــزن(‪ )115‬مائــة وخمســة عشــر كيلــو مــن نبــات القــات‬\n‫احملظــور مقابــل مبلــغ مالــي بقصــد االجتــار وذلــك لألدلــة والقرائــن‬\n‫التاليــة‪-1 -:‬ماتضمنتــه محضــر القبــض والتفتيــش املــدون علــى‬\n‫الصفحتــن رقــم (‪ )7.6‬مــن تقريــر األحــوال األمنيــة املوحــد لفــة رقــم (‪)2‬‬\n‫‪-2‬ماتضمنــه إقــراره املنــوه عنــه واملــدون علــى الصفحة رقــم (‪ )5‬من ملف‬\n‫ضبــط إجــراءات قضيــة مخــدرات لفــة رقــم (‪-3)17‬ماتضمنتــه التقريــر‬\n‫الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪)25‬وبالبحــث عــن‬\n‫ســوابقه أتضــح عــدم وجــود ســوابق مســجلة عليــه وحيــث إن مــا أقــدم‬\n‫عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة فعــل محــرم شــرع ًا ومجــرم‬\n‫نظام ـ ًا ومعاقــب عليــه مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬وتاريــخ‬\n‫‪1374/2/1‬ه بعقوباتــه األصليــة والتكميليــة لــذا اطلــب إثبــات مــا اســند‬\n‫إليــه واحلكــم مبــا يلــي ‪-1:‬بعقوبــة تعزيريــة وفقــا ملــا تضمنتــه املــادة (‪)3‬‬\n‫الثالثــة مــن القــرار املشــار اليــه لقــاء نقــل (‪)380‬ثالثمائــة وثمانــون حزمــة‬\n‫تــزن (‪)115‬مائــة وخمســة عشــر كيلــو مــن نبــات القــات احملظــور مقابــل‬\n‫مبلــغ مالــي بقصــد االجتــار ‪-2‬احلكــم بإبعــاده عــن البــاد بعــد تنفيــذ‬\n‫العقوبــة بحقــه وفقــا ملــا تضمنتــه الفقــرة (ج) مــن املــادة (‪ )4‬الرابعــة مــن‬\n‫القــرار املشــار إليــه ‪-3‬مصــادرة املبلــغ املالــي املضبــوط وقــدره (‪)13000‬‬\n‫ثالثــة عشــر ألــف ريــال كونــه مت إخفــاء حقيقتــه ولم يثبت جلهــة التحقيق‬\n‫ملكيــة املدعــى عليــه لــه هكــذا ادعــى وبســؤال املدعى عليــه عن دعوى‬\n‫املدعــي العــام أقــر بجميــع مــا جــاء فيهــا وقيامــه بنقــل مــا بلــغ وزنــه مائــة‬\n‫وخمســة عشــر كيلــو مــن نبــات القــات مبلــغ قــدره ســبعة اآلف ريــال لــم‬\n\n\n                                                                                            ‫‪414‬‬\n\f      ‫تقبــض بقصــد االجتــار هكــذا أجــاب كمــا جــرى ســؤال املدعــى عليــه‬\n      ‫عــن املبلــغ املضبــوط عنــد القبــض وقــدره ثالثــة عشــر ألــف ريــال فأجــاب‬\n      ‫قائ ـاً‪ :‬هــذا املــال يعــود لــي خاصــة وهــو حصيلــة ملجمــوع رواتبــي للعــام‬\n      ‫املاضــي وليــس لــه عالقــة بنقــل القــات هكــذا أجــاب وبســؤال املدعــي‬\n      ‫العــام عــن بينتــه حيــال مــا ذكــر عــن هــذا املــال أجــاب قائــا ليــس لــدي‬\n      ‫ســوى مــا يف أوراق املعاملــة هكــذا أجــاب وبالرجــوع إلــى أوراق املعاملــة‬\n      ‫أطلعــت علــى التقريــر الكيميائــي رقــم ‪.....‬وتاريــخ ‪1434/3/22‬ه‬\n      ‫املتضمــن إيجابيــة العينــة املرســلة لنبات القــات كما اطلعت على كرت‬\n      ‫ســوابق املدعــى عليــه يف املعاملــة فوجدتــه يخلــو مــن الســوابق وبعــرض‬\n      ‫مــا جــاء يف التقريــر الكيميائــي علــى املدعــى عليــه صــادق علــى مــا جــاء‬\n      ‫فيــه كمــا أطلعــت علــى قــرار اعتــراف املدعــى عليــه يف دفتــر التحقيــق‬\n      ‫صفحــة رقــم ( ‪ )5‬واملتضمــن أقــرر انــا املدعــو ‪.....‬باكســتاني اجلنســية‬\n      ‫مقيــم مبوجــب اإلقامــة رقــم ‪.....‬وتاريــخ ‪1432/12/27‬ه ـ مصدرهــا‬\n      ‫اخلــرج وانــا بكامــل بكامــل اهليتــي املعتبــرة شــرعا حيــث ادلــي مبــا‬\n      ‫يلــي ‪:‬مت القبــض علــي مــن قبــل نقطــة امــن ‪ .....‬حيــث كان بقيادتــي‬\n      ‫ســيارة ‪ ....‬تريــا موديــل ‪2000‬رقــم اللوحة‪.....‬تعــود ملكيتهــا للمدعــو‬\n      ‫‪ .....‬وبتفتيــش الســيارة عثــر علــى كميــة مــن نبــات القــات كانــت مخبــأه‬\n      ‫يف تانكــي الديــزل يف الــدرج اجلانبــي للتديــر بلــغ عددهــا ‪ 380‬ثالثمائــة‬\n      ‫وثمانــن حزمــة اتضــح لــي أنهــا تــزن ‪ 155‬مائــة وخمســة عشــر كيلــو‬\n      ‫جرام ـ ًا حيــث إن هــذه الكميــة عائــدة لشــخص باكســتاني ذكرتــه‬\n      ‫جلهــة التحقيــق قــد اتفقــت معــه علــى نقلهــا مــن محافظــة‪ ....‬الــى محافظــة‬\n      ‫‪ ....‬مقابــل مبلــغ مالــي قــدره ســبعة االف ريــال ســعودي لــم أســتلم مــن‬\n      ‫املبلــغ أي شــيء وحيــث ان مالــك الســيارة ليــس لــه أي علــم او عالقــة‬\n\n\n‫‪415‬‬\n\f‫بكميــة القــات املذكــورة وقــد اســتلمت الســيارة مــن شــخص ســوري‬\n‫يعمــل مــع مالــك الســيارة وليــس لــه أي عالقــة بكميــة القــات و حيــث‬\n‫ان املبلــغ الــذي ضبــط بحوزتــي وقــدره ثالثــة عشــر الــف ريــال ليــس لــه‬\n‫عالقــة بكميــة القــات املذكــورة وليــس مــن عائــدات النقل للقــات او أي‬\n‫مخــدرات حيــث ان هــذا اول مــرة اقــدم علــى مثــل هــذا العمــل وعلــى ذلــك‬\n‫اقــرر واوقــع واصــادق وبعرضــه علــى املدعــى عليــه قــال هــذا اإلقــرار‬\n‫صحيــح وليــس فيــه مــا يخالــف مــا ذكــرت يف اإلجابــة علــى الدعــوى‬\n‫هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــرا إلــى‬\n‫أن املدعــى عليــه أقــر بقيامــه بنقــل القــات باملبلــغ املذكــور يف الدعــوى‬\n‫ونظــرا إلــى أن األصــل يف املســلم أنــه ميلــك مــا كان حتــت يــده مــن مــال‬\n‫ونحــوه إال إذا ثبــت خــاف ذلــك بالبينــة الشــرعية أو مبــا أقــر بــه املكلف‬\n‫علــى نفســه وذلــك ألن األصــل بــراءة الذمــة جــاء يف مطالــب أولــي النهــى‬\n‫(‪ )67/4‬مــا نصــه‪( :‬األصــل فيمــا بيــد املســلم أنــه ملكــه ) وملــا جــاء يف‬\n‫املــادة الثالثــة بفقرتهــا الثالثــة مــن نظــام املخــدرات الســابق يف القــرار‬\n‫رقــم (‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ ونصهــا مــا يلــي‪(:‬كل شــخص مــن‬\n‫غيــر الصيادلــة واملرخــص لهــم باإلجتــار باجلواهــر املخــدرة ثبتــت حيازتــه‬\n‫لشــيء مــن املخــدرات أو توســط يف تصريفهــا بالبيــع أو اإلرســال أو‬\n‫اإلهــداء أو النقــل مــن جهــة أخــرى يعاقــب بالســجن ملــدة خمــس ســنوات‬\n‫ويغــرم بغرامــة ماليــة قدرهــا عشــرة اآللــف ريــال عربــي ســعودي)‪.‬ونظرا‬\n‫إلــى مــا جــاء يف القــرار الــوزاري رقــم (‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ‬\n‫املتضمــن أن عقوبــات الســجن والغرامــة الــواردة بالقــرار رقــم( ‪)11‬‬\n‫لعــام ‪1374‬ه ـ هــي احلــد األعلــى ملــا ميكــن للجهــة املختصــة احلكــم بــه‬\n‫علــى املتهــم وعلــى أال تقــل يف عقوبــة االجتــار باملــواد املخــدرة بالبيــع أو‬\n\n\n                                                                                       ‫‪416‬‬\n\f      ‫اإلهــداء أو اإلرســال أو النقــل مــده ال تقــل عــن ســنتني و ال تتجــاوز خمــس‬\n      ‫ســنوات كمــا يف املــادة الثالثــة مــن هــذا القــرار وبنــاء علــى مــا جــاء يف‬\n      ‫املــادة الرابعــة مــن القــرار املشــار إليــه والتــي تتضمــن إبعــاد األجنبــي عــن‬\n      ‫البــاد بعــد تنفيــذ العقوبــة بحقــه وفــق مــا هــو مفصــل فيهــا‪ .‬وجلميــع مــا‬\n      ‫ســبق قــررت مــا يلــي ألجــل احلــق العــام ‪:‬أوالً‪ /‬ســجن املدعــى عليــه ملــدة‬\n      ‫ســنتني مــن تاريــخ إيقافــه يف هــذه القضيــة‪ .‬ثانيــا‪ /‬غرامــة ماليــة قدرهــا‬\n      ‫ألــف ريــال ‪.‬ثالثــا‪ /‬إبعــاد املدعــى عليــه عــن اململكــة بعــد تنفيــذ العقوبــة‬\n      ‫احملكــوم بهــا عليــه وأن ال يســمح لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح‬\n      ‫بــه تعليمــات احلــج والعمــرة رابع ـاً‪ /‬ســقوط طلــب املدعــي العــام بطلــب‬\n      ‫مصــادرة املبلــغ املذكــور يف الدعــوى ملــا ســبق بيانــه وبعــرض احلكــم‬\n      ‫علــى املدعــى عليــه قــرر قناعتــه بــه وقــرر املدعــي العــام اعتراضــه وطلــب‬\n      ‫االســتئناف ومتكينــه مــن تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وصلــى‬\n                            ‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/5 /21‬ه‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة ‪ ......‬املكلــف برقــم‬\n      ‫‪ 341085145‬وتاريــخ ‪1434 /8/ 28‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة رئيــس احملكمــة الشــيخ ‪..... /‬برقــم ‪ 34223849‬وتاريــخ ‪/ 27‬‬\n      ‫‪1434 / 5‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪ -..... /‬باكســتاني‬\n      ‫اجلنســية ‪ -‬يف قضيــة ( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪417‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":411,"source_page_end":417,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1840d1e9d6892bb17ead9613d874069c6f28d8723b58205d33e6a365739a71f5","normalized_text_hash":"d7b2eebe3a367037d1c21d4057350f6c5ee4e551cba830cd2d2f457310dc57b6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p411-34223849"},{"id":"e26dc64f-eda3-5a07-be75-2b28c2fc59f7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -هروب من رجال األمن - التعزير بالسجن واجللد -شبهة ترويج -تعزير للشبهة.","document_number":"34243861","case_number":"34269340","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/18","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -هروب من رجال األمن - التعزير بالسجن واجللد -شبهة ترويج -تعزير للشبهة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34243861:‬تاريخه‪1434/6/18 :‬هـ‬\n                  ‫رقم الدعوى‪34269340:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34267598‬تاريخه‪1434/07/15:‬هـ‬\n\n\n‫مخــدرات ‪ -‬نقــل بقصــد الترويــج‪ -‬قــات ‪ -‬هــروب مــن رجــال األمــن ‪-‬‬\n        ‫التعزيــر بالســجن واجللــد ‪ -‬شــبهة ترويــج ‪ -‬تعزيــر للشــبهة‪.‬‬\n\n\n\n\n                 ‫املادة الرابعة من القرار الوزاري رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد الترويــج‬\n‫وصــدم ســيارة الدوريــة األمنيــة وهروبــه مــن رجــال األمــن ‪،‬حيــث كان‬\n‫يقــود ســيارة فطلبــت منــه الدوريــة األمنيــة التوقــف فلــم يتوقــف وقــام‬\n‫بصــدم ســيارة الدوريــة والذ بالفــرار وبتفتيــش الســيارة عثــر علــى نبــات‬\n‫القــات ثــم قــام املدعــى عليــه بتســليم نفســه وطلــب املدعــي العــام إثبــات‬\n‫مــا أســند إليــه واحلكــم بتعزيــره لقــاء هروبــه مــن رجــال األمــن وصدمــه‬\n‫الدوريــة وأثبــت التقريــر الكيميائــي إيجابيــة العينــة املضبوطــة لنبــات‬\n‫القــات احملظــور واعتــرف املدعــى عليــه بحيــازة القات بقصد االســتعمال‬\n‫الشــخصي وصــدم الدوريــة األمنيــة والهــروب مــن رجــال األمــن وأنكــر‬\n‫الترويــج ‪،‬وملــا كانــت بينــة املدعــي العــام علــى الترويــج كبــر كميــة‬\n‫القــات ‪ ،‬مت تعزيــره بالســجن واجللــد وصــرف النظــر عــن طلــب املدعــي‬\n‫العــام مبعاقبتــه وفــق املــادة الثالثــة مــن القــرار املشــار إليــه لعــدم وجــود‬\n\n                                                                                          ‫‪418‬‬\n\f      ‫البينــة علــى الترويــج وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                            ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬   ‫الئحــة ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34269340‬وتاريــخ ‪ 1434/06/12‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341416140‬وتاريــخ ‪ 1434/06/12‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافق‪1434/06/17‬هـ افتتحت اجللســة الســاعة ‪09 : 45‬وفيها‬\n      ‫حضــر املدعــي العــام ‪.....‬واملكلــف بحضــور اجللســات باخلطــاب رقـ ــم (‬\n      ‫‪ ).....‬يف ‪1433/3/22‬ه ـ وادعــى علــى احلاضــر معــه باملجلــس الشــرعي‬\n      ‫الســجني ‪..... /‬ســعودي اجلنســية بالســجل املدنــي رقــم (‪ ).....‬قائــا يف‬\n      ‫دعــواه ‪ :‬انــه بتاريــخ ‪1434/3/18‬ه ـ وأثنــاء قيــام دوريــة محافظــة أحــد‬\n      ‫املســارحة بواجبهــا امليدانــي يف احملافظــة مت مشــاهدة ســيارة مــن‬\n      ‫نــوع ســنة الصنــع ‪ 2012‬رقــم اللوحــة (‪ ).....‬قادمــة مــن قريــة ‪.....‬عائــدة‬\n      ‫ملكيتهــا ل‪(.....‬لــم يوجــه لــه االتهــام وســلمت لــه) فتــم التأشــير لقائدهــا‬\n      ‫بالوقــوف فلــم يتوقــف فتــم مطاردتــه مــن قبــل الدوريــة وقــام بصــدم‬\n      ‫ســيارة الدوريــة وعندهــا قــام بتــرك الســيارة والذ بالفــرار (فــرزت لذلــك‬\n      ‫أوراق مســتقلة) وبتفتيشــها عثــر بهــا علــى كميــة مــن نبــات القــات‬\n      ‫احملظــور بلــغ وزنهــا(‪19 . 750‬كجــم) تســعة عشــر كيلــو وســبعمائة‬\n      ‫وخمســن جرام ـ ًا ‪ ،‬مبوجــب التقريــر الكيميائــي الشــرعي رقــم (‪.....‬‬\n      ‫لعــام ‪1434‬هــ) الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبية‬\n      ‫الشــرعية بجــازان ‪ ،‬وبتاريــخ ‪1434/5/18‬ه ـ قــام املتهــم املذكــور‬\n\n‫‪419‬‬\n\f                              ‫بتســليم نفســه ملكافحــة املخــدرات بصامطــة‪.‬‬\n‫وبإســتجواب املدعــى عليــه والتحقيــق معــه أســفر التحقيــق عــن توجيــه‬\n‫االتهــام إليــه بنقــل هــذه الكميــة مــن نبــات القــات احملظــور بقصــد‬\n‫الترويــج وبصدمــة لســيارة الدوريــة الرســمية واإلضــرار بهــا وهروبــه مــن‬\n‫رجــال األمــن وذلــك لألدلــة املرفقــة بــأوراق القضيــة ‪ .‬وحيــث إن مــا أقــدم‬\n‫عليــه املتهــم املذكــور فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب‬\n‫قــرار مجلــس الــوزراء رقــم (‪ )11‬لعام‪1374‬ه ـ ومــا حلــق بــه تعديــات فإنــه‬\n‫يتعــن إحالتــه إلــى احملكمــة اجلزائيــة اســتنادا للمادتــن (‪ 126‬ـ ‪)128‬‬\n                      ‫مــن نظــام اإلجــراءات اجلزائيــة وذلــك لطلــب مــا يلــي‪:‬‬\n‫‪/1‬إثبــات إدانتــه مبــا اســند إليــه واحلكــم بتعزيــره يف ضــوء املــادة‬\n‫(الثالثــة) مــن القــرار املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي‬\n                                      ‫رقــم (‪ )59633‬وتاريخ‪1432/12/9‬ه ـ‬\n‫‪2‬ـ احلكــم بتعزيــره شــرع ًا هروبــه مــن رجــال األمــن ‪3 .‬ـ احلكــم بتعزيــره‬\n‫شــرع ًا لقــاء صدمــه لســيارة الدوريــة الرســمية واإلضــرار بهــا مــع تشــديد‬\n‫العقوبــة عليــه لقــاء ذلــك‪ .‬وبســؤال املدعــى عليــه أجــاب قائــا ‪ :‬أعتــرف‬\n‫بالقبــض علــي بتاريــخ ‪1434/3/18‬ه ـ وبحوزتــي بداخــل الســيارة التــي‬\n‫كانــت بقيادتــي والتــي لــذت منهــا بالفــرار أثنــاء القبــض كميــة مــن‬\n‫نبــات القــات احملظــور بلــغ وزنهــا (‪19 . 750‬كجــم) تســعة عشــر كيلــو‬\n‫وســبعمائة وخمســن جــرام لغــرض االســتعمال الشــخصي وأنكــر‬\n‫حيازتــي لهــا لغــرض الترويــج وأعتــرف بقيامــي بصــدم الدوريــة وهروبــي‬\n‫مــن رجــال األمــن أثنــاء القبــض علــي بهــذا أجــاب ‪ ،‬ســألت املدعــى العــام‬\n‫هــل لديــه بينــة علــى صحــة دعــواه ضــد املدعــى عليــه يف احليــازة بقصــد‬\n‫الترويــج فقــال ليــس لــدي بينــة ســوى كبــر حجــم الكميــة ومــا جــاء‬\n\n\n                                                                                        ‫‪420‬‬\n\f      ‫بــأوراق القضيــة ‪ ،‬وباإلطــاع علــى أوراق القضيــة وجــد ضمنهــا التقريــر‬\n      ‫الكيميائــي الشــرعي رقــم (‪.....‬لعــام ‪1434‬هــ) واملتضمــن ثبــوت إيجابيــة‬\n      ‫العينــة املرســلة مــن الكميــة لنبــات القــات احملظــور ‪ ،‬كمــا وجــد‬\n      ‫كــرت بصمــات املدعــى عليــه واملتضمــن وجــود ســابقتني مســجلة عليــه‬\n      ‫وهــى‪1 ( :‬ـ اســتعمال املخــدرات ومقاومــة رجــال األمــن وهــروب مــن‬\n      ‫الســلطة وترويــج املخــدرات ـ ـ و‪2‬ـ حيــازة املخــدرات ) وقــد صــادق عليهــا‪.‬‬\n      ‫وعليــه فبنــاء علــى ســماع الدعــوى واإلجابــة وعــدم وجــود بينــة للمدعــي‬\n      ‫العــام علــى صحــة دعــواه ضــد املدعــى عليــه يف حيازتــه لهــذه الكميــة‬\n      ‫لغــرض الترويــج فلــم يثبــت لــدي ذلــك شــرعا وصرفــت النظــر عــن طلبــه‬\n      ‫تعزيــر املدعــى عليــه وفــق املــادة ( الثالثــة ) مــن القــرار الــوزاري رقــم ( ‪11‬‬\n      ‫) للعــام ‪1374‬ه ـ ـ وثبــت لــدي شــرعا إدانــة املدعــى عليــه ‪..... /‬بالقبــض‬\n      ‫عليــه وبحوزتــه بداخــل الســيارة التــي كانــت بقيادتــه كميــة مــن نبــات‬\n      ‫القــات احملظــور بلــغ وزنهــا ( ‪19 . 750‬كجــم ) تســعة عشــر كيلــو‬\n      ‫وســبعمائة وخمســون جــرام لغــرض اإلســتعمال الشــخصي ويســتحق‬\n      ‫التعزيــر علــى ذلــك وفــق املــادة ( الرابعــة ) مــن القــرار الــوزاري رقــم ( ‪11‬‬\n      ‫) لعــام ‪1374‬ه ـ لــذا فقــد حكمــت بتعزيــره بالســجن ملــدة ثمانيــة عشــر‬\n      ‫شــهرا اعتبــارا مــن تاريــخ دخولــه الســجن ( حيــث أنــه قبــض عليــه بتاريــخ‬\n      ‫‪1434/5/18‬هـ ) ‪ ،‬ونظرا لكبر حجم الكمية تتوجه إليه الشــبهة يف‬\n      ‫احليــازة بقصــد الترويــج ولهــذه الشــبهة ولهروبــه مــن رجــال األمــن وقيامــه‬\n      ‫بصــدم الدوريــة حكمــت بتعزيــره بالســجن ملــدة ســبعة أشــهر إضافــة ملــا‬\n      ‫صــدر بحقــه مــن ســجن أعــاه و جلــده مائتــن جلــدة علنــا علــى أربــع‬\n      ‫دفعــات كل دفعــة خمســون جلــدة بينهــا وبــن التــي تليهــا خمســة عشــر‬\n      ‫يومــا بذلــك حكمــت وأفهمــت املدعــى عليــه باحلكــم فقــرر القناعــة‬\n\n\n‫‪421‬‬\n\f‫وقــرر املدعــي العــام معارضتــه وطلــب رفــع احلكــم حملكمــة االســتئناف‬\n‫دون الئحــة اعتراضيــة وبــه حــرر يف ‪1434/6/17‬ه ـ وصلــى اهلل علــى‬\n                               ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n‫‪ 341416140‬وتاريــخ ‪1434/6/24‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 34243861‬وتاريــخ‬\n‫‪1434/6/18‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪..... /‬يف قضيــة‬\n‫(قــات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪422‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":418,"source_page_end":422,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fd577e18864dcc6ee99288cfa6004b7607a0cc8f1988340e240a6e62c57522ea","normalized_text_hash":"59278aaa6b5417d6d45c8b764dbb0b695d868aec344fa52a73a4a9e328f35842","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p418-34243861"},{"id":"e5a66014-046b-5c68-8932-210f1a1aab0f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج مادة الكوكاين -حيازة حشيش بقصد التعاطي -هروب من الفرقة القابضة -تستر -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملصادرة واملنع من السفر والغرامة.","document_number":"3427326","case_number":"34297291","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/19","year":"1434","subject":"مخدرات -ترويج مادة الكوكاين -حيازة حشيش بقصد التعاطي -هروب من الفرقة القابضة -تستر -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملصادرة واملنع من السفر والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3427326 :‬تاريخه ‪1434/7/19 :‬هـ‬\n                       ‫رقم الدعوى ‪34297291 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34375336‬تاريخه‪1434/12/02:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج مــادة الكوكايــن ‪ -‬حيــازة حشــيش بقصد التعاطي‬\n      ‫‪ -‬هــروب مــن الفرقــة القابضــة ‪ -‬تســتر‪ -‬إقــرار‪ -‬إقامــة حــد املســكر علــى‬\n      ‫متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واجللــد واملصــادرة واملنــع مــن‬\n                                                                   ‫الســفر والغرامة‪.‬‬\n\n\n\n             ‫‪ .1‬املادة ( ‪ ) 38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n             ‫‪ .2‬املادة ( ‪ ) 53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n             ‫‪ .3‬املادة ( ‪ ) 56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج مــادة الكوكايــن‪،‬‬\n      ‫وهروبــه مــن الفرقــة القابضــة وتســتره علــى مصــدر مــا مت ضبطــه‬\n      ‫معــه ‪ ،‬حيــث ورد بــاغ للجهــة األمنيــة مــن أحــد املصــادر عــن قيــام‬\n      ‫املدعــى عليــه بترويــج مــادة الكوكايــن ‪،‬واســتعد املصــدر وهــو أحــد‬\n      ‫العاملــن يف إدارة املكافحــة باإلطاحــة بــه ‪ ،‬ومت تزويــده باملبلــغ املرقــم‬\n      ‫وقــدره ألفــي ريــال؛ ليقــوم بعمليــة الشــراء‪ ،‬واتفــق علــى املــكان‪ ،‬وســلم‬\n      ‫املدعــى عليــه املصــدر كيــس نايلــون بداخلــه مــادة يشــتبه أن تكــون‬\n      ‫مــن الكوكايــن املخــدر ووزنهــا جرامــا واحــدا وأربعــة أعشــار اجلــرام‪،‬‬\n\n\n‫‪423‬‬\n\f‫واســتلم املذكــور مــن املصــدر املبلــغ املرقــم ثــم مت القبــض عليــه‪ ،‬وعثــر‬\n‫معــه علــى كيــس نايلــون فيــه حبــة بيضــاء اللــون مكســورة نصفــن‬\n‫حتمــل عالمــة الكبتاجــون‪ ،‬كمــا عثــر معــه علــى قطعــة ســوداء اللــون‬\n‫يشــتبه أن تكــون مــن احلشــيش‪ ،‬بلــغ وزنهــا ُعشــر اجلــرام ‪،‬و عثــر‬\n‫معــه علــى املبلــغ املرقــم وقــدره ألفــي ريــال ‪،‬و عثــر معــه علــى اجلــوال‬\n‫املســتخدم يف الترويــج‪ ،‬كمــا عثــر معــه بالســيارة علــى علبــة دخــان‬\n‫بداخلهــا ســيجارة ملفوفــة يشــتبه أن تكــون مخلوطــة مبــادة احلشــيش‬\n‫جرامــا واحـ ًـدا وثالثــة أعشــار اجلــرام وطلــب املدعــي‬\n                                                       ‫ً‬      ‫املخــدر‪ ،‬بلــغ وزنهــا‬\n‫العــام تعزيــر املدعــى عليــه بالســجن و اجللــد واملنــع مــن الســفر و الغرامــة‬\n‫ومصــادرة اجلــوال و إلغــاء الشــريحة ومصــادرة الســيارة وذلــك بتطبيــق‬\n‫املــواد ( ‪ )56/53/38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫بحقــه وتعزيــره لقــاء هروبــه وتســتره علــى مصــدر مــا ضبــط معــه ‪ ،‬أقــر‬\n‫املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام ‪ ،‬بنــاء علــى ماتقــدم‬\n‫حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن و اجللــد و املنــع مــن‬\n‫الســفر و مصــادرة الســيارة و اجلــوال و إلغــاء الشــريحة والغرامــة وإقامــة‬\n‫حــد املســكر وبعــرض احلكــم علــى طــريف الدعــوى قــرر املدعــى عليــه‬\n‫اعتراضــه علــى احلكــم بالئحــة وقــرر املدعــي العــام اعتراضــه علــى‬\n‫بــدون الئحــة ‪ُ ،‬صــدق احلكــم مــن محكمــة االســتئناف باألكثريــة‪.‬‬\n\n\n\n\n                                                                                        ‫‪424‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم وتاريــخ ‪1434/06/27‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقم وتاريخ ‪ 1434/06/27‬هـ ففي يوم اإلثنني املوافق‪1434/07/10‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 45‬وفيهــا قــدم املدعــي العــام الئحــة‬\n      ‫الدعــوى التــي نصهــا ( فبصفتــي عضــو هيئــة التحقيــق واالدعــاء العــام‬\n      ‫مبدينــة الريــاض أدعــي علــى‪ ........ /‬البالــغ مــن العمــر (‪ )41‬عام ـ ًا‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ،)..........‬أعــزب‪،‬‬\n      ‫متعلــم‪ ،‬متســبب‪ ،‬يقيــم مبدينــة الريــاض‪ ،‬أوقف بتاريــخ ‪1434/4/15‬هـ‬\n      ‫وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر إحالــة ومتديــد توقيــف رقــم‬\n      ‫(ه ـ ر‪ )42783/5/1‬وتاريــخ ‪1434/4/27‬ه ـ اســتناد ًا للقــرار الــوزاري‬\n      ‫رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة‪ .‬حيــث انــه بتاريــخ ‪1434/4/15‬ه ـ قبــض علــى‬\n      ‫املذكــور مــن قبــل إحــدى فــرق إدارة العمليــات التابعــة إلدارة مكافحــة‬\n      ‫املخــدرات مبنطقــة الريــاض وذلــك بنــاء ًا علــى ورود معلومــات مــن أحــد‬\n      ‫مصادرهــم الســرية عــن قيــام املذكــور بترويــج مــادة الكوكايــن‬\n      ‫املخــدر مســتخدم ًا يف ذلــك هاتفــه اجلــوال رقــم (‪ ).‬وســبق وان اتفــق معــه‬\n      ‫املصــدر هاتفي ـ ًا لشــراء (‪ )2‬جرامــن مــن مــادة الكوكايــن املخــدر‬\n      ‫مببلــغ وقــدره (‪ )2000‬ألفــي ريــال واســتعد املصــدر بربــط احــد ضبــاط‬\n      ‫إدارة العمليــات طرفنــا ليقــوم بعمليــة اإلســتالم والتســليم مــن املذكــور‪،‬‬\n      ‫ومت تزويــد الضابــط املكلــف بهاتــف جــوال ليقــوم بالتواصــل مــع‬\n\n‫‪425‬‬\n\f‫املذكــور ومت تزويــد رقــم الضابــط املكلــف إلــى املصــدر ثــم قــام‬\n‫املصــدر بتمريــره للمذكــور وبعــد حوالــي نصــف الســاعة ورد إتصال من‬\n‫املصــدر يفيــد بــأن املذكــور متواجــد باملوقــع وينتظــر اتصــال الضابــط‬\n‫املكلــف ‪ ،‬عليــه جــرى االتصــال مــن قبــل الضابــط املكلــف علــى‬\n‫هاتــف املذكــور وذكــر للضابــط املكلــف بأنــه متواجــد خلــف أحــد‬\n‫األســواق بداخــل احلــي ويســتقبل ســيارة مــن نــوع ‪ .....‬وهــو يف انتظــاره‪،‬‬\n‫وعليــه مت تزويــد الضابــط املكلــف مببلــغ مرقــم وقــدره (‪ )2000‬ألفــي‬\n‫ريــال ليقــوم بعمليــة الشــراء ‪ ،‬ومت االنتقــال بكامــل الفرقــة ‪ ،‬ونشــر‬\n‫الفرقــة خلــف الســوق وعنــد دخــول الضابــط املكلــف بســيارته إلــى‬\n‫داخــل احلــي شــوهدت ســيارة مــن نــوع جيــب (‪ ).....‬فضــي اللــون يحمــل‬\n‫اللوحــة رقــم (‪ ).......‬يســتقله شــخص واحــد وهــو يقــف بجانــب الســيارة‬\n‫التــي بهــا الضابــط املكلــف عبــر نوافــذ األبــواب لــم يترجــل احــد منهــا‬\n‫‪ ،‬وســلم املذكــور للضابــط املكلــف كيــس نايلــون بداخلــه مــادة‬\n‫مســحوقه ناعمــة امللمــس بلــوري اللــون عــدمي الرائحــة يشــبه نــدف الثلــج‬\n‫‪ ،‬يشــتبه أن يكــون مــن مــادة الكوكايــن املخــدر والتــي بلــغ وزنهــا‬\n‫(‪ )1.4‬جرام ـ ًا واحــد ًا وأربعــة أعشــار اجلــرام ‪ ،‬واســتلم املذكــور مــن‬\n‫ال منهمــا يف ســبيله ‪ ،‬ومتــت‬‫الضابــط املكلــف املبلــغ املرقــم وحتــرك ك ً‬\n‫متابعــة املذكــور حتــى متكــن مــن الوقــوف بداخــل حــي الســويدي ‪،‬‬\n‫وعنــد نزولــه مــن ســيارته متــت مداهمتــه ‪ ،‬وعنــد مشــاهدته للفرقــة قــام‬\n‫بالهــرب علــى قدميــه مســافة قصيــرة ومت إطــاق طلقتــن حتذيريــة‬\n‫مــن مســدس حكومــي يف الهــواء لتخويفــه لعــدم متكنــه مــن الهــرب‬\n‫‪ ،‬وبضبطــه اتضــح انــه املذكــور وبتفتيشــه عثــر بداخــل جيبــه علــى‬\n‫محفظــة جلديــه عثــر بداخلهــا علــى كيــس نايلــون بداخلــه حبــة بيضــاء‬\n\n\n                                                                                   ‫‪426‬‬\n\f      ‫اللــون مكســورة نصفــن جميــع النصفــن حتمــل عالمــة الكبتاجــون‬\n      ‫احملظــورة ‪ ،‬وكذلــك عثــر بنفــس احملفظــة علــى قطعــة ســوداء اللــون‬\n      ‫صغيــرة يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )0.1‬عشــر‬\n      ‫اجلــرام ‪ ،‬وعثــر أيضــا بنفــس احملفظــة علــى مبلــغ مالــي وقــدره (‪)4573‬‬\n      ‫أربعــة آالف وخمســمائة وثالثــة وســبعون ريــال ‪ ،‬وكذلــك عثــر بداخــل‬\n      ‫جيــب ثوبــه العلــوي علــى املبلــغ املرقــم وقــدره ألفــي ريــال ‪ ،‬وعثــر معــه‬\n      ‫علــى كذلــك علــى جهــازي جــوال مــن نــوع ‪ .....‬احدهمــا يحمــل الرقــم‬\n      ‫(‪ ).0‬ورقمــه املصنعــي (‪ )...‬وهــو الهاتــف الــذي اســتخدم يف الترويــج ‪،‬‬\n      ‫وبتفتيــش ســيارته عثــر بجانــب ناقــل احلركــة (القيــر) علــى علبــة دخــان‬\n      ‫عثــر بداخلهــا علــى ســيجارة ملفوفــة يشــتبه أن تكــون مخلوطــة مبــادة‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )1.3‬جــرام واحــد ًا وثالثــة أعشــار اجلــرام ‪،‬‬\n      ‫ومبناقشــته عــن مصــدر مــا قــام بترويجــه أفــاد بأنــه يحصــل عليهــا مــن‬\n      ‫شــخص فلســطيني اجلنســية يســكن بحــي ( ‪ ) .......‬ومت التحفــظ علــى‬\n      ‫ا مت‬ ‫املذكــور وذلــك حملاولــة الشــراء مــن الشــخص الفلســطيني وفع ـ ً‬\n      ‫الشــراء منــه وعنــد ضبطــه ســوف ُتشــعر جهــة التحقيــق بذلــك وقــد أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة الســموم‬\n      ‫والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪/4637‬س) لعــام‬\n      ‫‪1434‬ه ـ احتــواء مســتخلص عينــة املســحوق املــروج ملــادة الكوكايــن‬\n      ‫وهــو مــن املــواد املخــدرة املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وايجابيــة القطعــة‬\n      ‫ومســتخلص التبــغ يف الســيجارة املضبوطــة للحشــيش وهــو مــن املــواد‬\n      ‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة‪ ،‬واحتــواء نصفــي احلبــة املضبوطــة لالمفيتامــن وهــو‬\n\n\n‫‪427‬‬\n\f‫مــن املــواد املنبهــة املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع أقوالــه اعتــرف أن‬\n‫بحيــازة مــا ضبــط بقصــد التعاطــي وبتعاطــي مــن نــوع مــا ضبــط معــه‪.‬‬\n‫وباســتجوابه اقــر بتســليمه كيــس وزنــه (‪ )1.4‬جرام ـ ًا واحــد ًا وأربعــة‬\n‫أعشــار اجلــرام مــن الكوكايــن‪ ،‬كمــا اعتــرف بحيازتــه ســيجارة مــن‬\n‫احلشــيش املخــدر بقصــد التعاطــي واعتــرف أن رقــم اجلــوال (‪ )....‬يعــود‬\n‫لــه وهــو مــن نــوع ‪ ،.....‬كمــا اعتــرف الســيارة مــن نــوع ‪ .....‬والتــي حتمــل‬\n‫رقــم (‪ )......‬تعــود لــه وهــي باســمه‪ ،‬وأفــاد أن املبلــغ املالــي املضبــوط معــه‬\n‫وقــدره (‪ )4573‬أربعــة آالف وخمســمائة وثــاث وســبعون ريــا ًال يعــود‬\n‫لعمالــه يف مؤسســة والــده لتجديــد رخــص إقاماتهــم (مت تســليمه املبلــغ‬\n‫املالــي اســتناد ًا للمادتــن (‪ 86‬ـ ـ ‪ )88‬مــن نظــام اإلجــراءات اجلزائيــة‬\n‫ال للمصادرة مبوجب اخلطاب رقم (هـ ر‪)60977/5/1‬‬                   ‫لكونه ليس مح ً‬\n‫وتاريــخ ‪1434/6/17‬هــ)‪ .‬وقــد أســفرت إجــراءات التحقيــق معــه عــن‬\n‫توجيــه االتهــام للمدعــى عليــه ببيــع ماوزنــه (‪ )1.34‬جرامـ ًا واحــد ًا وثالثــة‬\n‫أعشــار اجلــرام مــن مــادة الكوكايــن بقصــد االجتــار والترويــج‪،‬‬\n‫وحيــازة ســيجارة مخلوط ـ ًا تبغهــا باحلشــيش املخــدر بلــغ وزنهــا (‪)1.4‬‬\n‫جرام ـ ًا واحــد ًا وأربعــة أعشــار اجلــرام وحيــازة نصفــن حلبــة مــن حبــوب‬\n‫االمفيتامــن املنبــه احملظــور وحيــازة قطعــة مــن احلشــيش املخــدر بلــغ‬\n‫وزنهــا (‪ )0.1‬عشــر اجلــرام بقصــد التعاطــي وتعاطيــه احلشــيش املخــدر‬\n‫واحلبــوب احملظــورة املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وهروبــه مــن الفرقــة القابضــة املعاقــب علــى‬\n                                 ‫ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة‬\n\n\n                                                                                         ‫‪428‬‬\n\f      ‫ا علــى‬  ‫‪ .1‬مــا تضمنــه اعترافــه حتقيق ـ ًا املنــوه عنــه املــدون تفصي ـ ً‬\n      ‫الصفحــات رقــم (‪ 1‬ـ ـ ‪ )3‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪. )16‬‬\n      ‫‪ .2‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املــدون‬\n                                                         ‫علــى اللفتــن رقــم (‪ )3‬ورقــم (‪.)4‬‬\n      ‫‪ .3‬مــا تضمنــه محضــر القبــض والضبــط والتفتيــش املنــوه عنــه املــدون‬\n      ‫علــى الصفحــة رقــم (‪ 11‬ـ ـ ‪ )12‬مــن ملــف ضبــط إجــراءات االســتدالل يف‬\n                                                            ‫قضايــا املخــدرات لفــة رقــم(‪.)1‬‬\n              ‫‪ .4‬ما تضمنه التقرير الكيميائي الشرعي املرفق لفة رقم (‪.)15‬‬\n                    ‫‪ .5‬عثر مع املذكور على اجلوال الذي مت التنسيق من خالله‪.‬‬\n      ‫‪ .6‬ماتضمنــه محضــر املبلــغ املرقــم املــدون علــى الصفحــة رقــم (‪ 11‬ـ ـ ‪)12‬‬\n      ‫مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا املخــدرات لفــة رقــم(‪.)1‬‬\n      ‫وببحــث ســوابقه عثــر لــه علــى ســابقة واحــدة وهــي حيــازة واســتعمال‬\n                                                                                   ‫مخــدرات‪.‬‬\n      ‫وحيــث إن مــا أق ــدم عل ــيه ال ــمذكور ف ــعل م ــحرم شــرع ًا وم ــعاقب عليــه‬\n      ‫شــرع ًا ونظام ـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                                      ‫باآلتــي‪:‬‬\n                 ‫‪ .1‬إجراء املقتضى الشرعي بحقه لقاء تعاطيه احلشيش املخدر‪.‬‬\n      ‫‪ .2‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا للفقــرة (األولــى)‬\n      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n      ‫إليــه ‪ ،‬وتشــديد العقوبــة عليــه وفقـ ًا للفقــرة (ج) البنــد (ثانيـاً) مــن نفــس‬\n                                    ‫املــادة مــن ذات النظــام بحقــه لقــاء مــا أســند إليــه‪.‬‬\n      ‫‪ .3‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد تنفيــذ عقوبــة ســجنه وفقـ ًا‬\n                  ‫للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار إليــه‪.‬‬\n\n\n‫‪429‬‬\n\f‫‪ .4‬مصــادرة الهاتــف النقــال مــن نــوع ( ‪ ) .......‬العائد للمذكور املســتخدم‬\n‫يف اجلرميــة ذي الرقــم املصنعــي (‪ ، ).....‬وفقـ ًا للفقــرة (األولــى) مــن املــادة‬\n                                                            ‫(‪ )53‬مــن ذات النظــام‪.‬‬\n‫‪ .5‬إلغــاء الشــريحة الهاتفيــة ذات الرقــم () املســتخدمة يف عمليــة الترويــج‬\n‫العائــد لــأول وعــدم صرفهــا لنفــس املشــترك يف حــال صــدور احلكــم‬\n‫باإللغــاء ‪ ،‬وإبــاغ الشــركة مصــدرة الشــريحة بذلــك وفقـ ًا لتعميم ســمو‬\n                     ‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪9‬ـ‪1428/2/10‬ه ـ ‪.‬‬\n‫‪ .6‬مصــادرة الســيارة العائــدة للمذكــور وهــي مــن نــوع ( ‪ ، ) .......‬حتمــل‬\n‫اللوحــة رقــم ( ــ) املســتخدمة يف عمليــة الترويــج اســتناد ًا للفقــرة األولــى‬\n       ‫مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n                               ‫‪ .7‬بعقوبة تعزيرية لقاء هربه من فرقة القبض‪.‬‬\n‫هــذا نــص الئحــة املدعــي العــام وجــرى تــاوة مــا جــاء يف الئحــة‬\n‫االدعــاء العــام علــى املتهــم احلاضــر يف هــذه اجللســة واطالعــه عليهــا‬\n‫وتوضيحهــا لــه وســؤاله اجلــواب عليهــا فأجــاب قائــا‪ :‬مــا ذكــر يف‬\n‫ببيــع ماوزنــه (‪ )1.34‬جرام ـ ًا‬            ‫الئحــة االدعــاء العــام مــن اتهامــي‬\n‫واحــد ًا وثالثــة أعشــار اجلــرام مــن مــادة الكوكايــن بقصــد االجتــار‬\n‫والترويــج‪ ،‬وحيــازة ســيجارة مخلوطـ ًا تبغهــا باحلشــيش املخــدر بلــغ وزنهــا‬\n‫(‪ )1.4‬جرام ـ ًا واحــد ًا وأربعــة أعشــار اجلــرام وحيــازة نصفــن حلبــة مــن‬\n‫حبــوب االمفيتامــن املنبــه احملظــور وحيــازة قطعــة مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ )0.1‬عشــر اجلــرام بقصــد التعاطــي وتعاطــي احلشــيش‬\n‫املخــدر واحلبــوب احملظــورة وهروبــي مــن الفرقــة القابضــة فهــذا صحيــح‬\n‫وأنــا تائــب ونــادم علــى مــا بــدر منــي وأتعهــد بعــدم العــودة إلــى مثــل ذلــك‬\n‫ثــم اطلعــت علــى أدلــة املدعــي العــام حيــث اطلعــت علــى أقــوال املدعــى‬\n\n\n                                                                                          ‫‪430‬‬\n\f      ‫عليــه يف التحقيــق ومحضــر القبــض والتقريــر الكيميائــي الشــرعي‬\n      ‫ومــا تضمنــه محضــر املبلــغ املرقــم والعثور على اجلوال الذي مت التنســيق‬\n      ‫مــن خاللــه معــه كمــا ســألت املدعــى عليــه عــن الســابقة املنســوبة لــه‬\n      ‫فقــال انهــا صحيحــة ثــم ســألت املدعــي العــام واملدعــى عليــه هــل لديهــم‬\n      ‫مــا يريــدان إضافتــه فأجــاب كل واحــد منهمــا بقولــه إننــا نكتفــي مبــا‬\n                          ‫قدمنــا مــن أقــوال ســابقة وليــس لدينــا مــا نريــد إضافتــه‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى أدلــة‬\n      ‫املدعــي العــام وباقــي أوراق املعاملــة وحيــث اقــر املدعــى عليــه مبــا نســب‬\n      ‫إليــه يف الدعــوى لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه ببيــع ماوزنــه‬\n      ‫(‪ )1.34‬جرام ـ ًا واحــد ًا وثالثــة أعشــار اجلــرام مــن مــادة الكوكايــن‬\n      ‫بقصــد االجتــار والترويــج‪ ،‬وحيــازة ســيجارة مخلوط ـ ًا تبغهــا باحلشــيش‬\n      ‫املخــدر بلــغ وزنهــا (‪ )1.4‬جرام ـ ًا واحــد ًا وأربعــة أعشــار اجلــرام وحيــازة‬\n      ‫نصفــن حلبــة مــن حبــوب االمفيتامــن املنبــه احملظــور وحيــازة قطعــة مــن‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )0.1‬عشــر اجلــرام بقصد التعاطــي وتعاطي‬\n          ‫احلشــيش املخــدر واحلبــوب احملظــورة وهروبــي مــن الفرقــة القابضــة‬\n      ‫والعقوبــات يف املــواد (‪ 38‬و‪56‬و‪)53‬مــن نظــام مكافحــة املخــدرات‬\n      ‫تنطبــق يف حــق املدعــى عليــه وعليــه فقــد حكمــت بتعزيــره علــى ذلــك‬\n                                                                                ‫مبــا يلــي‪:‬‬\n      ‫‪ -1‬بالســجن ملــدة عشــر ســنوات تبــدأ مــن تاريــخ إيقافــه خلطــورة مــا‬\n      ‫أقــدم عليــه املدعــى عليــه مــن ترويجــه ملــادة الكوكايــن املخــدرة‬\n                                                                              ‫واحملظــورة‬\n      ‫‪ -2‬بجلــده ألــف جلــدة مفرقــة علــى عشــر يــن دفعــة متســاوية كل‬\n              ‫دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى مــدة عشــرة أيــام‬\n\n\n‫‪431‬‬\n\f‫‪ -3‬بــأن يدفــع غرامــة ماليــة قدرهــا ثالثــون ألــف ريــال تــودع يف بيــت‬\n                                          ‫املــال وتصــرف يف وجــوه البــر اخليرية‬\n‫‪ -4‬منعــه مــن الســفر خــارج اململكــة ملــدة عشــر ســنوات تبــدأ بعــد‬\n                                                                     ‫تنفيــذ احلكــم‬\n‫‪ -5‬مصــادرة اجلــوال املســتخدم يف هــذه اجلرميــة وبيعــه وإيــداع قيمتــه‬\n‫بيــت املــال وصرفهــا يف وجــوه البــر اخليريــة و إلغــاء شــريحة الهاتــف‬\n                                                            ‫املســتخدمة يف اجلرميــة‬\n‫‪ -6‬كمــا حكمــت بجلــدة ثمانــن جلــدة حــد املســكر الســتعماله‬\n‫احلشــيش املخــدر والفاصــل بــن جلــد احلــد وجلــد التعزيــر مــدة عشــرة‬\n    ‫أيــام وعقوبــة اســتعماله احلبــوب احملظــورة داخلــة يف جلــد التعزيــر‬\n‫‪7‬ـ مصــادرة الســيارة مــن نــوع ‪ .........‬حتمــل اللوحــة رقــم (‪ )......‬وبيعهــا‬\n‫وإيــداع قيمتهــا بيــت املــال لصرفــه يف وجــوه البــر املختلفــة وعقوبــة‬\n‫تســتره علــى مصــدر مــا ضبــط وهروبــه مــن الفرقــة القابضــة داخلــة‬\n                                          ‫فيمــا مت احلكــم بــه عليــه مــن ســجن‬\n‫وبعــرض هــذا احلكــم علــى املدعــى عليــه قــرر اعتراضــه علــى هــذا‬\n‫احلكــم وانــه ســوف يقــدم الئحــة اعتــراض عليــه أمــا املدعــي العــام‬\n‫فقــد قــرر االعتــراض مكتفيــا مبــا جــاء يف الئحــة االدعــاء وجــرى‬\n‫إفهــام املعتــرض مبوجــب التعليمــات املنظمــة لالعتــراض وذلــك إعمــاال‬\n‫للمــادة الرابعــة والتســعون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة وأن‬\n‫عليــه مراجعــة احملكمــة يــوم األربعــاء املوافــق ‪1434/7/19‬ه ـ الســاعة‬\n‫التاســعة صباحــا موعــدا الســتالم نســخة مــن صــك احلكــم وجــرى‬\n‫الكتابــة إلــى إدارة الســجن إلحضــار املدعــى عليــه يف املوعــد احملــدد‬\n‫الســتالم نســخة مــن صــك احلكــم وختمــت اجللســة الســاعة‪01:30‬‬\n\n\n                                                                                       ‫‪432‬‬\n\f      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                              ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/10‬ه ـ‬\n      ‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض‬\n      ‫والقائــم بعمــل الشــيخ‪ /‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1434/06/27‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/06/27‬ه ـ ففــي يــوم األربعــاء‬\n                    ‫املوافــق‪ 1434/08/17‬ه ـ افتتحــت اجللســة الســاعة ‪10:45‬‬\n      ‫وفيهــا حضــر املعتــرض علــى احلكــم وهــو وجــرى تســليمه نســخة مــن‬\n      ‫صــك احلكــم وجــرى إفهامــه مبوجــب املــادة (‪)194‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وان مــدة االعتــراض علــى هــذا احلكــم هــي ثالثــون يومــا تبــدأ‬\n      ‫مــن تاريــخ هــذا اليــوم وإذا لــم يقــدم االعتــراض خــال هــذه املــدة فســوف‬\n      ‫يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة اعتــراض‬\n      ‫وذلــك إعمــاال للمــادة (‪)195‬مــن نظــام اإلجــراءات اجلزائيــة ففهــم ذلــك‬\n      ‫واســتعد بــه وعلــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/17‬ه ـ‬\n      ‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n      ‫بالريــاض برقــم وتاريــخ ‪ 1434/06/27‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1434/06/27‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/10/26‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 10:45‬وقــد وردنــا مــن إدارة احملكمة الالئحة‬\n      ‫االعتراضيــة املقدمــة مــن املعتــرض وكالــة () واملقيــدة يف احملكمــة‬\n      ‫برقــم‪ .....‬وتاريــخ ‪1434/9/23‬ه ـ املكونــة مــن ( ‪ ) 9‬صفحــة وقــد‬\n      ‫اطلعــت علــى هــذه الالئحــة ولــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه‬\n\n\n‫‪433‬‬\n\f‫ومت الشــرح علــى هــذه الالئحــة بذلــك وجــرى ضمهــا إلــى ملــف املعاملــة‬\n‫وأمــرت بالكتابــة علــى املعاملــة إلــى محكمــة االســتئناف وذلــك إعمــاال‬\n‫للمــادة (‪)197‬مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬وختمــت اجللســة الســاعة‬\n‫‪ 10:50‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                            ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/10/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولى‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪1434/11/2‬ه ـ‬\n‫واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة‪ /‬برقــم‬\n‫وتاريــخ ‪1434/7/19‬ه ـ واخلــاص بدعــوى املدعــي العــام ضــد ‪)....... (/‬‬\n‫‪ ،‬وموضوعهــا مخــدرات‪ ،‬وانتهــت الدراســة والتدقيــق باملصادقــة علــى‬\n‫احلكــم باألكثريــة لعــدم موجــب املالحظــة‪ ،‬مــع تنبيــه فضيلتــه إلــى‬\n‫تدويــن اســم املدعــي العــام الثالثــي حتــت توقيعــه يف الضبــط حســب‬\n‫التعليمــات‪ ،‬ومالحظــة ذلــك مســتقبالً‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪434‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":423,"source_page_end":434,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"541c6f945a289925960b48a28f91d3be72317903510aa909f9a1b299ab0a919b","normalized_text_hash":"177d938c6f16e7155a37338e3d6fb63a83402b9b40b47abe65a93ee1434b7ce0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p423-3427326"},{"id":"8bdf4da0-d5ca-54b8-a435-f63722d0f7ff","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن و اجللد و الغرامة و املنع من السفر و مصادرة اجلوال و إلغاء الشريحة ورد املبلغ احلكومي.","document_number":"34268398","case_number":"34299189","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/15","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن و اجللد و الغرامة و املنع من السفر و مصادرة اجلوال و إلغاء الشريحة ورد املبلغ احلكومي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34268398 :‬تاريخه‪1434/7/15 :‬هـ‬\n                        ‫رقم الدعوى‪34299189 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪/34289621‬ج‪/2‬ب تاريخه‪1434/08/07 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n      ‫إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن‬\n      ‫و اجللــد و الغرامــة و املنــع مــن الســفر و مصــادرة اجلــوال و إلغــاء‬\n                                            ‫الشــريحة ورد املبلــغ احلكومــي‪.‬‬\n\n\n\n      ‫‪ ( .1‬حديــث أم ســلمة رضــي اهلل عنهــا يف نهــي النبــي صلــى اهلل عليــه‬\n                                             ‫وســلم عــن كل مســكر و مفتــر ) ‪.‬‬\n               ‫‪ .2‬املادة ( ‪ ) 38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n               ‫‪ .3‬املادة ( ‪ ) 56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n               ‫‪ .4‬املادة ( ‪ ) 53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n               ‫‪ .5‬املادة ( ‪ ) 60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n                                  ‫‪ .6‬القرار الوزاري رقم ‪ 47‬يف ‪ 1421/2/18‬هـ ‪.‬‬\n           ‫‪ .7‬برقية وزير الداخلية رقم ( ‪ )9798/4/5/1‬يف ‪1428/2/10-9‬هـ ‪.‬‬\n                  ‫‪ .8‬تعميم وزير الداخلية رقم ‪ 65980‬يف ‪ 1422/10/23-22‬هـ ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج املخــدرات ‪ ،‬وبيــع قطعــة‬\n      ‫مــن احلشــيش املخــدر ‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى عليــه‬\n\n‫‪435‬‬\n\f‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء‬\n‫الشــريحة ورد املبلــغ احلكومــي وذلــك تطبيق ـ ًا ألحــكام املــواد (‪ )38‬و‬\n‫(‪ )53‬مــن نظــام مكافحــة املخــدرات ‪ ،‬كمــا طلــب إقامــة حــد املســكر‬\n‫علــى املدعــى عليــه لقــاء تعاطيــه للحشــيش ‪ ،‬حيــث توفــرت معلومــات‬\n‫لــدى اجلهــة األمنيــة عــن قيــام أحــد األشــخاص بترويــج املخــدرات‪،‬‬\n‫وأنــه يســتخدم املدعــى عليــه فتــم اإلتصــال عليــه مــن املصــدر وطلــب‬\n‫منــه قطعــة مــن احلشــيش املخــدر مببلــغ ألــف ريــال‪ ،‬فوافــق علــى ذلــك‪،‬‬\n‫وطلــب مــن املصــدر أن يســتلم الكميــة مــن املدعــى عليــه‪ ،‬واتفــق علــى‬\n‫املوعــد‪ ،‬فتــم تفتيــش املصــدر ‪ ،‬وترقيــم املبلــغ احلكومــي وقــدره ألــف‬\n‫ريــال ثــم قابــل املصــدر املدعــى عليــه ‪ ،‬وبعــد دقائــق نــزل املدعــى عليــه‬\n‫مــن الســيارة ودخــل منزلــه‪ ،‬وعــاد املصــدر وســلم الفرقــة قطعــة ســوداء‬\n‫جرامــا يشــتبه أن تكــون مــن احلشــيش‪ ،‬ثــم‬‫ً‬      ‫اللــون تــزن ثالثــة وعشــرون‬\n‫مت القبــض علــى املدعــى عليــه ‪ ،‬بنــاء علــى مــا ســبق حكمــت احملكمــة‬\n‫بإقامــة حــد املســكر علــى املدعــى عليــه واحلكــم بالتعزيــر بالســجن و‬\n‫اجللــد و الغرامــة و املنــع مــن الســفر و مصــادرة اجلــوال و إلغــاء الشــريحة‬\n‫ورد املبلــغ احلكومــي و مت النــزول عــن احلــد األدنــى للعقوبــة بنــاء علــى‬\n‫املــادة (‪ ) 60‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة ‪ ،‬لعــدم‬\n‫وجــود ســوابق بحــق املدعــى عليــه‪ ،‬و لقلــة الكميــة ‪ ،‬قنــع املدعــى عليــه‬\n‫باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة‬\n                   ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬      ‫اعتراضيــة ُ‬\n\n\n\n\n                                                                                     ‫‪436‬‬\n\f      ‫اجلزائيــة‬\n         ‫ّ‬         ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪............‬القاضــي يف احملكمــة‬\n      ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء املكلــف برقم وتاريخ ‪ 1434/06/28‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/06/28‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافق‪ 1434/07/15‬هـ افتتحت اجللسة الساعة ‪ 10 : 00‬وفيها حضر‬\n      ‫املدعــي العــام (‪ ) ......‬املعمــد بالترافــع أمــام هــذه احملكمــة مبوجــب‬\n      ‫خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعاء العام مبحافظة االحســاء‬\n      ‫ذي الرقم والتاريخ ‪ 1433/12/01‬هـ وادعى ضد احلاضر معه ( ‪..........‬‬\n      ‫ا يف دعــواه‬    ‫) ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬قائ ـ ً‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لدائــرة التحقيــق واالدعــاء‬\n      ‫العــام مبحافظــة االحســاء أدعــي علــى املذكــور أعــاه فباالطــاع علــى‬\n      ‫محضــر القبــض املعــد مــن مكافحــة املخــدرات مبحافظــة االحســاء‬\n      ‫تبــن أنــه بتاريــخ ‪1434/5/22‬ه ـ توفــرت معلومــات لــدى املكافحــة مــن‬\n      ‫مصادرهــا الســرية تفيــد عــن قيــام املواطــن‪( /‬لــم يتــم القبــض عليــه)‬\n      ‫بترويــج املخــدرات وأنــه يســتخدم املدعــى عليــه يف تســليم أي كميــة‬\n      ‫يقــوم ببيعهــا فتــم متكــن املصــدر مــن االتصــال عليــه وطلــب منــه شــراء‬\n      ‫قطعــة مــن احلشــيش املخــدر مببلــغ (‪)1000‬ألــف ريــال فوافــق علــى ذلــك‬\n      ‫وطلــب مــن املصــدر أن يســتلم الكميــة مــن املدعــى عليــه ومت متكــن‬\n      ‫املصــدر مــن االتصــال علــى جــوال املدعــى عليــه رقــم (‪ ).....‬واتفقــا علــى‬\n      ‫موعــد ومــكان االســتالم والتســليم فتــم تفتيــش املصــدر وترقيــم مبلــغ‬\n      ‫حكومــي وقــدره (‪)1000‬ألــف ريــال وحتــرك املصــدر بســيارته حتــت‬\n\n‫‪437‬‬\n\f‫أنظــار الفرقــة القابضــة إلــى املــكان املتفــق عليــه ثــم قابــل املدعــى عليــه‬\n‫وركــب معــه وبعــد عشــر دقائــق نــزل املدعــى عليــه مــن الســيارة ودخــل‬\n‫إلــى منزلــه ثــم عــاد املصــدر وســلم الفرقــة قطعــة ســوداء اللــون تــزن (‪)23‬‬\n‫ثالثــة وعشــرون جرام ـ ًا يحتمــل أن تكــون مــن احلشــيش املخــدر فتــم‬\n‫مراقبــة منــزل املدعــى عليــه ويف يــوم األحــد املوافــق ‪1434/5/26‬ه ـ‬\n‫وأثنــاء قيــام الفرقــة امليدانيــة مبســح ميدانــي للمواقــع املشــبوهة شــاهد‬\n‫أعضــاء الفرقــة املدعــى عليــه بالقــرب مــن إحــدى االســتراحات فتــم‬\n‫القبــض عليــه وبتفتيشــه لــم يعثــر بحوزتــه علــى شــيء مــن املمنوعــات ولــم‬\n           ‫يعثــر علــى املبلــغ احلكومــي املرقــم وقــدره (‪ )1000‬ألــف ريــال‪.‬‬\n‫وباســتجوابه‪ /‬أقــر بأنــه يف يــوم األربعــاء املوافــق ‪1434/5/22‬ه ـ قــام‬\n‫بشــراء قطعــة مــن احلشــيش املخــدر مــن (‪ ).......‬بقصــد التعاطــي ومــن‬\n‫اليــوم نفســه تلقــى اتصــا ًال علــى جوالــه املذكــور أعــاه مــن (‪ )......‬وطلــب‬\n‫منــه أن يقــوم ببيــع قطعــة احلشــيش التــي بحوزتــه علــى املصــدر ووعــده‬\n‫بتوفيــر كميــة بديلــة لــه فوافــق علــى ذلــك ثــم قابــل املصــدر وســلمه‬\n‫قطعــة احلشــيش واســتلم مبلغهــا كمــا أقــر بتعاطيــه للحشــيش املخــدر‬\n                                                                         ‫يف الســابق‪.‬‬\n‫وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ )......‬لعــام ‪1434‬ه ـ‬\n‫ايجابيــة عينــة القطعــة املضبوطــة ملــادة احلشــيش املخــدر املــدرج يف‬\n‫اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لألولــ‪ /‬ببيع قطعة من احلشــيش‬\n‫املخــدر تــزن (‪ )23‬ثالثــة وعشــرون جرام ـ ًا بقصــد االجتــار وتعاطيــه‬\n                                                               ‫لنوعــه يف الســابق ‪.‬‬\n                                                ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n\n\n                                                                                        ‫‪438‬‬\n\f      ‫‪ -1‬ماجــاء يف أقوالــه املدونــة علــى الصفحــات رقــم (‪ )3،2،1‬مــن دفتــر‬\n                                                                  ‫التحقيــق لفــه رقــم(‪.)10‬‬\n      ‫‪ -2‬ماجــاء يف محضــر القبــض املنــوه عنــه املــدون علــى الصفحتــن رقــم‬\n                                        ‫(‪ )13،12‬مــن دفتــر االســتدالل لفــة رقــم (‪.)8‬‬\n      ‫‪ -3‬ماجــاء يف محضــر االتصــال املــدون علــى الصفحــة رقــم (‪ )4‬مــن دفتــر‬\n                                                                  ‫االســتدالل لفــة رقم (‪.)8‬‬\n      ‫‪ -4‬ماجــاء يف محضــر تفتيــش املصــدر وســيارته املــدون علــى الصفحــة‬\n                                      ‫رقــم (‪ )12‬مــن دفتــر االســتدالل لفــة رقــم (‪).8‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا ‪ ،‬فعــل مجــرم ومعاقــب علي ــه شــرع ًا ونظام ـ ًا مبوجــب املــادة (‬\n      ‫الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات‬\n                                             ‫مــا اســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n      ‫‪ - 1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )38‬مــن النظــام‬\n      ‫املشــار إليــه لقــاء مــا أســند إليــه لكونهــا العقوبــة األشــد اســتنادا للفقــرة‬\n          ‫األولــى مــن املــادة (‪ )62‬مــن النظــام املشــار إليــه لقــاء مــا أســند إليــه‪.‬‬\n      ‫‪ -2‬مصــادرة اجلــوال املضبــوط مــع املدعــى عليــه مــن نــوع (‪ )....‬الرقــم‬\n      ‫التسلســلي (‪ ).....‬املســتخدم يف اجلرميــة وفقـ ًا للفقــرة (األولــى) مــن املــادة‬\n      ‫(‪ )53‬مــن النظــام املشــار إليــه وإيــداع املبالــغ يف حســاب إدارة املخــدرات‬\n                   ‫ـاء علــى القــرار الــوزاري رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬ه ـ ‪.‬‬        ‫بنـ ً‬\n      ‫‪ -3‬إلغــاء شــرايحة االتصــال املوصوفــة يف القــرار وفــق برقيــة وزيــر‬\n                ‫الداخليــة رقــم (‪ )9798/4/5/1‬وتاريــخ ‪1428/2/10-9‬هــ‪.‬‬\n      ‫‪-4‬إلزامــه بــرد املبلــغ احلكومــي العائــد ملكافحــة املخــدرات باالحســاء‬\n\n\n‫‪439‬‬\n\f‫وقــدره (‪ )1000‬ألــف ريــال اســتناد َا لتعميــم وزير الداخليــة رقم (‪)65980‬‬\n                                                   ‫وتاريخ ‪1422/10/23-22‬هـ‪.‬‬\n‫‪-5‬معاقبتــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن‬\n     ‫النظــام املشــار إليــه مبنعــه مــن الســفر بعــد تنفيــذ محكوميتــه‪.‬‬\n‫ا مــا ذكــره املدعــي‬    ‫هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n‫العــام مــن أنــه بتاريــخ ‪1434/5/22‬ه ـ قمــت بترويــج قطعــة مــن احلشــيش‬\n‫املخــدر تــزن (‪ )23‬ثالثــة وعشــرون جرامـ ًا بقصــد االجتــار وأنني تعاطيت‬\n‫لنوعــه يف الســابق وأنــه بتاريــخ ‪1434/05/26‬ه ـ مت القبــض علــي مــن‬\n‫قبــل إحــدى فــرق مكافحــة املخــدرات التابعــة حملافظــة األحســاء فهــذا‬\n‫كلــه صحيــح وكذلــك مــا ذكــره املدعــي العــام مــن أنــه اتصــل بــي على‬\n‫هاتفــي اجلــوال رقــم وطلــب منــي حشــيش مخــدر مببلــغ وقــدره ألــف ريــال‬\n‫اســتلمتها فهــذا صحيــح أيض ـ ًا هكــذا أجــاب وباإلطــاع علــى املعاملــة‬\n‫وجــد فيهــا علــى لفــة رقــم ‪ 14‬التقريــر الكيمــاوي الشــرعي رقــم ()‬\n‫لعــام ‪1434‬ه ـ املتضمــن إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‬\n‫واســتهالك جميــع العينــات املرســلة يف التحليــل ا‪.‬ه ـ فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه ببيــع قطعــة مــن احلشــيش‬\n‫املخــدر تــزن (‪ )23‬ثالثــة وعشــرون جرامـ ًا بقصد االجتــار وتعاطيه لنوعه‬\n‫يف الســابق وللتقريــر الكيمــاوي الشــرعي ولنهــي النبــي صلــى اهلل عليــه‬\n‫وســلم عــن كل مســكر ومفتــر كمــا يف حديــث أم ســلمه رضــي اهلل‬\n‫عنهــا وحيــث إن مــا أقــدم عليــه املدعــى عليــه ضــرب من ضروب اإلفســاد‬\n‫بــاألرض وحيــث إن احلشــيش يشــترك مــع اخلمــر يف منــاط احلكــم لذلــك‬\n‫كلــه ثبــت لــدي إدانــة املدعــى عليــه ببيــع قطعــة مــن احلشــيش املخدر تزن‬\n‫(‪ )23‬ثالثــة وعشــرون جرامـ ًا بقصــد االجتــار وتعاطيــه لنوعــه يف الســابق‬\n\n\n                                                                                     ‫‪440‬‬\n\f      ‫وحكمــت عليــه مبــا يلــي ‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه ثمانــون جلــدة دفعــة‬\n      ‫واحــدة حــد املســكر ثاني ـ ًا ‪ :‬ســجن املدعــى عليــه مــدة ثــاث ســنوات‬\n      ‫يحتســب منهــا مــدة بقائــه بالســجن بخصــوص هــذه القضيــة وجلــد‬\n      ‫املدعــى عليــه ثالثمائــة جلــدة تعزيــر ًا مفرقــة علــى ســت دفعــات كل‬\n      ‫دفعــة خمســن جلــدة بــن كل دفعــة واألخــرى مــدة اســبوعني وبغرامــة‬\n      ‫ماليــة قدرهــا ثالثــة آالف ريــال وقــد نزلــت علــى العقوبــة املقــررة نظامـ ًا‬\n      ‫وذلــك مبوجــب املــادة ‪ 60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة نظــر ًا لعــدم وجــود ســوابق علــى املدعــى عليــه وملــا ظهــر عليــه‬\n      ‫مــن عالمــات التوبــة عليــه ثالث ـ ًا ‪ :‬منــع املدعــى عليــه مــن الســفر خــارج‬\n      ‫اململكــة مــدة خمــس ســنوات بعــد تنفيــذ مــدة محكوميتــه وذلــك‬\n      ‫مبوجــب املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫رابع ـ ًا ‪ :‬مصــادرة اجلــوال املضبــوط مــع املدعــى عليــه مــن نــوع (‪)......‬‬\n      ‫الرقــم التسلســلي (‪ ).....‬املســتخدم يف اجلرميــة وفق ـ ًا للفقــرة (األولــى)‬\n      ‫مــن املــادة (‪ )53‬مــن النظــام املشــار إليــه وإيــداع املبالــغ يف حســاب إدارة‬\n      ‫ـاء علــى القــرار الــوزاري رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬ه ـ‬          ‫املخــدرات بنـ ً‬\n      ‫خامسـ ًا ‪ :‬إلغــاء شــرايحة االتصــال املوصوفــة يف القــرار وفــق برقيــة وزيــر‬\n      ‫الداخليــة رقــم (‪ )9798/4/5/1‬وتاريــخ ‪1428/2/10-9‬ه ـ سادس ـ ًا ‪:‬‬\n      ‫إلــزام املدعــى عليــه بــرد املبلــغ احلكومــي العائــد ملكافحــة املخــدرات‬\n      ‫باالحســاء وقــدره (‪ )1000‬ألــف ريــال اســتناد َا لتعميــم وزيــر الداخليــة‬\n      ‫رقــم (‪ )65980‬وتاريــخ ‪1422/10/23-22‬ه ـ وبــه حكمــت وبعــرض‬\n      ‫احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر املدعــي العــام اعتراضــه‬\n      ‫علــى احلكــم وطلــب رفــع املعاملــة إلــى محكمــة اإلســتئناف بــدون الئحة‬\n      ‫فأجبتــه لطلبــه وأمــا املدعــى عليــه قــرر قناعتــه بــه وبــه ختمــت اجللســة يف‬\n\n\n‫‪441‬‬\n\f‫متــام الســاعة ‪ 10 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/15‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/08/30‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 45‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫اإلســتئناف باملنطقــة الشــرقية برقــم يف ‪1434/08/24‬ه ـ واملتعلقــة‬\n‫بدعــوى املدعــي العــام ضــد املــدون هويتــه ســابق ًا يف قضيــة مخــدرات‬\n‫وبرفقهــا القــرار الشــرعي برقــم وتاريــخ ‪1434/08/07‬ه ـ الصــادر‬\n‫مــن الدائــرة اجلزائيــة الثانيــة مبحكمــة االســتئناف باملنطقــة الشــرقية‬\n‫املتضمــن إنــه بدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن‬\n‫فضيلتــه حكــم علــى املدعــى عليــه مبنعــه مــن الســفر ملدة خمس ســنوات‬\n‫بينمــا نصــت املــادة ‪ 56‬علــى أن مــدة املنــع تكــون مماثلــة ملــدة الســجن‬\n‫ملالحظــة مــا ذكــر وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة إلكمــال‬\n‫الزمهــا قاضــي اســتئناف (‪ ).......‬ختمــه وتوقيعــه قاضــي اســتئناف (‪).......‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة (‪ )......‬ختمــه وتوقيعــه وعليــه فإنــي أجيــب‬\n‫أصحــاب الفضيلــة قضــاة محكمــة االســتئناف وفقهــم اهلل لــكل‬\n‫خيــر بأننــي عدلــت عمــا حكمــت بــه مــن منــع املدعــى عليــه مــن الســفر‬\n‫خــارج اململكــة مــدة خمــس ســنوات وحكمــت مبنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة مماثلــة لســجنه وهــي ثــاث ســنوات وبــه ختمــت اجللســة يف‬\n‫متــام الســاعة ‪ 11 : 50‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم وتاريــخ ‪1434/9/20‬ه ـ الــواردة مــن‬\n\n\n                                                                                         ‫‪442‬‬\n\f      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف برقــم‬\n      ‫وتاريــخ ‪1434/9/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪ /‬املســجل برقــم وتاريــخ ‪1434/7/15‬ه ـ اخلــاص‬\n      ‫بدعوى‪/‬املدعــي العــام ضــد(‪ )......‬يف قضيــة مخــدرات وقــد تضمــن‬\n      ‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلتــه‬\n      ‫علــى قرارنــا رقــم وتاريــخ ‪1434/8/7‬ه ـ قررنــا املصادقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/10/20‬هــ‪.‬‬\n\n\n\n\n‫‪443‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":435,"source_page_end":443,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa5321b6f84ac313e9c03ee1e974103b4de579b6aef841bdb8669898894482fc","normalized_text_hash":"4063138d0f99e1fe5a1b3e115cdc1fa3902985261538e3de2b99a2fbfb8f7e7d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p435-34268398"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b698b1a8-2457-5936-860e-b3a357413841","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -ثبوت إدانة املدعى عليه -ندم -نزول عن احلد األدنى للعقوبة -مقاومة رجال األمن -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر -تعزير تخدمني يف اجلرمية- مبصادرة الهاتف اجلوال وشريحته املس ظروف مخففة للعقوبة.","document_number":"3425538","case_number":"34186011","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/28","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -ثبوت إدانة املدعى عليه -ندم -نزول عن احلد األدنى للعقوبة -مقاومة رجال األمن -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر -تعزير تخدمني يف اجلرمية- مبصادرة الهاتف اجلوال وشريحته املس ظروف مخففة للعقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3425538:‬تاريخه‪1434/01/28 :‬هـ‬\n                   ‫رقم الدعوى‪34186011:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪3446381‬تاريخه‪1434/02/24:‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة‪ -‬ثبــوت إدانــة املدعــى عليــه‪ -‬نــدم‬\n‫‪-‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬مقاومــة رجــال األمــن ‪ -‬تعزيــر‬\n‫املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر ‪ -‬تعزيــر‬\n‫ـتخدمني يف اجلرميــة‪-‬‬‫َ‬       ‫مبصــادرة الهاتــف اجلــوال وشــريحته املسـ‬\n                                                ‫ظــروف مخففــة للعقوبــة‪.‬‬\n\n\n\n\n‫فقــرة ‪ 2‬مــن املــادة ‪ ، 3‬املــادة (‪ ، )38‬املــادة (‪ ، )56‬املــادة (‪ )60‬مــن نظــام‬\n                                 ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫أقــام املدعــي العــام دعــواه ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات‬\n‫اإلمفيتامــن ‪ ،‬بقصــد الكســب املــادي ‪ ،‬حيــث مت القبــض علــى املدعــى‬\n‫عليــه وهــو يــروج حبــوب االمفيتامــن وأقــر املدعــى عليــه بصفــة الترويــج‬\n‫وأثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n‫اإلمفيتامــن وطلــب املدعــي العــام احلكــم علــى املدعــى عليه‪،‬بعقوبــة‬\n‫تعزيريــة واملنــع مــن الســفر خــارج البــاد بعــد تنفيــذ العقوبــة ومصــادرة‬\n‫جهــاز اجلــوال املســتخدم يف الترويــج وإلغــاء الشــريحة املســتخدمة يف‬\n‫الترويــج لنفــس املدعــى عليــه‪ ،‬إقــرار املدعــى عليــه بالدعــوى ‪ -‬قــررت‬\n\n                                                                                       ‫‪398‬‬\n\f      ‫احملكمــة بثبــوت إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة‪،‬‬\n      ‫حكمــت احملكمــة علــى املدعــى عليــه بســجنه ســنة وســتة أشــهر تبــدأ‬\n      ‫مــن تاريــخ توقيفــه يف هــذه القضيــة‪ ،‬وجلــده خمســن جلــدة مفرقــة علــى‬\n      ‫دفعــات كل دفعــة خمســون جلــدة بينهمــا عشــر أيــام‪ ،‬وإلزامــه بدفــع‬\n      ‫غرامــة ماليــة قدرهــا ثالثــة آالف ري ــال‪ ،‬واملنــع مــن الســفر خــارج البــاد‬\n      ‫مــدة ســنتني تبــدأ بعــد انتهــاء عقوبة ســجنه‪ ،‬ومصــادرة اجلوال املســتخدم‬\n      ‫يف الترويــج وإلغــاء الشــريحة وعــدم صرفهــا لنفــس املتهــم‪ ،‬وعقوبــة‬\n      ‫تعزيريــة لقــاء توجيــه التهمــة عليــه مبقاومــة رجــال الفرقــة القابضــة‬\n      ‫بجلــده خمســن جلــدة دفعــة واحــدة‪ ،‬قــرر املدعــي العــام عــدم قناعتــه‬\n      ‫باحلكــم ‪،‬وقنــع املدعــى عليــه وجــرى تصديــق احلكــم مــن محكمــة‬\n                                                                          ‫االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬‬\n      ‫وتاريــخ ‪1434/01/21‬هاملقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ‬\n      ‫‪1434/01/21‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/01/27‬ه ـ حضــر‬\n      ‫ا‬\n      ‫املدعــي العــام‪.......... /‬املشــار إلــى تكليفــه يف الضبــط وادعــى قائ ـ ً‬\n      ‫دعــواي هــي مــا ورد يف الئحــة الدعــوى العامــة املتضمنــة االدعــاء علــى‪/‬‬\n      ‫‪...................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)..........‬‬\n      ‫حيــث أنــه بتاريــخ ‪1433/12/15‬ه ـ مت القبــض عليــه لترويجــه احلبــوب‬\n      ‫احملظــورة وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام لــه بترويــج ثــاث‬\n\n‫‪399‬‬\n\f‫حبــات مــن حبــوب االمفيتامــن املنبهــة احملظــورة عن طريــق البيع وحيازة‬\n‫حبــة بقصــد الترويــج واملجــرم مبوجــب املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة وتوجيــه االتهــام لــه مبقاومــة رجــال األمــن‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪-1 :‬مــا ورد بإقــراره املــدون علــى الصفحــة‬\n‫رقــم (‪ )3‬مــن دفتــر التحقيــق رقــم (‪ )1‬وعلــى الصفحــة رقــم(‪ )18‬مــن ملف‬\n‫إجــراءات االســتدالل رقــم(‪ -2 )1‬مــا تضمنــه محضــر القبــض والتفتيــش‬\n‫املــدون علــى الصفحــة رقــم (‪ )11‬مــن ملــف إجــراءات االســتدالل املرفــق‬\n‫لفــه رقــم (‪ -3 )1‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املرفــق لفــه‬\n‫رقــم(‪ )13‬وبالبحــث عمــا إذا كان لــه ســوابق اتضــح عــدم وجــود ســوابق‬\n‫مســجلة عليــه وحيــث أن مــا أقــدم عليــه املذكــور فعــل محــرم شــرع ًا‬\n‫ومجــرم ومعاقــب عليــه نظام ـ ًا مبوجــب نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا‬\n‫يلــي‪-1 :‬عقوبــة تعزيزيــه وفقـ ًا ملــا ورد فاملــادة (‪ )1/38‬مــن النظــام املشــار‬\n‫إليــه لقــاء مــا أســند إليــه ‪ -2‬منعــه مــن الســفر خــارج اململكــة بعــد‬\n‫تنفيــذ العقوبــة وفق ـ ًا ملــا ورد يف املــادة (‪ )56‬الفقــرة األولــى مــن النظــام‬\n‫املشــار إليــه ‪ -3‬مصــادرة جهــازي اجلــوال ذوي الرقمــن املصنعــي رقــم‬\n‫(‪ )..........‬ورقــم(‪ )..........‬وذلــك الســتعمالها يف قضيــة الترويــج وفق ـ ًا ملــا‬\n‫ورد يف املــادة (‪ )1/53‬مــن النظــام املشــار إليــه وإلغــاء رقــم الشــريحة‬\n‫(‪ )..........‬لنفــس املدعــى عليــه وفق ـ ًا لتعميــم صاحــب الســمو امللكــي‬\n‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪ -4‬عقوبــة‬\n‫تعزيريــة لقــاء مقاومتــه لرجــال األمــن عنــد القبــض عليــه هــذه دعــواي‬\n‫ا‬ ‫ويف هــذه اجللســة حضــر املدعــى عليــه وبســؤاله اإلجابــة أجــاب قائ ـ ً‬\n‫مــا نســب لــي يف دعــوى املدعــي العــام كلــه صحيــح إذ قمــت بترويــج‬\n\n\n                                                                                         ‫‪400‬‬\n\f      ‫الكميــة املشــار إليهــا يف الدعــوى مقابــل مبلــغ قــدره مائتــا ريــال وســلمت‬\n      ‫الكميــة واســتلمت املبلــغ واســتخدمت اجلــوال وشــريحة اإلتصــال املشــار‬\n      ‫إليهمــا يف الدعــوى يف التنســيق لهــذه العمليــة وأمــا مــا نســب لــي مــن‬\n      ‫مقاومــة رجــال الفرقــة فهــذا غيــر صحيــح فلــم أقاومهــم وليــس لــي‬\n      ‫ســوابق وأنــا تائــب إلــى اهلل وأتعهــد بعــدم العــودة لذلــك هــذه إجابتــي‬\n      ‫وجــرى االطــاع علــى األدلــة والقرائــن املشــار إليهــا يف دعــوى املدعــي‬\n      ‫العــام فوجــد مضمونهــا كمــا ذكــر ووجــد يف محضــر القبــض يف امللــف‬\n      ‫املرفــق باملعاملــة لفــة رقم(‪)1‬أنــه أثنــاء القبــض علــى املدعــى عليــه قــاوم‬\n      ‫مقاومــة عنيفــة ووجــد أن التقريــر الكيميائــي الشــرعي رقــم ‪..........‬لعــام‬\n      ‫‪1433‬ه ـ املرفــق باملعاملــة لفــة رقم(‪)12‬يتضمــن أنــه بتحليــل عينــة ممــا‬\n      ‫مت ضبطــه مــع املدعــى عليــه ثبــت إيجابيهــا ملــادة االمفيتامــن املخــدر‬\n      ‫احملظــور فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى‬\n      ‫عليــه ومصادقتــه علــى مــا نســب لــه يف الدعــوى عــدا إنــكاره مقاومــة‬\n                                                   ‫ـاء علــى مــا يلــي‪:‬‬\n                                                                     ‫الفرقــة القابضــة وبنـ ً‬\n      ‫‪-1‬ترويــج املدعــى عليــه حلبــوب االمفيتامــن احملظــورة فعــل محرم شــرع ًا‬\n      ‫ومجــرم نظامـ ًا ملــا نصــت عليــه الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومعاقــب عليــه بالعقوبة األصلية‬\n      ‫الــواردة يف املــادة الثامنــة والثالثــن والعقوبــة التكميليــة الــواردة يف‬\n      ‫املــادة السادســة واخلمســن مــن النظــام املشــار إليــه ‪-2‬ماتضمنــه التقريــر‬\n      ‫الكيميائــي املشــار إليــه ‪-3‬مــا قــرره املدعــى عليــه مــن التوبــة وتعهــده‬\n      ‫بعــدم تكــرر الفعــل منــه وعــدم وجــود ســوابق عليــه ولقلــة الكميــة‬\n      ‫ولصغــر ســنه هــذا كلــه يســتوجب تخفيــف العقوبــة عليــه والنــزول عــن‬\n      ‫احلــد األدنــى املقــرر يف املــادة الثامنــة والثالثــن وفقــا ملــا ورد يف املــادة‬\n\n\n‫‪401‬‬\n\f‫الســتني مــن النظــام املشــار إليــه ‪ - 4‬اســتخدام املدعــى عليــه للجــوال‬\n‫وشــريحة اإلتصــال املشــار إليهــا يف الدعــوى يســتوجب مصادرتــه وفق ـ ًا‬\n‫ملــا نصــت عليــه املــادة الثالثــة واخلمســن مــن النظــام املذكــور ووفق ـ ًا‬\n‫لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة املشــار إليــه ‪-5‬توجــه‬\n‫التهمــة علــى املدعــى عليــه مبقاومــة رجــال الفرقــة القابضــة وذلــك ملــا‬\n‫تضمنــه محضــر القبــض لــذا فقــد تقــرر مــا يلــي ‪:‬أو ًال ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بترويــج ثــاث حبــات مــن حبــوب االمفيتامــن املنبهــة‬\n‫احملظــورة عــن طريــق البيــع وحيــازة حبــة بقصــد الترويــج وقــررت تعزيــره‬\n‫علــى ذلــك بســجنه مــدة ســنة وســتة أشــهر تبــدأ مــن تاريــخ توقيفــه يف هذه‬\n‫القضيــة وجلــده مئــة وخمســن جلــدة مفرقــة علــى دفعــات كل دفعــة‬\n‫خمســون جلــدة وبينهمــا عشــرة أيــام وإلزامــه بدفــع غرامــة ماليــة قدرهــا‬\n‫ألــف ريــال خلزينــة الدولــة ومنعــه مــن الســفر إلــى خــارج هــذه البــاد مــدة‬\n‫ســنتني تبــدأ بعــد انتهــاء عقوبــة ســجنه املنصــوص عليهــا أعــاه ثاني ـاً‪:‬‬\n‫ثبــت لــدي اســتخدام املدعــى عليــه للجــوال وشــريحة االتصــال املشــار‬\n‫إليهــا وقــررت مصــادرة ذلــك وعــدم صــرف شــريحة االتصــال لنفــس‬\n‫املســتخدم ثالث ـاً‪ :‬قــررت تعزيــر املدعــى عليــه لقــاء توجــه التهمــة عليــه‬\n‫مبقاومــة رجــال الفرقــة القابضــة وذلــك بجلــده خمســن جلــدة دفعــة‬\n‫واحــدة وبذلــك حكمــت وبعــرض احلكــم علــى املدعــي العــام قــرر‬\n‫اعتراضــه علــى احلكــم وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة‬\n‫اعتراضيــه وبعرضــه علــى املدعــى عليــه قــرر قناعتــه باحلكــم وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪ 1434/01/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n\n\n                                                                                       ‫‪402‬‬\n\f      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n      ‫‪..........‬وتاريــخ ‪1434/2/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ‪.......... /‬برقــم ‪..........‬وتاريخ ‪1434/1/28‬هـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد‪.......... /‬يف قضيــة (مخــدرات) علــى‬\n      ‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n      ‫املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                    ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪403‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":398,"source_page_end":403,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dc91a1a5f71ac4932635d3c8cdf9d9d65383da039a7830d8533281090c5cca7a","normalized_text_hash":"f37979a7aa1130f8d6ee93bbb0b4eed2b2c6013eec447bb3e801fb874309f24d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p398-3425538"},{"id":"0577d345-eef2-59ea-adf0-50e9e8002568","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -قات -األصل براءة الذمة -اخلطأ يف العفو خير من اخلطأ يف العقوبة -حكم برد الدعوى -سند شرعي -بينة","document_number":"34207894","case_number":"34187484","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/6","year":"1434","subject":"مخدرات -ترويج -قات -األصل براءة الذمة -اخلطأ يف العفو خير من اخلطأ يف العقوبة -حكم برد الدعوى -سند شرعي -بينة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34207894 :‬تاريخه‪1434/5/6 :‬هـ‬\n                  ‫رقم الدعوى‪34187484:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34223297‬تاريخه‪1434/05/26:‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج ‪ -‬قــات ‪ -‬األصــل بــراءة الذمــة ‪ -‬اخلطــأ يف العفــو‬\n‫خيــر مــن اخلطــأ يف العقوبــة ‪ -‬حكــم بــرد الدعــوى ‪ -‬ســند شــرعي‪ -‬بينــة‬\n                                                               ‫غيــر موصلــة‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعالــى ( ومــا يتبــع أكثرهــم إال ظن ـ ًا إن الظــن ال يغنــي مــن‬\n                                  ‫احلــق شــيئا إن اهلل عليــم مبــا يفعلــون )‬\n‫‪ -2‬قولــه صلــى اهلل عليــه وســلم ( ادرؤوا احلــدود عــن املســلمني مــا‬\n‫اســتطعتم فــإن كان لــه مخــرج فخلــوا ســبيله فــإن اإلمــام أن يخطــئ‬\n                         ‫يف العفــو خيــر مــن أن يخطــئ يف العقوبــة ) ‪.‬‬\n                     ‫‪ -3‬األصل البراءة وال يزول هذا األصل إال بيقني ‪.‬‬\n                       ‫‪ -4‬القاعدة الشرعية ‪ :‬اليقني ال يزول بالشك ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج قــات عــن طريــق البيــع‬\n‫فطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة وإلغــاء‬\n‫شــريحة االتصــال املســتخدمة يف الترويــج وإعــادة املبلــغ احلكومــي‬\n‫املفقود‪،‬حيــث مت االتصــال علــى املدعــى عليــه مــن قبــل املصــدر وطلــب‬\n‫منــه حزمــة قــات فطلــب مــن املصــدر احلضــور إلــى منزلــه ثــم جــرى بعــد‬\n‫ذلــك االســتالم والتســليم ثــم دخــل املدعــى عليــه املنــزل وأقفــل البــاب‬\n                                                                                  ‫‪404‬‬\n\f      ‫فتأجــل القبــض عليــه ويف يــوم آخــر قبــض علــى املدعــى عليــه وأثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات‬\n      ‫احملظــور وأنكــر املدعــى عليــه الدعــوى‪ ،‬حيــث إن بينــة املدعــي العــام‬\n      ‫شــهادة الشــهود ‪ .‬حكــم بــرد الدعــوى وقنــع املدعــى عليــه واعتــرض‬\n      ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬      ‫املدعــي العــام بــدون الئحــة ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪ 34187484‬وتاريــخ‬\n      ‫‪ 1434/04/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341000650‬وتاريــخ‬\n      ‫‪ 1434/04/23‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/04/29‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي العــام ‪.....‬املكلــف مــن‬\n      ‫مرجعــه باخلطــاب برقــم ‪.....‬يف ‪1430/5/8‬ه ـ وحضــر حلضــوره املدعــى‬\n      ‫عليــه ‪.....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ ).....‬وادعــى املدعــي‬\n      ‫العــام يف دعــواه احملــررة لدينــا أنــه يف متــام الســاعة الثالثــة عصــرا مــن‬\n      ‫يــوم اخلميــس املوافــق ‪1434/03/19‬ه ـ وأثنــاء توفــر معلومــات ملكافحة‬\n      ‫املخــدرات بخميــس مشــيط مــن أحــد مصادرهــا الســرية عــن قيــام املتهــم‬\n      ‫املذكــور بترويــج نبــات القــات مت االتصــال عليــه مــن قبــل املصــدر ومت‬\n      ‫علــى جوالــه رقــم (‪).....‬علــى مســمع مــن أفــراد الفرقــة وطلــب منــه حزمــة‬\n      ‫مــن نبــات القــات مببلغ(‪)300‬ريــال فطلــب من املصدر احلضــور إلى منزله‬\n      ‫ومت تكليــف أحــد األفــراد بالتنكــر ومرافقــة املصــدر ومت تزويدهــم‬\n      ‫مببلــغ حكومــي مرقــم وعنــد وصولهــم إلــى املنــزل خــرج عليهــم املتهــم‬\n\n‫‪405‬‬\n\f‫املذكــور وســلم املصــدر حزمــة ملفوفــة يف قطعــة قمــاش أخضــر بلــغ‬\n‫وزنهــا (‪)445‬جــم واســتلم املبلغ احلكومــي ودخل منزله وأغلق الباب ومت‬\n‫تأجيــل القبــض عليــه إلــى وقت الحق ويف اليــوم املوافق ‪1434/04/05‬هـ‬\n‫مت القبــض علــى املتهــم املذكــور وهــو خــارج مــن منزلــه وباســتجواب‬\n‫املتهــم املذكــور بعــد إحاطتــه بالتهــم املوجهــة لــه وبجهــة التحقيــق أقــر‬\n‫باســتعمال القــات احملظــور منــذ عــام وبتحليــل عينــة ممــا مت ضبطــه ثبــت‬\n‫احتواءهــا علــى القــات مبوجــب التقريــر الكيميائــي الشــرعي رقــم(‪).....‬‬\n‫لعــام الصــادر مــن مركــز الســموم والكيميــاء مبنطقــة عســير والقــات‬\n‫مــن املــواد املدرجــة باجلــدول رقــم(‪ )4‬فئــة (أ‪،‬ج) املــواد املخــدرة امللحقــة‬\n‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد انتهــى التحقيــق مــع‬\n‫املدعــى عليــه إلــى توجيــه االتهــام لــه بترويــج حزمــة نبــات قــات محظــور‬\n‫بلــغ وزنــه (‪445‬جــم) عــن طريــق البيــع واســتخدامه لــه يف الســابق وذلــك‬\n‫لألدلــة والقرائــن التالية‪-1:‬مــا جــاء يف محضــر اســتجوابه املنــوه عنــه‬\n‫علــى الصفحتــن رقــم(‪ )2-1‬مــن ملــف التحقيــق املرفــق علــى لفــة رقــم‬\n‫(‪ )13‬واملتضمــن اســتعماله للقــات يف الســابق ‪ -2‬مــا تضمنــه محضــر‬\n‫الشــراء املنــوه عنــه واملــدون علــى الصفحتــن رقمــي(‪ )12-2‬مــن ملــف‬\n‫االســتدالل املرفــق علــى اللفــة(‪ -3 )1‬مــا تضمنــه التقريــر الكيميائــي‬\n‫الشــرعي املنــوه عنــه برقــم (‪/629‬م) لعــام ‪1434‬ه ـ املرفــق لفــه(‪)7‬‬\n‫وبالبحــث عــن ســوابقه اتضــح عــدم وجــود ســوابق مســجلة علــى املدعــى‬\n‫عليــه وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم شــرعا ومعاقــب‬\n‫عليــه نظامــا وقــد أقــدم عليــه وهــم بكامــل أهليتــه املعتبــرة شــرعا لــذا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا‪ -1:‬قضــى بــه األمــر‬\n‫الســامي الكــرمي رقــم (‪ )59366‬وتاريــخ ‪1432/12/09‬ه ـ ‪ -2‬إلزامــه‬\n\n\n                                                                                      ‫‪406‬‬\n\f      ‫بدفــع قيمــة املبلــغ احلكومــي املفقــود والبالغ(‪)300‬ريــال ‪ -3‬إلغــاء‬\n      ‫الشــريحة رقــم (‪ ).....‬وعــدم صرفهــا لنفــس املســتخدم اســتنادا لتعميــم‬\n      ‫وزيــر الداخليــة رقــم(‪ )9798‬وتاريخ‪1428/02/10-9‬ه ـ هكــذا ادعــى‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه افــاد قائــا ماذكــره‬\n      ‫املدعــي العــام يف دعــواه مــن ترويجــي القــات املخــدر فغيــر صحيــح وامــا‬\n      ‫اجلــوال املذكــور يف الدعــوى فصحيــح أنــه عائــد لــي لكــن يتصــل علــى‬\n      ‫أشــخاص وال أعلــم مــن املتصــل هكــذا أجــاب وبعــرض إجابــة املدعــى‬\n      ‫عليــه علــى املدعــي العــام وســؤاله البينــة علــى صحــة دعــواه أفــاد أن لــدي‬\n      ‫بينــة ســأحضرها اجللســة القادمــة ورفعــت اجللســة وحــدد لــه موعــد يــوم‬\n      ‫االحد املوافق ‪1434/5/5‬هـ الســاعة العاشــرة اختتمت اجللســة الســاعة‬\n      ‫احلاديــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                       ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪ 34187484‬وتاريــخ‬\n      ‫‪ 1434/04/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341000650‬وتاريــخ‬\n      ‫‪ 1434/04/23‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/05/05‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة وفيهــا حضــر املدعــي العــام واملدعــي عليــه‬\n      ‫وبســؤال املدعــى العــام هــل أحضــر مــا اســتمهل مــن أجلــه أفــاد قائــل نعــم‬\n      ‫واحضــر لشــهادة كل مــن ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪.....‬مــن مواليــد عــام ‪1410‬ه ـ ويعمــل مبكافحــة املخــدرات مبنطقــة‬\n      ‫خميس مشــيط ومن ســكانها وبســؤاله عما لديه من شــهادة قال أشــهد‬\n      ‫بــاهلل العظيــم أنــه يف يــوم اخلميــس املوافــق ‪ 1434/3/19‬مت اإلتصــال‬\n\n\n‫‪407‬‬\n\f‫علــى املدعــى عليــه ‪ .....‬علــى جوالــه رقــم (‪ ).....‬مــن قبــل املصــدر ومت‬\n‫االنتقــال إلــى منزلــه الكائــن يف حــي ‪ .......‬يف ‪ .........‬وخــرج املدعــى عليــه‬\n‫ثــم دخــل املصــدر معــه داخــل احلــوش وخــرج املصــدر بحزمــة مــن القــات‬\n‫احملظــور علمــا انــه مت تفتيــش املصــدر قبــل نزولــه ولــم أرى االســتالم‬\n‫والتســليم للقــات احملظــور هكــذا شــهد وبعــرض شــهادة الشــاهد علــى‬\n‫املدعــى عليــه قــال أمــا الشــاهد فــا أعرفــه ولــم أشــاهده مــن قبــل لــذا‬\n‫جــرى تعديــل الشــاهد مــن قبــل كل مــن ‪.....‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪.....‬مــن مواليــد ‪1393‬ه ـ ويعمــل يف مبكافحــة املخــدرات‬\n‫بخميــس مشــيط و‪.....‬ســعودي مبوجــب الســجل املدنــي رقــم ‪.....‬مــن‬\n‫مواليــد ‪1407‬ه ـ يعمــل مبكافحــة املخــدرات بخميــس مشــيط وشــهدا‬\n‫بــان الشــاهد ثقــة عــدل مقبــول الشــهادة هكــذا شــهدا وبســؤال املدعــي‬\n‫العــام هــل لديــك مزيــد بينــة أفــاد قائــا ال ســوى مــا يف أوراق املعاملــة‬\n‫هكــذا أفــاد وللرجــوع إلــى أوراق املعاملــة رفعــت اجللســة وحــدد لهــم‬\n‫موعــد يــوم االثنــن املوافــق ‪1434/5/6‬ه ـ الســاعة العاشــرة أختتمــت‬\n‫اجللســة الســاعة العاشــرة وخمــس وأربعــن دقيقــة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                              ‫‪ 1434/05/05‬ه ـ‬\n‫احلمــدهلل وحــده وبعــد ويف هــذا اليــوم الثنــن املوافــق ‪1434/05/06‬ه ـ‬\n‫أفتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر املدعــي العــام وحضــر‬\n‫املدعــى عليــه وبعــد تأمــل الدعوى ودراســة أوراق املعاملــة وبالرجوع إليها‬\n‫لــم اجــد اعتــراف او اقــرار ان املدعــي قــام بترويــج القــات احملظــور لــذا‬\n‫وبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة وبعــد اإلطــاع علــى املعاملــة‬\n‫اخلاصــة بهمــا وبنــاء علــى إنــكار املدعــى عليــه دعــوى املدعــي العــام‬\n\n\n                                                                                        ‫‪408‬‬\n\f      ‫ودفــع بــإن اجلــوال الــذي مت التنســيق بــه يف شــراء احلبــوب احملظــورة لــه‬\n      ‫وقــت الشــراء وان الــذي يتصــل عليــه أشــخاص اليعــرف منهــم وبنــاء على‬\n      ‫شــهادة الشــاهد الغيــر موصلــة حيــث شــهد بأنــه لــم يشــاهد املدعــى عليــه‬\n      ‫وقــت إســتالم وتســليم القــات احملظــور وأنــه إمنــا كان التنســيق باجلــوال‬\n      ‫الــذي مت قبــض املدعــى عليــه وهــو بحوزتــه واحلضــور إلــى بيتــه ودخــول‬\n      ‫املصــدر احلــوش ولكــون املدعــي العــام ال بينــة لديــه ســوى مــا أحضــر‬\n      ‫و أوراق املعاملــة ولــم أجــد يف أوراق املعاملــة مــا يؤكــد اتهــام املدعــى‬\n      ‫عليــه ســوى شــهادة الشــاهد واإلتصــال باجلــوال الســيما أن مــن أوراق‬\n      ‫املعاملــة لــم يتضــح ان احلديــث احلاصــل هــو ترويــج القــات احملظــور وبنــاء‬\n      ‫علــى ان اليقــن القــوي ال يرتفــع بالشــك الضعيــف والثابــت بيقــن بــراءة‬\n      ‫(((و َمــا َي َّت ِبـ ُـع‬\n                           ‫املتهــم ألنهــا أصــل فــا تــزول براءتــه إال بيقــن ولقولــه تعالــى َ‬\n      ‫بــا‬                    ‫الـ ِّـق َش ـ ْيئًا ِإ َّن َّ َ‬\n            ‫الل َع ِليـ ٌـم ِ َ‬                            ‫الظـ َّـن َل ُي ْغ ِنــي مِ ـ َـن ْ َ‬\n                                                                                             ‫كث َُر ُهـ ْـم ِإ َّل َظ ًّنــا ِإ َّن َّ‬ ‫َأ ْ‬\n      ‫ـون)) وعــن عائشــة رضــي اهلل عنهــا قالــت‪ :‬قــال رســول اهلل صلــى‬                                                    ‫َي ْف َع ُلـ َ‬\n      ‫اهلل عليه وســلم ‪« :‬ادْ َرؤوا احلُدو َد عن املســلمني ما اســتطعتم‪ ،‬فإن كان‬\n      ‫لــه مخــرج‪ ،‬فخلــوا ســبيله‪ .‬فــإن اإلمــام أن يخطــئ يف العفــو‪ ،‬خيــر مــن أن‬\n      ‫يخطــئ يف العقوبــة» رواه الترمــذي مرفوع ـ ًا والقاعــدة الشــرعية تقــول‬\n      ‫اليقــن ال يــزول بالشــك واألصــل يف املتهــم البــراءة وبنــاء علــى انــه متــى‬\n      ‫تطــرق الشــك واالحتمــال إلــي قرائــن اإلدانــة وجــب احلكــم ببــراءة املتهــم‬\n      ‫لعــدم كفايــة األدلــة إذ الشــك يفســر ملصلحــة املتهــم وحيــث اليوجــد‬\n      ‫ســوابق مســجلة علــى املدعــى عليــه لذلــك كلــه فقــد رددت دعــوى‬\n      ‫املدعــى العــام وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى هــذا مــا‬\n      ‫ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه‬\n      ‫بــه وأمــا املدعــي العــام فقــرر املعارضــة وطلــب رفــع احلكــم لالســتئناف‬\n\n\n‫‪409‬‬\n\f‫بــدون الئحــة اعتراضيــة وأمــرت بتنظيــم القــرار الــازم لذلــك ورفــع‬\n‫كامــل اوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم واختتمــت‬\n‫اجللســة الســاعة العاشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/6‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط رقــم‬\n‫‪ 341000650‬وتاريــخ ‪1434/5/8‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ..... /‬رقــم ‪34207894‬‬\n‫وتاريــخ ‪1434/5/6‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ (...../‬ســعودي‬\n‫اجلنســية ) يف قضيــة ( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪410‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":404,"source_page_end":410,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d095c3f12f834ff61ece31a6f36c4f5546921ecc4ddde5e41327917116d02848","normalized_text_hash":"399ae251eb4299f3892380776b03a43bb330c506dbd36e1384f62faf986d9a2b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p404-34207894"},{"id":"dffa5fa4-2a4c-5797-b4ea-509a41f78380","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -املدعى عليه أجنبي يتحدث العربية -عدم مصادرة املبلغ -األصل فيما بيد املسلم فهو ملكه.","document_number":"34223849","case_number":"34203476","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة برجال أملع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -املدعى عليه أجنبي يتحدث العربية -عدم مصادرة املبلغ -األصل فيما بيد املسلم فهو ملكه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34223849:‬تاريخه‪1434/5/27:‬هـ‬\n                        ‫رقم الدعوى‪34203476:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34324940‬تاريخه‪1434/07/17:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬نقــل بقصــد الترويــج ‪ -‬قــات ‪ -‬املدعــى عليــه أجنبــي يتحــدث‬\n       ‫العربيــة ‪ -‬عــدم مصــادرة املبلــغ ‪ -‬األصــل فيمــا بيــد املســلم فهــو ملكــه‪.‬‬\n\n\n\n\n      ‫‪ -1‬جــاء يف مطالــب أولــي النهــى (‪ )67/4‬مــا نصــه (األصــل فيمــا بيــد‬\n                                                            ‫املســلم أنــه ملكــه ) ‪.‬‬\n                                                        ‫‪ -2‬األصل براءة الذمة ‪.‬‬\n      ‫‪ -3‬وملــا جــاء يف املــادة الثالثــة بفقرتهــا الثالثــة مــن نظــام املخــدرات‬\n      ‫الســابق يف القــرار رقــم (‪ )11‬تاريــخ ‪1374/2/1‬ه ـ ونصهــا‪(:‬كل شــخص‬\n      ‫مــن غيــر الصيادلــة واملرخــص لهــم باالجتــار باجلواهــر املخــدرة ثبتــت‬\n      ‫حيازتــه لشــيء مــن املخــدرات أو توســط يف تصريفهــا بالبيــع أو اإلرســال‬\n      ‫أو اإلهــداء أو النقــل مــن جهــة أخــرى يعاقــب بالســجن ملــدة خمــس‬\n      ‫ســنوات ويغــرم بغرامــة ماليــة قدرهــا عشــرة آاللف ريال عربي ســعودي)‪.‬‬\n       ‫‪ -4‬املادة الثالثة من القرار الوزاري رقم (‪ )2057‬وتاريخ ‪1404/5/26‬هـ‪.‬‬\n      ‫‪ -5‬املادة الرابعة من القرار الوزاري رقم (‪ )2057‬وتاريخ ‪1404/5/26‬هـ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات مقابــل مبلــغ مالــي‬\n      ‫بقصــد االجتــار وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n\n‫‪411‬‬\n\f‫تعزيريــة واحلكــم بإبعــاده عــن البــاد ‪،‬حيــث مت االشــتباه مــن مقبــل‬\n‫فرقــة الضبــط األمنــي بشــاحنة يقودهــا املدعــى عليــه وبتفتيــش ضبــط‬\n‫معــه مبلــغ مالــي وبتفتيشــه الشــاحنة ضبــط بهــا كميــة مــن نبــات يشــتبه‬\n‫أن يكــون نبــات القــات وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n‫العينــة املضبوطــة لنبــات القــات احملظــور ‪،‬صــادق املدعــى عليــه علــى‬\n‫الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بســجن املدعــى عليه‬\n‫ملــدة ســنتني وبغرامــة ماليــة قدرهــا ألــف ريــال وبإبعــاده عــن اململكــة‬\n‫بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه وأن ال يســمح لــه بالعــودة‬\n‫إليهــا فيمــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة ‪،‬ســقوط طلــب‬\n‫املدعــي العــام بطلــب مصــادرة املبلــغ املذكــور يف الدعــوى و قنــع املدعــى‬\n‫‪،‬وصــدق احلكــم مــن‬ ‫عليــه باحلكــم واعتــرض املدعــي العــام بالئحــة ُ‬\n                                                       ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬رئيــس احملكمــة العامــة برجــال أملــع‬\n‫وبناء على املعاملة احملالة لنا برقم ‪ 34203476‬وتاريخ ‪1434/05/04‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 341085145‬وتاريــخ ‪ 1434/05/04‬ه ـ‬\n‫ففي يوم الثالثاء املوافق‪ 1434/05/21‬هـ افتتحت اجللســة الســاعة ‪00‬‬\n‫‪ 12 :‬وكانــت املعاملــة قــد وردتنــا مــن رئيــس دائــرة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة ‪ .....‬برقــم‪.....‬يف ‪1434/5/1‬ه وعليــه حضــر املدعــي‬\n‫العــام بدائــرة التحقيــق واالدعــاء العــام مبحافظــة ‪..... ....‬لتمثيــل االدعــاء‬\n‫العــام والقيــام باعمــال املرافعــة اثنــاء اجللســات واملكلــف باالدعــاء العــام‬\n‫مبوجــب خطــاب رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة ‪....‬‬\n\n                                                                                       ‫‪412‬‬\n\f      ‫رقــم ‪.....‬يف ‪1434/3/12‬ه وادعــى علــى احلاضــر معــه ‪.....‬باكســتاني‬\n      ‫اجلنســية مبوجــب االقامــة رقــم ‪.....‬قائــا يف دعــواه عليــه بصفتــي مدعيـ ًا‬\n      ‫عام ـ ًا بدائــرة التحقيــق واالدعــاء العــام مبحافظــة (‪ )...‬أدعــى علــى ‪...../‬‬\n      ‫‪.....‬باكســتاني اجلنســية برخصــة اإلقامــة رقــم (‪ ).....‬البالــغ مــن العمــر‬\n      ‫(‪ )37‬عام ـ ًا ســائق شــاحنة متعلــم مســلم يتحــدث العربيــة‪ -‬املقبــوض‬\n      ‫عليــه بتاريــخ ‪1434/3/9‬ه ـ واملــودع بوحــدة ســجن محافظــة ‪ ....‬مبوجــب‬\n      ‫أمــر متديــد التوقيــف رقــم (‪ ).....‬وتاريــخ ‪1434/3/23‬ه ـ اســتناد ًا للمــادة‬\n      ‫(‪ )114‬مــن نظــام اإلجــراءات اجلزائيــة حيــث أنــه عنــد الســاعة السادســة‬\n      ‫مــن صبــاح يــوم االثنــن املوافــق ‪1434/3/9‬ه ـ مت االشــتباه مــن قبــل فرقة‬\n      ‫الضبــط األمنــي مبركــز ‪.....‬بســيارة شــاحنه نــوع ( ‪ ).......‬اللــون (أزرق)‬\n      ‫صنــع عــام (‪2000‬م) حتمــل اللوحــة رقــم (‪ ).....‬بقيــادة املدعــى عليــه‬\n      ‫وبتفتيشــه ضبــط معــه مبلــغ مالــي قــدره( ‪ )13000‬ثالثــة عشــر ألــف‬\n      ‫ريــال وبتفتيــش الشــاحنة ضبــط بهــا (‪ )380‬ثالثمائــة وثمانــون حزمــة‬\n      ‫يشــتبه أنهــا مــن نبــات القــات احملظــور تــزن(‪ )115‬مائــة وخمســة عشــر‬\n      ‫كيلــو مخبــأة بداخــل صهريــج الديــزل وبالــدرج اجلانبــي للتيــدر وقــد‬\n      ‫أثبــت التقريــر الكيمائــي الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1434/4/22‬ه ـ‬\n      ‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n      ‫مبنطقــة عســير أن العينــة إيجابيــة لنبــات القــات وهــو مــن املــواد املدرجــة‬\n      ‫بجــداول املخــدرات واملؤثــرات العقليــة باجلــدول (‪ )4‬الرابــع الفئــة (‪)5‬‬\n      ‫اخلامســة املرفــق بتعميــم صاحــب الســمو امللكــي النائــب الثانــي لرئيــس‬\n      ‫مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )74831‬وتاريــخ ‪1431/7/9‬ه ـ‬\n      ‫وباســتجوابه املدعــى عليــه ‪/‬أقــر بنقــل (‪ )380‬ثالثمائــة وثمانــون حزمــة‬\n      ‫تــزن(‪ )115‬مائــة وخمســة عشــر كيلــو مــن نبــات القــات احملظــور مــن‬\n\n\n‫‪413‬‬\n\f‫محافظــة ‪ ....‬إلــى محافظــة ‪ ......‬مقابــل (‪ )7000‬ســبعة آالف وانتهــى‬\n‫التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه ‪/‬بنقــل (‪ )380‬ثالثمائــة‬\n‫وثمانــون حزمــة تــزن(‪ )115‬مائــة وخمســة عشــر كيلــو مــن نبــات القــات‬\n‫احملظــور مقابــل مبلــغ مالــي بقصــد االجتــار وذلــك لألدلــة والقرائــن‬\n‫التاليــة‪-1 -:‬ماتضمنتــه محضــر القبــض والتفتيــش املــدون علــى‬\n‫الصفحتــن رقــم (‪ )7.6‬مــن تقريــر األحــوال األمنيــة املوحــد لفــة رقــم (‪)2‬‬\n‫‪-2‬ماتضمنــه إقــراره املنــوه عنــه واملــدون علــى الصفحة رقــم (‪ )5‬من ملف‬\n‫ضبــط إجــراءات قضيــة مخــدرات لفــة رقــم (‪-3)17‬ماتضمنتــه التقريــر‬\n‫الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪)25‬وبالبحــث عــن‬\n‫ســوابقه أتضــح عــدم وجــود ســوابق مســجلة عليــه وحيــث إن مــا أقــدم‬\n‫عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة فعــل محــرم شــرع ًا ومجــرم‬\n‫نظام ـ ًا ومعاقــب عليــه مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬وتاريــخ‬\n‫‪1374/2/1‬ه بعقوباتــه األصليــة والتكميليــة لــذا اطلــب إثبــات مــا اســند‬\n‫إليــه واحلكــم مبــا يلــي ‪-1:‬بعقوبــة تعزيريــة وفقــا ملــا تضمنتــه املــادة (‪)3‬‬\n‫الثالثــة مــن القــرار املشــار اليــه لقــاء نقــل (‪)380‬ثالثمائــة وثمانــون حزمــة‬\n‫تــزن (‪)115‬مائــة وخمســة عشــر كيلــو مــن نبــات القــات احملظــور مقابــل‬\n‫مبلــغ مالــي بقصــد االجتــار ‪-2‬احلكــم بإبعــاده عــن البــاد بعــد تنفيــذ‬\n‫العقوبــة بحقــه وفقــا ملــا تضمنتــه الفقــرة (ج) مــن املــادة (‪ )4‬الرابعــة مــن‬\n‫القــرار املشــار إليــه ‪-3‬مصــادرة املبلــغ املالــي املضبــوط وقــدره (‪)13000‬‬\n‫ثالثــة عشــر ألــف ريــال كونــه مت إخفــاء حقيقتــه ولم يثبت جلهــة التحقيق‬\n‫ملكيــة املدعــى عليــه لــه هكــذا ادعــى وبســؤال املدعى عليــه عن دعوى‬\n‫املدعــي العــام أقــر بجميــع مــا جــاء فيهــا وقيامــه بنقــل مــا بلــغ وزنــه مائــة‬\n‫وخمســة عشــر كيلــو مــن نبــات القــات مبلــغ قــدره ســبعة اآلف ريــال لــم‬\n\n\n                                                                                            ‫‪414‬‬\n\f      ‫تقبــض بقصــد االجتــار هكــذا أجــاب كمــا جــرى ســؤال املدعــى عليــه‬\n      ‫عــن املبلــغ املضبــوط عنــد القبــض وقــدره ثالثــة عشــر ألــف ريــال فأجــاب‬\n      ‫قائ ـاً‪ :‬هــذا املــال يعــود لــي خاصــة وهــو حصيلــة ملجمــوع رواتبــي للعــام‬\n      ‫املاضــي وليــس لــه عالقــة بنقــل القــات هكــذا أجــاب وبســؤال املدعــي‬\n      ‫العــام عــن بينتــه حيــال مــا ذكــر عــن هــذا املــال أجــاب قائــا ليــس لــدي‬\n      ‫ســوى مــا يف أوراق املعاملــة هكــذا أجــاب وبالرجــوع إلــى أوراق املعاملــة‬\n      ‫أطلعــت علــى التقريــر الكيميائــي رقــم ‪.....‬وتاريــخ ‪1434/3/22‬ه‬\n      ‫املتضمــن إيجابيــة العينــة املرســلة لنبات القــات كما اطلعت على كرت‬\n      ‫ســوابق املدعــى عليــه يف املعاملــة فوجدتــه يخلــو مــن الســوابق وبعــرض‬\n      ‫مــا جــاء يف التقريــر الكيميائــي علــى املدعــى عليــه صــادق علــى مــا جــاء‬\n      ‫فيــه كمــا أطلعــت علــى قــرار اعتــراف املدعــى عليــه يف دفتــر التحقيــق‬\n      ‫صفحــة رقــم ( ‪ )5‬واملتضمــن أقــرر انــا املدعــو ‪.....‬باكســتاني اجلنســية‬\n      ‫مقيــم مبوجــب اإلقامــة رقــم ‪.....‬وتاريــخ ‪1432/12/27‬ه ـ مصدرهــا‬\n      ‫اخلــرج وانــا بكامــل بكامــل اهليتــي املعتبــرة شــرعا حيــث ادلــي مبــا‬\n      ‫يلــي ‪:‬مت القبــض علــي مــن قبــل نقطــة امــن ‪ .....‬حيــث كان بقيادتــي‬\n      ‫ســيارة ‪ ....‬تريــا موديــل ‪2000‬رقــم اللوحة‪.....‬تعــود ملكيتهــا للمدعــو‬\n      ‫‪ .....‬وبتفتيــش الســيارة عثــر علــى كميــة مــن نبــات القــات كانــت مخبــأه‬\n      ‫يف تانكــي الديــزل يف الــدرج اجلانبــي للتديــر بلــغ عددهــا ‪ 380‬ثالثمائــة‬\n      ‫وثمانــن حزمــة اتضــح لــي أنهــا تــزن ‪ 155‬مائــة وخمســة عشــر كيلــو‬\n      ‫جرام ـ ًا حيــث إن هــذه الكميــة عائــدة لشــخص باكســتاني ذكرتــه‬\n      ‫جلهــة التحقيــق قــد اتفقــت معــه علــى نقلهــا مــن محافظــة‪ ....‬الــى محافظــة‬\n      ‫‪ ....‬مقابــل مبلــغ مالــي قــدره ســبعة االف ريــال ســعودي لــم أســتلم مــن‬\n      ‫املبلــغ أي شــيء وحيــث ان مالــك الســيارة ليــس لــه أي علــم او عالقــة‬\n\n\n‫‪415‬‬\n\f‫بكميــة القــات املذكــورة وقــد اســتلمت الســيارة مــن شــخص ســوري‬\n‫يعمــل مــع مالــك الســيارة وليــس لــه أي عالقــة بكميــة القــات و حيــث‬\n‫ان املبلــغ الــذي ضبــط بحوزتــي وقــدره ثالثــة عشــر الــف ريــال ليــس لــه‬\n‫عالقــة بكميــة القــات املذكــورة وليــس مــن عائــدات النقل للقــات او أي‬\n‫مخــدرات حيــث ان هــذا اول مــرة اقــدم علــى مثــل هــذا العمــل وعلــى ذلــك‬\n‫اقــرر واوقــع واصــادق وبعرضــه علــى املدعــى عليــه قــال هــذا اإلقــرار‬\n‫صحيــح وليــس فيــه مــا يخالــف مــا ذكــرت يف اإلجابــة علــى الدعــوى‬\n‫هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــرا إلــى‬\n‫أن املدعــى عليــه أقــر بقيامــه بنقــل القــات باملبلــغ املذكــور يف الدعــوى‬\n‫ونظــرا إلــى أن األصــل يف املســلم أنــه ميلــك مــا كان حتــت يــده مــن مــال‬\n‫ونحــوه إال إذا ثبــت خــاف ذلــك بالبينــة الشــرعية أو مبــا أقــر بــه املكلف‬\n‫علــى نفســه وذلــك ألن األصــل بــراءة الذمــة جــاء يف مطالــب أولــي النهــى‬\n‫(‪ )67/4‬مــا نصــه‪( :‬األصــل فيمــا بيــد املســلم أنــه ملكــه ) وملــا جــاء يف‬\n‫املــادة الثالثــة بفقرتهــا الثالثــة مــن نظــام املخــدرات الســابق يف القــرار‬\n‫رقــم (‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ ونصهــا مــا يلــي‪(:‬كل شــخص مــن‬\n‫غيــر الصيادلــة واملرخــص لهــم باإلجتــار باجلواهــر املخــدرة ثبتــت حيازتــه‬\n‫لشــيء مــن املخــدرات أو توســط يف تصريفهــا بالبيــع أو اإلرســال أو‬\n‫اإلهــداء أو النقــل مــن جهــة أخــرى يعاقــب بالســجن ملــدة خمــس ســنوات‬\n‫ويغــرم بغرامــة ماليــة قدرهــا عشــرة اآللــف ريــال عربــي ســعودي)‪.‬ونظرا‬\n‫إلــى مــا جــاء يف القــرار الــوزاري رقــم (‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ‬\n‫املتضمــن أن عقوبــات الســجن والغرامــة الــواردة بالقــرار رقــم( ‪)11‬‬\n‫لعــام ‪1374‬ه ـ هــي احلــد األعلــى ملــا ميكــن للجهــة املختصــة احلكــم بــه‬\n‫علــى املتهــم وعلــى أال تقــل يف عقوبــة االجتــار باملــواد املخــدرة بالبيــع أو‬\n\n\n                                                                                       ‫‪416‬‬\n\f      ‫اإلهــداء أو اإلرســال أو النقــل مــده ال تقــل عــن ســنتني و ال تتجــاوز خمــس‬\n      ‫ســنوات كمــا يف املــادة الثالثــة مــن هــذا القــرار وبنــاء علــى مــا جــاء يف‬\n      ‫املــادة الرابعــة مــن القــرار املشــار إليــه والتــي تتضمــن إبعــاد األجنبــي عــن‬\n      ‫البــاد بعــد تنفيــذ العقوبــة بحقــه وفــق مــا هــو مفصــل فيهــا‪ .‬وجلميــع مــا‬\n      ‫ســبق قــررت مــا يلــي ألجــل احلــق العــام ‪:‬أوالً‪ /‬ســجن املدعــى عليــه ملــدة‬\n      ‫ســنتني مــن تاريــخ إيقافــه يف هــذه القضيــة‪ .‬ثانيــا‪ /‬غرامــة ماليــة قدرهــا‬\n      ‫ألــف ريــال ‪.‬ثالثــا‪ /‬إبعــاد املدعــى عليــه عــن اململكــة بعــد تنفيــذ العقوبــة‬\n      ‫احملكــوم بهــا عليــه وأن ال يســمح لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح‬\n      ‫بــه تعليمــات احلــج والعمــرة رابع ـاً‪ /‬ســقوط طلــب املدعــي العــام بطلــب‬\n      ‫مصــادرة املبلــغ املذكــور يف الدعــوى ملــا ســبق بيانــه وبعــرض احلكــم‬\n      ‫علــى املدعــى عليــه قــرر قناعتــه بــه وقــرر املدعــي العــام اعتراضــه وطلــب‬\n      ‫االســتئناف ومتكينــه مــن تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وصلــى‬\n                            ‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/5 /21‬ه‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة ‪ ......‬املكلــف برقــم‬\n      ‫‪ 341085145‬وتاريــخ ‪1434 /8/ 28‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة رئيــس احملكمــة الشــيخ ‪..... /‬برقــم ‪ 34223849‬وتاريــخ ‪/ 27‬‬\n      ‫‪1434 / 5‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪ -..... /‬باكســتاني‬\n      ‫اجلنســية ‪ -‬يف قضيــة ( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪417‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":411,"source_page_end":417,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1840d1e9d6892bb17ead9613d874069c6f28d8723b58205d33e6a365739a71f5","normalized_text_hash":"d7b2eebe3a367037d1c21d4057350f6c5ee4e551cba830cd2d2f457310dc57b6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p411-34223849"},{"id":"e26dc64f-eda3-5a07-be75-2b28c2fc59f7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -هروب من رجال األمن - التعزير بالسجن واجللد -شبهة ترويج -تعزير للشبهة.","document_number":"34243861","case_number":"34269340","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/18","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -هروب من رجال األمن - التعزير بالسجن واجللد -شبهة ترويج -تعزير للشبهة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34243861:‬تاريخه‪1434/6/18 :‬هـ‬\n                  ‫رقم الدعوى‪34269340:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34267598‬تاريخه‪1434/07/15:‬هـ‬\n\n\n‫مخــدرات ‪ -‬نقــل بقصــد الترويــج‪ -‬قــات ‪ -‬هــروب مــن رجــال األمــن ‪-‬‬\n        ‫التعزيــر بالســجن واجللــد ‪ -‬شــبهة ترويــج ‪ -‬تعزيــر للشــبهة‪.‬‬\n\n\n\n\n                 ‫املادة الرابعة من القرار الوزاري رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد الترويــج‬\n‫وصــدم ســيارة الدوريــة األمنيــة وهروبــه مــن رجــال األمــن ‪،‬حيــث كان‬\n‫يقــود ســيارة فطلبــت منــه الدوريــة األمنيــة التوقــف فلــم يتوقــف وقــام‬\n‫بصــدم ســيارة الدوريــة والذ بالفــرار وبتفتيــش الســيارة عثــر علــى نبــات‬\n‫القــات ثــم قــام املدعــى عليــه بتســليم نفســه وطلــب املدعــي العــام إثبــات‬\n‫مــا أســند إليــه واحلكــم بتعزيــره لقــاء هروبــه مــن رجــال األمــن وصدمــه‬\n‫الدوريــة وأثبــت التقريــر الكيميائــي إيجابيــة العينــة املضبوطــة لنبــات‬\n‫القــات احملظــور واعتــرف املدعــى عليــه بحيــازة القات بقصد االســتعمال‬\n‫الشــخصي وصــدم الدوريــة األمنيــة والهــروب مــن رجــال األمــن وأنكــر‬\n‫الترويــج ‪،‬وملــا كانــت بينــة املدعــي العــام علــى الترويــج كبــر كميــة‬\n‫القــات ‪ ،‬مت تعزيــره بالســجن واجللــد وصــرف النظــر عــن طلــب املدعــي‬\n‫العــام مبعاقبتــه وفــق املــادة الثالثــة مــن القــرار املشــار إليــه لعــدم وجــود‬\n\n                                                                                          ‫‪418‬‬\n\f      ‫البينــة علــى الترويــج وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                            ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬   ‫الئحــة ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34269340‬وتاريــخ ‪ 1434/06/12‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341416140‬وتاريــخ ‪ 1434/06/12‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافق‪1434/06/17‬هـ افتتحت اجللســة الســاعة ‪09 : 45‬وفيها‬\n      ‫حضــر املدعــي العــام ‪.....‬واملكلــف بحضــور اجللســات باخلطــاب رقـ ــم (‬\n      ‫‪ ).....‬يف ‪1433/3/22‬ه ـ وادعــى علــى احلاضــر معــه باملجلــس الشــرعي‬\n      ‫الســجني ‪..... /‬ســعودي اجلنســية بالســجل املدنــي رقــم (‪ ).....‬قائــا يف‬\n      ‫دعــواه ‪ :‬انــه بتاريــخ ‪1434/3/18‬ه ـ وأثنــاء قيــام دوريــة محافظــة أحــد‬\n      ‫املســارحة بواجبهــا امليدانــي يف احملافظــة مت مشــاهدة ســيارة مــن‬\n      ‫نــوع ســنة الصنــع ‪ 2012‬رقــم اللوحــة (‪ ).....‬قادمــة مــن قريــة ‪.....‬عائــدة‬\n      ‫ملكيتهــا ل‪(.....‬لــم يوجــه لــه االتهــام وســلمت لــه) فتــم التأشــير لقائدهــا‬\n      ‫بالوقــوف فلــم يتوقــف فتــم مطاردتــه مــن قبــل الدوريــة وقــام بصــدم‬\n      ‫ســيارة الدوريــة وعندهــا قــام بتــرك الســيارة والذ بالفــرار (فــرزت لذلــك‬\n      ‫أوراق مســتقلة) وبتفتيشــها عثــر بهــا علــى كميــة مــن نبــات القــات‬\n      ‫احملظــور بلــغ وزنهــا(‪19 . 750‬كجــم) تســعة عشــر كيلــو وســبعمائة‬\n      ‫وخمســن جرام ـ ًا ‪ ،‬مبوجــب التقريــر الكيميائــي الشــرعي رقــم (‪.....‬‬\n      ‫لعــام ‪1434‬هــ) الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبية‬\n      ‫الشــرعية بجــازان ‪ ،‬وبتاريــخ ‪1434/5/18‬ه ـ قــام املتهــم املذكــور‬\n\n‫‪419‬‬\n\f                              ‫بتســليم نفســه ملكافحــة املخــدرات بصامطــة‪.‬‬\n‫وبإســتجواب املدعــى عليــه والتحقيــق معــه أســفر التحقيــق عــن توجيــه‬\n‫االتهــام إليــه بنقــل هــذه الكميــة مــن نبــات القــات احملظــور بقصــد‬\n‫الترويــج وبصدمــة لســيارة الدوريــة الرســمية واإلضــرار بهــا وهروبــه مــن‬\n‫رجــال األمــن وذلــك لألدلــة املرفقــة بــأوراق القضيــة ‪ .‬وحيــث إن مــا أقــدم‬\n‫عليــه املتهــم املذكــور فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب‬\n‫قــرار مجلــس الــوزراء رقــم (‪ )11‬لعام‪1374‬ه ـ ومــا حلــق بــه تعديــات فإنــه‬\n‫يتعــن إحالتــه إلــى احملكمــة اجلزائيــة اســتنادا للمادتــن (‪ 126‬ـ ‪)128‬‬\n                      ‫مــن نظــام اإلجــراءات اجلزائيــة وذلــك لطلــب مــا يلــي‪:‬‬\n‫‪/1‬إثبــات إدانتــه مبــا اســند إليــه واحلكــم بتعزيــره يف ضــوء املــادة‬\n‫(الثالثــة) مــن القــرار املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي‬\n                                      ‫رقــم (‪ )59633‬وتاريخ‪1432/12/9‬ه ـ‬\n‫‪2‬ـ احلكــم بتعزيــره شــرع ًا هروبــه مــن رجــال األمــن ‪3 .‬ـ احلكــم بتعزيــره‬\n‫شــرع ًا لقــاء صدمــه لســيارة الدوريــة الرســمية واإلضــرار بهــا مــع تشــديد‬\n‫العقوبــة عليــه لقــاء ذلــك‪ .‬وبســؤال املدعــى عليــه أجــاب قائــا ‪ :‬أعتــرف‬\n‫بالقبــض علــي بتاريــخ ‪1434/3/18‬ه ـ وبحوزتــي بداخــل الســيارة التــي‬\n‫كانــت بقيادتــي والتــي لــذت منهــا بالفــرار أثنــاء القبــض كميــة مــن‬\n‫نبــات القــات احملظــور بلــغ وزنهــا (‪19 . 750‬كجــم) تســعة عشــر كيلــو‬\n‫وســبعمائة وخمســن جــرام لغــرض االســتعمال الشــخصي وأنكــر‬\n‫حيازتــي لهــا لغــرض الترويــج وأعتــرف بقيامــي بصــدم الدوريــة وهروبــي‬\n‫مــن رجــال األمــن أثنــاء القبــض علــي بهــذا أجــاب ‪ ،‬ســألت املدعــى العــام‬\n‫هــل لديــه بينــة علــى صحــة دعــواه ضــد املدعــى عليــه يف احليــازة بقصــد‬\n‫الترويــج فقــال ليــس لــدي بينــة ســوى كبــر حجــم الكميــة ومــا جــاء‬\n\n\n                                                                                        ‫‪420‬‬\n\f      ‫بــأوراق القضيــة ‪ ،‬وباإلطــاع علــى أوراق القضيــة وجــد ضمنهــا التقريــر‬\n      ‫الكيميائــي الشــرعي رقــم (‪.....‬لعــام ‪1434‬هــ) واملتضمــن ثبــوت إيجابيــة‬\n      ‫العينــة املرســلة مــن الكميــة لنبــات القــات احملظــور ‪ ،‬كمــا وجــد‬\n      ‫كــرت بصمــات املدعــى عليــه واملتضمــن وجــود ســابقتني مســجلة عليــه‬\n      ‫وهــى‪1 ( :‬ـ اســتعمال املخــدرات ومقاومــة رجــال األمــن وهــروب مــن‬\n      ‫الســلطة وترويــج املخــدرات ـ ـ و‪2‬ـ حيــازة املخــدرات ) وقــد صــادق عليهــا‪.‬‬\n      ‫وعليــه فبنــاء علــى ســماع الدعــوى واإلجابــة وعــدم وجــود بينــة للمدعــي‬\n      ‫العــام علــى صحــة دعــواه ضــد املدعــى عليــه يف حيازتــه لهــذه الكميــة‬\n      ‫لغــرض الترويــج فلــم يثبــت لــدي ذلــك شــرعا وصرفــت النظــر عــن طلبــه‬\n      ‫تعزيــر املدعــى عليــه وفــق املــادة ( الثالثــة ) مــن القــرار الــوزاري رقــم ( ‪11‬‬\n      ‫) للعــام ‪1374‬ه ـ ـ وثبــت لــدي شــرعا إدانــة املدعــى عليــه ‪..... /‬بالقبــض‬\n      ‫عليــه وبحوزتــه بداخــل الســيارة التــي كانــت بقيادتــه كميــة مــن نبــات‬\n      ‫القــات احملظــور بلــغ وزنهــا ( ‪19 . 750‬كجــم ) تســعة عشــر كيلــو‬\n      ‫وســبعمائة وخمســون جــرام لغــرض اإلســتعمال الشــخصي ويســتحق‬\n      ‫التعزيــر علــى ذلــك وفــق املــادة ( الرابعــة ) مــن القــرار الــوزاري رقــم ( ‪11‬‬\n      ‫) لعــام ‪1374‬ه ـ لــذا فقــد حكمــت بتعزيــره بالســجن ملــدة ثمانيــة عشــر‬\n      ‫شــهرا اعتبــارا مــن تاريــخ دخولــه الســجن ( حيــث أنــه قبــض عليــه بتاريــخ‬\n      ‫‪1434/5/18‬هـ ) ‪ ،‬ونظرا لكبر حجم الكمية تتوجه إليه الشــبهة يف‬\n      ‫احليــازة بقصــد الترويــج ولهــذه الشــبهة ولهروبــه مــن رجــال األمــن وقيامــه‬\n      ‫بصــدم الدوريــة حكمــت بتعزيــره بالســجن ملــدة ســبعة أشــهر إضافــة ملــا‬\n      ‫صــدر بحقــه مــن ســجن أعــاه و جلــده مائتــن جلــدة علنــا علــى أربــع‬\n      ‫دفعــات كل دفعــة خمســون جلــدة بينهــا وبــن التــي تليهــا خمســة عشــر‬\n      ‫يومــا بذلــك حكمــت وأفهمــت املدعــى عليــه باحلكــم فقــرر القناعــة‬\n\n\n‫‪421‬‬\n\f‫وقــرر املدعــي العــام معارضتــه وطلــب رفــع احلكــم حملكمــة االســتئناف‬\n‫دون الئحــة اعتراضيــة وبــه حــرر يف ‪1434/6/17‬ه ـ وصلــى اهلل علــى‬\n                               ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n‫‪ 341416140‬وتاريــخ ‪1434/6/24‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 34243861‬وتاريــخ‬\n‫‪1434/6/18‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪..... /‬يف قضيــة‬\n‫(قــات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪422‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":418,"source_page_end":422,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fd577e18864dcc6ee99288cfa6004b7607a0cc8f1988340e240a6e62c57522ea","normalized_text_hash":"59278aaa6b5417d6d45c8b764dbb0b695d868aec344fa52a73a4a9e328f35842","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p418-34243861"},{"id":"e5a66014-046b-5c68-8932-210f1a1aab0f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج مادة الكوكاين -حيازة حشيش بقصد التعاطي -هروب من الفرقة القابضة -تستر -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملصادرة واملنع من السفر والغرامة.","document_number":"3427326","case_number":"34297291","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/19","year":"1434","subject":"مخدرات -ترويج مادة الكوكاين -حيازة حشيش بقصد التعاطي -هروب من الفرقة القابضة -تستر -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملصادرة واملنع من السفر والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3427326 :‬تاريخه ‪1434/7/19 :‬هـ‬\n                       ‫رقم الدعوى ‪34297291 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34375336‬تاريخه‪1434/12/02:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج مــادة الكوكايــن ‪ -‬حيــازة حشــيش بقصد التعاطي‬\n      ‫‪ -‬هــروب مــن الفرقــة القابضــة ‪ -‬تســتر‪ -‬إقــرار‪ -‬إقامــة حــد املســكر علــى‬\n      ‫متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واجللــد واملصــادرة واملنــع مــن‬\n                                                                   ‫الســفر والغرامة‪.‬‬\n\n\n\n             ‫‪ .1‬املادة ( ‪ ) 38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n             ‫‪ .2‬املادة ( ‪ ) 53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n             ‫‪ .3‬املادة ( ‪ ) 56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج مــادة الكوكايــن‪،‬‬\n      ‫وهروبــه مــن الفرقــة القابضــة وتســتره علــى مصــدر مــا مت ضبطــه‬\n      ‫معــه ‪ ،‬حيــث ورد بــاغ للجهــة األمنيــة مــن أحــد املصــادر عــن قيــام‬\n      ‫املدعــى عليــه بترويــج مــادة الكوكايــن ‪،‬واســتعد املصــدر وهــو أحــد‬\n      ‫العاملــن يف إدارة املكافحــة باإلطاحــة بــه ‪ ،‬ومت تزويــده باملبلــغ املرقــم‬\n      ‫وقــدره ألفــي ريــال؛ ليقــوم بعمليــة الشــراء‪ ،‬واتفــق علــى املــكان‪ ،‬وســلم‬\n      ‫املدعــى عليــه املصــدر كيــس نايلــون بداخلــه مــادة يشــتبه أن تكــون‬\n      ‫مــن الكوكايــن املخــدر ووزنهــا جرامــا واحــدا وأربعــة أعشــار اجلــرام‪،‬‬\n\n\n‫‪423‬‬\n\f‫واســتلم املذكــور مــن املصــدر املبلــغ املرقــم ثــم مت القبــض عليــه‪ ،‬وعثــر‬\n‫معــه علــى كيــس نايلــون فيــه حبــة بيضــاء اللــون مكســورة نصفــن‬\n‫حتمــل عالمــة الكبتاجــون‪ ،‬كمــا عثــر معــه علــى قطعــة ســوداء اللــون‬\n‫يشــتبه أن تكــون مــن احلشــيش‪ ،‬بلــغ وزنهــا ُعشــر اجلــرام ‪،‬و عثــر‬\n‫معــه علــى املبلــغ املرقــم وقــدره ألفــي ريــال ‪،‬و عثــر معــه علــى اجلــوال‬\n‫املســتخدم يف الترويــج‪ ،‬كمــا عثــر معــه بالســيارة علــى علبــة دخــان‬\n‫بداخلهــا ســيجارة ملفوفــة يشــتبه أن تكــون مخلوطــة مبــادة احلشــيش‬\n‫جرامــا واحـ ًـدا وثالثــة أعشــار اجلــرام وطلــب املدعــي‬\n                                                       ‫ً‬      ‫املخــدر‪ ،‬بلــغ وزنهــا‬\n‫العــام تعزيــر املدعــى عليــه بالســجن و اجللــد واملنــع مــن الســفر و الغرامــة‬\n‫ومصــادرة اجلــوال و إلغــاء الشــريحة ومصــادرة الســيارة وذلــك بتطبيــق‬\n‫املــواد ( ‪ )56/53/38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫بحقــه وتعزيــره لقــاء هروبــه وتســتره علــى مصــدر مــا ضبــط معــه ‪ ،‬أقــر‬\n‫املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام ‪ ،‬بنــاء علــى ماتقــدم‬\n‫حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن و اجللــد و املنــع مــن‬\n‫الســفر و مصــادرة الســيارة و اجلــوال و إلغــاء الشــريحة والغرامــة وإقامــة‬\n‫حــد املســكر وبعــرض احلكــم علــى طــريف الدعــوى قــرر املدعــى عليــه‬\n‫اعتراضــه علــى احلكــم بالئحــة وقــرر املدعــي العــام اعتراضــه علــى‬\n‫بــدون الئحــة ‪ُ ،‬صــدق احلكــم مــن محكمــة االســتئناف باألكثريــة‪.‬‬\n\n\n\n\n                                                                                        ‫‪424‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم وتاريــخ ‪1434/06/27‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقم وتاريخ ‪ 1434/06/27‬هـ ففي يوم اإلثنني املوافق‪1434/07/10‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 45‬وفيهــا قــدم املدعــي العــام الئحــة‬\n      ‫الدعــوى التــي نصهــا ( فبصفتــي عضــو هيئــة التحقيــق واالدعــاء العــام‬\n      ‫مبدينــة الريــاض أدعــي علــى‪ ........ /‬البالــغ مــن العمــر (‪ )41‬عام ـ ًا‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ،)..........‬أعــزب‪،‬‬\n      ‫متعلــم‪ ،‬متســبب‪ ،‬يقيــم مبدينــة الريــاض‪ ،‬أوقف بتاريــخ ‪1434/4/15‬هـ‬\n      ‫وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر إحالــة ومتديــد توقيــف رقــم‬\n      ‫(ه ـ ر‪ )42783/5/1‬وتاريــخ ‪1434/4/27‬ه ـ اســتناد ًا للقــرار الــوزاري‬\n      ‫رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة‪ .‬حيــث انــه بتاريــخ ‪1434/4/15‬ه ـ قبــض علــى‬\n      ‫املذكــور مــن قبــل إحــدى فــرق إدارة العمليــات التابعــة إلدارة مكافحــة‬\n      ‫املخــدرات مبنطقــة الريــاض وذلــك بنــاء ًا علــى ورود معلومــات مــن أحــد‬\n      ‫مصادرهــم الســرية عــن قيــام املذكــور بترويــج مــادة الكوكايــن‬\n      ‫املخــدر مســتخدم ًا يف ذلــك هاتفــه اجلــوال رقــم (‪ ).‬وســبق وان اتفــق معــه‬\n      ‫املصــدر هاتفي ـ ًا لشــراء (‪ )2‬جرامــن مــن مــادة الكوكايــن املخــدر‬\n      ‫مببلــغ وقــدره (‪ )2000‬ألفــي ريــال واســتعد املصــدر بربــط احــد ضبــاط‬\n      ‫إدارة العمليــات طرفنــا ليقــوم بعمليــة اإلســتالم والتســليم مــن املذكــور‪،‬‬\n      ‫ومت تزويــد الضابــط املكلــف بهاتــف جــوال ليقــوم بالتواصــل مــع‬\n\n‫‪425‬‬\n\f‫املذكــور ومت تزويــد رقــم الضابــط املكلــف إلــى املصــدر ثــم قــام‬\n‫املصــدر بتمريــره للمذكــور وبعــد حوالــي نصــف الســاعة ورد إتصال من‬\n‫املصــدر يفيــد بــأن املذكــور متواجــد باملوقــع وينتظــر اتصــال الضابــط‬\n‫املكلــف ‪ ،‬عليــه جــرى االتصــال مــن قبــل الضابــط املكلــف علــى‬\n‫هاتــف املذكــور وذكــر للضابــط املكلــف بأنــه متواجــد خلــف أحــد‬\n‫األســواق بداخــل احلــي ويســتقبل ســيارة مــن نــوع ‪ .....‬وهــو يف انتظــاره‪،‬‬\n‫وعليــه مت تزويــد الضابــط املكلــف مببلــغ مرقــم وقــدره (‪ )2000‬ألفــي‬\n‫ريــال ليقــوم بعمليــة الشــراء ‪ ،‬ومت االنتقــال بكامــل الفرقــة ‪ ،‬ونشــر‬\n‫الفرقــة خلــف الســوق وعنــد دخــول الضابــط املكلــف بســيارته إلــى‬\n‫داخــل احلــي شــوهدت ســيارة مــن نــوع جيــب (‪ ).....‬فضــي اللــون يحمــل‬\n‫اللوحــة رقــم (‪ ).......‬يســتقله شــخص واحــد وهــو يقــف بجانــب الســيارة‬\n‫التــي بهــا الضابــط املكلــف عبــر نوافــذ األبــواب لــم يترجــل احــد منهــا‬\n‫‪ ،‬وســلم املذكــور للضابــط املكلــف كيــس نايلــون بداخلــه مــادة‬\n‫مســحوقه ناعمــة امللمــس بلــوري اللــون عــدمي الرائحــة يشــبه نــدف الثلــج‬\n‫‪ ،‬يشــتبه أن يكــون مــن مــادة الكوكايــن املخــدر والتــي بلــغ وزنهــا‬\n‫(‪ )1.4‬جرام ـ ًا واحــد ًا وأربعــة أعشــار اجلــرام ‪ ،‬واســتلم املذكــور مــن‬\n‫ال منهمــا يف ســبيله ‪ ،‬ومتــت‬‫الضابــط املكلــف املبلــغ املرقــم وحتــرك ك ً‬\n‫متابعــة املذكــور حتــى متكــن مــن الوقــوف بداخــل حــي الســويدي ‪،‬‬\n‫وعنــد نزولــه مــن ســيارته متــت مداهمتــه ‪ ،‬وعنــد مشــاهدته للفرقــة قــام‬\n‫بالهــرب علــى قدميــه مســافة قصيــرة ومت إطــاق طلقتــن حتذيريــة‬\n‫مــن مســدس حكومــي يف الهــواء لتخويفــه لعــدم متكنــه مــن الهــرب‬\n‫‪ ،‬وبضبطــه اتضــح انــه املذكــور وبتفتيشــه عثــر بداخــل جيبــه علــى‬\n‫محفظــة جلديــه عثــر بداخلهــا علــى كيــس نايلــون بداخلــه حبــة بيضــاء‬\n\n\n                                                                                   ‫‪426‬‬\n\f      ‫اللــون مكســورة نصفــن جميــع النصفــن حتمــل عالمــة الكبتاجــون‬\n      ‫احملظــورة ‪ ،‬وكذلــك عثــر بنفــس احملفظــة علــى قطعــة ســوداء اللــون‬\n      ‫صغيــرة يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )0.1‬عشــر‬\n      ‫اجلــرام ‪ ،‬وعثــر أيضــا بنفــس احملفظــة علــى مبلــغ مالــي وقــدره (‪)4573‬‬\n      ‫أربعــة آالف وخمســمائة وثالثــة وســبعون ريــال ‪ ،‬وكذلــك عثــر بداخــل‬\n      ‫جيــب ثوبــه العلــوي علــى املبلــغ املرقــم وقــدره ألفــي ريــال ‪ ،‬وعثــر معــه‬\n      ‫علــى كذلــك علــى جهــازي جــوال مــن نــوع ‪ .....‬احدهمــا يحمــل الرقــم‬\n      ‫(‪ ).0‬ورقمــه املصنعــي (‪ )...‬وهــو الهاتــف الــذي اســتخدم يف الترويــج ‪،‬‬\n      ‫وبتفتيــش ســيارته عثــر بجانــب ناقــل احلركــة (القيــر) علــى علبــة دخــان‬\n      ‫عثــر بداخلهــا علــى ســيجارة ملفوفــة يشــتبه أن تكــون مخلوطــة مبــادة‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )1.3‬جــرام واحــد ًا وثالثــة أعشــار اجلــرام ‪،‬‬\n      ‫ومبناقشــته عــن مصــدر مــا قــام بترويجــه أفــاد بأنــه يحصــل عليهــا مــن‬\n      ‫شــخص فلســطيني اجلنســية يســكن بحــي ( ‪ ) .......‬ومت التحفــظ علــى‬\n      ‫ا مت‬ ‫املذكــور وذلــك حملاولــة الشــراء مــن الشــخص الفلســطيني وفع ـ ً‬\n      ‫الشــراء منــه وعنــد ضبطــه ســوف ُتشــعر جهــة التحقيــق بذلــك وقــد أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة الســموم‬\n      ‫والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪/4637‬س) لعــام‬\n      ‫‪1434‬ه ـ احتــواء مســتخلص عينــة املســحوق املــروج ملــادة الكوكايــن‬\n      ‫وهــو مــن املــواد املخــدرة املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وايجابيــة القطعــة‬\n      ‫ومســتخلص التبــغ يف الســيجارة املضبوطــة للحشــيش وهــو مــن املــواد‬\n      ‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة‪ ،‬واحتــواء نصفــي احلبــة املضبوطــة لالمفيتامــن وهــو‬\n\n\n‫‪427‬‬\n\f‫مــن املــواد املنبهــة املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع أقوالــه اعتــرف أن‬\n‫بحيــازة مــا ضبــط بقصــد التعاطــي وبتعاطــي مــن نــوع مــا ضبــط معــه‪.‬‬\n‫وباســتجوابه اقــر بتســليمه كيــس وزنــه (‪ )1.4‬جرام ـ ًا واحــد ًا وأربعــة‬\n‫أعشــار اجلــرام مــن الكوكايــن‪ ،‬كمــا اعتــرف بحيازتــه ســيجارة مــن‬\n‫احلشــيش املخــدر بقصــد التعاطــي واعتــرف أن رقــم اجلــوال (‪ )....‬يعــود‬\n‫لــه وهــو مــن نــوع ‪ ،.....‬كمــا اعتــرف الســيارة مــن نــوع ‪ .....‬والتــي حتمــل‬\n‫رقــم (‪ )......‬تعــود لــه وهــي باســمه‪ ،‬وأفــاد أن املبلــغ املالــي املضبــوط معــه‬\n‫وقــدره (‪ )4573‬أربعــة آالف وخمســمائة وثــاث وســبعون ريــا ًال يعــود‬\n‫لعمالــه يف مؤسســة والــده لتجديــد رخــص إقاماتهــم (مت تســليمه املبلــغ‬\n‫املالــي اســتناد ًا للمادتــن (‪ 86‬ـ ـ ‪ )88‬مــن نظــام اإلجــراءات اجلزائيــة‬\n‫ال للمصادرة مبوجب اخلطاب رقم (هـ ر‪)60977/5/1‬‬                   ‫لكونه ليس مح ً‬\n‫وتاريــخ ‪1434/6/17‬هــ)‪ .‬وقــد أســفرت إجــراءات التحقيــق معــه عــن‬\n‫توجيــه االتهــام للمدعــى عليــه ببيــع ماوزنــه (‪ )1.34‬جرامـ ًا واحــد ًا وثالثــة‬\n‫أعشــار اجلــرام مــن مــادة الكوكايــن بقصــد االجتــار والترويــج‪،‬‬\n‫وحيــازة ســيجارة مخلوط ـ ًا تبغهــا باحلشــيش املخــدر بلــغ وزنهــا (‪)1.4‬‬\n‫جرام ـ ًا واحــد ًا وأربعــة أعشــار اجلــرام وحيــازة نصفــن حلبــة مــن حبــوب‬\n‫االمفيتامــن املنبــه احملظــور وحيــازة قطعــة مــن احلشــيش املخــدر بلــغ‬\n‫وزنهــا (‪ )0.1‬عشــر اجلــرام بقصــد التعاطــي وتعاطيــه احلشــيش املخــدر‬\n‫واحلبــوب احملظــورة املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وهروبــه مــن الفرقــة القابضــة املعاقــب علــى‬\n                                 ‫ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة‬\n\n\n                                                                                         ‫‪428‬‬\n\f      ‫ا علــى‬  ‫‪ .1‬مــا تضمنــه اعترافــه حتقيق ـ ًا املنــوه عنــه املــدون تفصي ـ ً‬\n      ‫الصفحــات رقــم (‪ 1‬ـ ـ ‪ )3‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪. )16‬‬\n      ‫‪ .2‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املــدون‬\n                                                         ‫علــى اللفتــن رقــم (‪ )3‬ورقــم (‪.)4‬‬\n      ‫‪ .3‬مــا تضمنــه محضــر القبــض والضبــط والتفتيــش املنــوه عنــه املــدون‬\n      ‫علــى الصفحــة رقــم (‪ 11‬ـ ـ ‪ )12‬مــن ملــف ضبــط إجــراءات االســتدالل يف‬\n                                                            ‫قضايــا املخــدرات لفــة رقــم(‪.)1‬‬\n              ‫‪ .4‬ما تضمنه التقرير الكيميائي الشرعي املرفق لفة رقم (‪.)15‬‬\n                    ‫‪ .5‬عثر مع املذكور على اجلوال الذي مت التنسيق من خالله‪.‬‬\n      ‫‪ .6‬ماتضمنــه محضــر املبلــغ املرقــم املــدون علــى الصفحــة رقــم (‪ 11‬ـ ـ ‪)12‬‬\n      ‫مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا املخــدرات لفــة رقــم(‪.)1‬‬\n      ‫وببحــث ســوابقه عثــر لــه علــى ســابقة واحــدة وهــي حيــازة واســتعمال‬\n                                                                                   ‫مخــدرات‪.‬‬\n      ‫وحيــث إن مــا أق ــدم عل ــيه ال ــمذكور ف ــعل م ــحرم شــرع ًا وم ــعاقب عليــه‬\n      ‫شــرع ًا ونظام ـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                                      ‫باآلتــي‪:‬‬\n                 ‫‪ .1‬إجراء املقتضى الشرعي بحقه لقاء تعاطيه احلشيش املخدر‪.‬‬\n      ‫‪ .2‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا للفقــرة (األولــى)‬\n      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n      ‫إليــه ‪ ،‬وتشــديد العقوبــة عليــه وفقـ ًا للفقــرة (ج) البنــد (ثانيـاً) مــن نفــس‬\n                                    ‫املــادة مــن ذات النظــام بحقــه لقــاء مــا أســند إليــه‪.‬‬\n      ‫‪ .3‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد تنفيــذ عقوبــة ســجنه وفقـ ًا‬\n                  ‫للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار إليــه‪.‬‬\n\n\n‫‪429‬‬\n\f‫‪ .4‬مصــادرة الهاتــف النقــال مــن نــوع ( ‪ ) .......‬العائد للمذكور املســتخدم‬\n‫يف اجلرميــة ذي الرقــم املصنعــي (‪ ، ).....‬وفقـ ًا للفقــرة (األولــى) مــن املــادة‬\n                                                            ‫(‪ )53‬مــن ذات النظــام‪.‬‬\n‫‪ .5‬إلغــاء الشــريحة الهاتفيــة ذات الرقــم () املســتخدمة يف عمليــة الترويــج‬\n‫العائــد لــأول وعــدم صرفهــا لنفــس املشــترك يف حــال صــدور احلكــم‬\n‫باإللغــاء ‪ ،‬وإبــاغ الشــركة مصــدرة الشــريحة بذلــك وفقـ ًا لتعميم ســمو‬\n                     ‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪9‬ـ‪1428/2/10‬ه ـ ‪.‬‬\n‫‪ .6‬مصــادرة الســيارة العائــدة للمذكــور وهــي مــن نــوع ( ‪ ، ) .......‬حتمــل‬\n‫اللوحــة رقــم ( ــ) املســتخدمة يف عمليــة الترويــج اســتناد ًا للفقــرة األولــى‬\n       ‫مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n                               ‫‪ .7‬بعقوبة تعزيرية لقاء هربه من فرقة القبض‪.‬‬\n‫هــذا نــص الئحــة املدعــي العــام وجــرى تــاوة مــا جــاء يف الئحــة‬\n‫االدعــاء العــام علــى املتهــم احلاضــر يف هــذه اجللســة واطالعــه عليهــا‬\n‫وتوضيحهــا لــه وســؤاله اجلــواب عليهــا فأجــاب قائــا‪ :‬مــا ذكــر يف‬\n‫ببيــع ماوزنــه (‪ )1.34‬جرام ـ ًا‬            ‫الئحــة االدعــاء العــام مــن اتهامــي‬\n‫واحــد ًا وثالثــة أعشــار اجلــرام مــن مــادة الكوكايــن بقصــد االجتــار‬\n‫والترويــج‪ ،‬وحيــازة ســيجارة مخلوطـ ًا تبغهــا باحلشــيش املخــدر بلــغ وزنهــا‬\n‫(‪ )1.4‬جرام ـ ًا واحــد ًا وأربعــة أعشــار اجلــرام وحيــازة نصفــن حلبــة مــن‬\n‫حبــوب االمفيتامــن املنبــه احملظــور وحيــازة قطعــة مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ )0.1‬عشــر اجلــرام بقصــد التعاطــي وتعاطــي احلشــيش‬\n‫املخــدر واحلبــوب احملظــورة وهروبــي مــن الفرقــة القابضــة فهــذا صحيــح‬\n‫وأنــا تائــب ونــادم علــى مــا بــدر منــي وأتعهــد بعــدم العــودة إلــى مثــل ذلــك‬\n‫ثــم اطلعــت علــى أدلــة املدعــي العــام حيــث اطلعــت علــى أقــوال املدعــى‬\n\n\n                                                                                          ‫‪430‬‬\n\f      ‫عليــه يف التحقيــق ومحضــر القبــض والتقريــر الكيميائــي الشــرعي‬\n      ‫ومــا تضمنــه محضــر املبلــغ املرقــم والعثور على اجلوال الذي مت التنســيق‬\n      ‫مــن خاللــه معــه كمــا ســألت املدعــى عليــه عــن الســابقة املنســوبة لــه‬\n      ‫فقــال انهــا صحيحــة ثــم ســألت املدعــي العــام واملدعــى عليــه هــل لديهــم‬\n      ‫مــا يريــدان إضافتــه فأجــاب كل واحــد منهمــا بقولــه إننــا نكتفــي مبــا‬\n                          ‫قدمنــا مــن أقــوال ســابقة وليــس لدينــا مــا نريــد إضافتــه‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى أدلــة‬\n      ‫املدعــي العــام وباقــي أوراق املعاملــة وحيــث اقــر املدعــى عليــه مبــا نســب‬\n      ‫إليــه يف الدعــوى لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه ببيــع ماوزنــه‬\n      ‫(‪ )1.34‬جرام ـ ًا واحــد ًا وثالثــة أعشــار اجلــرام مــن مــادة الكوكايــن‬\n      ‫بقصــد االجتــار والترويــج‪ ،‬وحيــازة ســيجارة مخلوط ـ ًا تبغهــا باحلشــيش‬\n      ‫املخــدر بلــغ وزنهــا (‪ )1.4‬جرام ـ ًا واحــد ًا وأربعــة أعشــار اجلــرام وحيــازة‬\n      ‫نصفــن حلبــة مــن حبــوب االمفيتامــن املنبــه احملظــور وحيــازة قطعــة مــن‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )0.1‬عشــر اجلــرام بقصد التعاطــي وتعاطي‬\n          ‫احلشــيش املخــدر واحلبــوب احملظــورة وهروبــي مــن الفرقــة القابضــة‬\n      ‫والعقوبــات يف املــواد (‪ 38‬و‪56‬و‪)53‬مــن نظــام مكافحــة املخــدرات‬\n      ‫تنطبــق يف حــق املدعــى عليــه وعليــه فقــد حكمــت بتعزيــره علــى ذلــك‬\n                                                                                ‫مبــا يلــي‪:‬‬\n      ‫‪ -1‬بالســجن ملــدة عشــر ســنوات تبــدأ مــن تاريــخ إيقافــه خلطــورة مــا‬\n      ‫أقــدم عليــه املدعــى عليــه مــن ترويجــه ملــادة الكوكايــن املخــدرة‬\n                                                                              ‫واحملظــورة‬\n      ‫‪ -2‬بجلــده ألــف جلــدة مفرقــة علــى عشــر يــن دفعــة متســاوية كل‬\n              ‫دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى مــدة عشــرة أيــام‬\n\n\n‫‪431‬‬\n\f‫‪ -3‬بــأن يدفــع غرامــة ماليــة قدرهــا ثالثــون ألــف ريــال تــودع يف بيــت‬\n                                          ‫املــال وتصــرف يف وجــوه البــر اخليرية‬\n‫‪ -4‬منعــه مــن الســفر خــارج اململكــة ملــدة عشــر ســنوات تبــدأ بعــد‬\n                                                                     ‫تنفيــذ احلكــم‬\n‫‪ -5‬مصــادرة اجلــوال املســتخدم يف هــذه اجلرميــة وبيعــه وإيــداع قيمتــه‬\n‫بيــت املــال وصرفهــا يف وجــوه البــر اخليريــة و إلغــاء شــريحة الهاتــف‬\n                                                            ‫املســتخدمة يف اجلرميــة‬\n‫‪ -6‬كمــا حكمــت بجلــدة ثمانــن جلــدة حــد املســكر الســتعماله‬\n‫احلشــيش املخــدر والفاصــل بــن جلــد احلــد وجلــد التعزيــر مــدة عشــرة‬\n    ‫أيــام وعقوبــة اســتعماله احلبــوب احملظــورة داخلــة يف جلــد التعزيــر‬\n‫‪7‬ـ مصــادرة الســيارة مــن نــوع ‪ .........‬حتمــل اللوحــة رقــم (‪ )......‬وبيعهــا‬\n‫وإيــداع قيمتهــا بيــت املــال لصرفــه يف وجــوه البــر املختلفــة وعقوبــة‬\n‫تســتره علــى مصــدر مــا ضبــط وهروبــه مــن الفرقــة القابضــة داخلــة‬\n                                          ‫فيمــا مت احلكــم بــه عليــه مــن ســجن‬\n‫وبعــرض هــذا احلكــم علــى املدعــى عليــه قــرر اعتراضــه علــى هــذا‬\n‫احلكــم وانــه ســوف يقــدم الئحــة اعتــراض عليــه أمــا املدعــي العــام‬\n‫فقــد قــرر االعتــراض مكتفيــا مبــا جــاء يف الئحــة االدعــاء وجــرى‬\n‫إفهــام املعتــرض مبوجــب التعليمــات املنظمــة لالعتــراض وذلــك إعمــاال‬\n‫للمــادة الرابعــة والتســعون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة وأن‬\n‫عليــه مراجعــة احملكمــة يــوم األربعــاء املوافــق ‪1434/7/19‬ه ـ الســاعة‬\n‫التاســعة صباحــا موعــدا الســتالم نســخة مــن صــك احلكــم وجــرى‬\n‫الكتابــة إلــى إدارة الســجن إلحضــار املدعــى عليــه يف املوعــد احملــدد‬\n‫الســتالم نســخة مــن صــك احلكــم وختمــت اجللســة الســاعة‪01:30‬‬\n\n\n                                                                                       ‫‪432‬‬\n\f      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                              ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/10‬ه ـ‬\n      ‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض‬\n      ‫والقائــم بعمــل الشــيخ‪ /‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1434/06/27‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/06/27‬ه ـ ففــي يــوم األربعــاء‬\n                    ‫املوافــق‪ 1434/08/17‬ه ـ افتتحــت اجللســة الســاعة ‪10:45‬‬\n      ‫وفيهــا حضــر املعتــرض علــى احلكــم وهــو وجــرى تســليمه نســخة مــن‬\n      ‫صــك احلكــم وجــرى إفهامــه مبوجــب املــادة (‪)194‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وان مــدة االعتــراض علــى هــذا احلكــم هــي ثالثــون يومــا تبــدأ‬\n      ‫مــن تاريــخ هــذا اليــوم وإذا لــم يقــدم االعتــراض خــال هــذه املــدة فســوف‬\n      ‫يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة اعتــراض‬\n      ‫وذلــك إعمــاال للمــادة (‪)195‬مــن نظــام اإلجــراءات اجلزائيــة ففهــم ذلــك‬\n      ‫واســتعد بــه وعلــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/17‬ه ـ‬\n      ‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n      ‫بالريــاض برقــم وتاريــخ ‪ 1434/06/27‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1434/06/27‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/10/26‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 10:45‬وقــد وردنــا مــن إدارة احملكمة الالئحة‬\n      ‫االعتراضيــة املقدمــة مــن املعتــرض وكالــة () واملقيــدة يف احملكمــة‬\n      ‫برقــم‪ .....‬وتاريــخ ‪1434/9/23‬ه ـ املكونــة مــن ( ‪ ) 9‬صفحــة وقــد‬\n      ‫اطلعــت علــى هــذه الالئحــة ولــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه‬\n\n\n‫‪433‬‬\n\f‫ومت الشــرح علــى هــذه الالئحــة بذلــك وجــرى ضمهــا إلــى ملــف املعاملــة‬\n‫وأمــرت بالكتابــة علــى املعاملــة إلــى محكمــة االســتئناف وذلــك إعمــاال‬\n‫للمــادة (‪)197‬مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬وختمــت اجللســة الســاعة‬\n‫‪ 10:50‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                            ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/10/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولى‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪1434/11/2‬ه ـ‬\n‫واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة‪ /‬برقــم‬\n‫وتاريــخ ‪1434/7/19‬ه ـ واخلــاص بدعــوى املدعــي العــام ضــد ‪)....... (/‬‬\n‫‪ ،‬وموضوعهــا مخــدرات‪ ،‬وانتهــت الدراســة والتدقيــق باملصادقــة علــى‬\n‫احلكــم باألكثريــة لعــدم موجــب املالحظــة‪ ،‬مــع تنبيــه فضيلتــه إلــى‬\n‫تدويــن اســم املدعــي العــام الثالثــي حتــت توقيعــه يف الضبــط حســب‬\n‫التعليمــات‪ ،‬ومالحظــة ذلــك مســتقبالً‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪434‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":423,"source_page_end":434,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"541c6f945a289925960b48a28f91d3be72317903510aa909f9a1b299ab0a919b","normalized_text_hash":"177d938c6f16e7155a37338e3d6fb63a83402b9b40b47abe65a93ee1434b7ce0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p423-3427326"},{"id":"8bdf4da0-d5ca-54b8-a435-f63722d0f7ff","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن و اجللد و الغرامة و املنع من السفر و مصادرة اجلوال و إلغاء الشريحة ورد املبلغ احلكومي.","document_number":"34268398","case_number":"34299189","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/15","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن و اجللد و الغرامة و املنع من السفر و مصادرة اجلوال و إلغاء الشريحة ورد املبلغ احلكومي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34268398 :‬تاريخه‪1434/7/15 :‬هـ‬\n                        ‫رقم الدعوى‪34299189 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪/34289621‬ج‪/2‬ب تاريخه‪1434/08/07 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n      ‫إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن‬\n      ‫و اجللــد و الغرامــة و املنــع مــن الســفر و مصــادرة اجلــوال و إلغــاء‬\n                                            ‫الشــريحة ورد املبلــغ احلكومــي‪.‬‬\n\n\n\n      ‫‪ ( .1‬حديــث أم ســلمة رضــي اهلل عنهــا يف نهــي النبــي صلــى اهلل عليــه‬\n                                             ‫وســلم عــن كل مســكر و مفتــر ) ‪.‬‬\n               ‫‪ .2‬املادة ( ‪ ) 38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n               ‫‪ .3‬املادة ( ‪ ) 56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n               ‫‪ .4‬املادة ( ‪ ) 53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n               ‫‪ .5‬املادة ( ‪ ) 60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n                                  ‫‪ .6‬القرار الوزاري رقم ‪ 47‬يف ‪ 1421/2/18‬هـ ‪.‬‬\n           ‫‪ .7‬برقية وزير الداخلية رقم ( ‪ )9798/4/5/1‬يف ‪1428/2/10-9‬هـ ‪.‬‬\n                  ‫‪ .8‬تعميم وزير الداخلية رقم ‪ 65980‬يف ‪ 1422/10/23-22‬هـ ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج املخــدرات ‪ ،‬وبيــع قطعــة‬\n      ‫مــن احلشــيش املخــدر ‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى عليــه‬\n\n‫‪435‬‬\n\f‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء‬\n‫الشــريحة ورد املبلــغ احلكومــي وذلــك تطبيق ـ ًا ألحــكام املــواد (‪ )38‬و‬\n‫(‪ )53‬مــن نظــام مكافحــة املخــدرات ‪ ،‬كمــا طلــب إقامــة حــد املســكر‬\n‫علــى املدعــى عليــه لقــاء تعاطيــه للحشــيش ‪ ،‬حيــث توفــرت معلومــات‬\n‫لــدى اجلهــة األمنيــة عــن قيــام أحــد األشــخاص بترويــج املخــدرات‪،‬‬\n‫وأنــه يســتخدم املدعــى عليــه فتــم اإلتصــال عليــه مــن املصــدر وطلــب‬\n‫منــه قطعــة مــن احلشــيش املخــدر مببلــغ ألــف ريــال‪ ،‬فوافــق علــى ذلــك‪،‬‬\n‫وطلــب مــن املصــدر أن يســتلم الكميــة مــن املدعــى عليــه‪ ،‬واتفــق علــى‬\n‫املوعــد‪ ،‬فتــم تفتيــش املصــدر ‪ ،‬وترقيــم املبلــغ احلكومــي وقــدره ألــف‬\n‫ريــال ثــم قابــل املصــدر املدعــى عليــه ‪ ،‬وبعــد دقائــق نــزل املدعــى عليــه‬\n‫مــن الســيارة ودخــل منزلــه‪ ،‬وعــاد املصــدر وســلم الفرقــة قطعــة ســوداء‬\n‫جرامــا يشــتبه أن تكــون مــن احلشــيش‪ ،‬ثــم‬‫ً‬      ‫اللــون تــزن ثالثــة وعشــرون‬\n‫مت القبــض علــى املدعــى عليــه ‪ ،‬بنــاء علــى مــا ســبق حكمــت احملكمــة‬\n‫بإقامــة حــد املســكر علــى املدعــى عليــه واحلكــم بالتعزيــر بالســجن و‬\n‫اجللــد و الغرامــة و املنــع مــن الســفر و مصــادرة اجلــوال و إلغــاء الشــريحة‬\n‫ورد املبلــغ احلكومــي و مت النــزول عــن احلــد األدنــى للعقوبــة بنــاء علــى‬\n‫املــادة (‪ ) 60‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة ‪ ،‬لعــدم‬\n‫وجــود ســوابق بحــق املدعــى عليــه‪ ،‬و لقلــة الكميــة ‪ ،‬قنــع املدعــى عليــه‬\n‫باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة‬\n                   ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬      ‫اعتراضيــة ُ‬\n\n\n\n\n                                                                                     ‫‪436‬‬\n\f      ‫اجلزائيــة‬\n         ‫ّ‬         ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪............‬القاضــي يف احملكمــة‬\n      ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء املكلــف برقم وتاريخ ‪ 1434/06/28‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/06/28‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافق‪ 1434/07/15‬هـ افتتحت اجللسة الساعة ‪ 10 : 00‬وفيها حضر‬\n      ‫املدعــي العــام (‪ ) ......‬املعمــد بالترافــع أمــام هــذه احملكمــة مبوجــب‬\n      ‫خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعاء العام مبحافظة االحســاء‬\n      ‫ذي الرقم والتاريخ ‪ 1433/12/01‬هـ وادعى ضد احلاضر معه ( ‪..........‬‬\n      ‫ا يف دعــواه‬    ‫) ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬قائ ـ ً‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لدائــرة التحقيــق واالدعــاء‬\n      ‫العــام مبحافظــة االحســاء أدعــي علــى املذكــور أعــاه فباالطــاع علــى‬\n      ‫محضــر القبــض املعــد مــن مكافحــة املخــدرات مبحافظــة االحســاء‬\n      ‫تبــن أنــه بتاريــخ ‪1434/5/22‬ه ـ توفــرت معلومــات لــدى املكافحــة مــن‬\n      ‫مصادرهــا الســرية تفيــد عــن قيــام املواطــن‪( /‬لــم يتــم القبــض عليــه)‬\n      ‫بترويــج املخــدرات وأنــه يســتخدم املدعــى عليــه يف تســليم أي كميــة‬\n      ‫يقــوم ببيعهــا فتــم متكــن املصــدر مــن االتصــال عليــه وطلــب منــه شــراء‬\n      ‫قطعــة مــن احلشــيش املخــدر مببلــغ (‪)1000‬ألــف ريــال فوافــق علــى ذلــك‬\n      ‫وطلــب مــن املصــدر أن يســتلم الكميــة مــن املدعــى عليــه ومت متكــن‬\n      ‫املصــدر مــن االتصــال علــى جــوال املدعــى عليــه رقــم (‪ ).....‬واتفقــا علــى‬\n      ‫موعــد ومــكان االســتالم والتســليم فتــم تفتيــش املصــدر وترقيــم مبلــغ‬\n      ‫حكومــي وقــدره (‪)1000‬ألــف ريــال وحتــرك املصــدر بســيارته حتــت‬\n\n‫‪437‬‬\n\f‫أنظــار الفرقــة القابضــة إلــى املــكان املتفــق عليــه ثــم قابــل املدعــى عليــه‬\n‫وركــب معــه وبعــد عشــر دقائــق نــزل املدعــى عليــه مــن الســيارة ودخــل‬\n‫إلــى منزلــه ثــم عــاد املصــدر وســلم الفرقــة قطعــة ســوداء اللــون تــزن (‪)23‬‬\n‫ثالثــة وعشــرون جرام ـ ًا يحتمــل أن تكــون مــن احلشــيش املخــدر فتــم‬\n‫مراقبــة منــزل املدعــى عليــه ويف يــوم األحــد املوافــق ‪1434/5/26‬ه ـ‬\n‫وأثنــاء قيــام الفرقــة امليدانيــة مبســح ميدانــي للمواقــع املشــبوهة شــاهد‬\n‫أعضــاء الفرقــة املدعــى عليــه بالقــرب مــن إحــدى االســتراحات فتــم‬\n‫القبــض عليــه وبتفتيشــه لــم يعثــر بحوزتــه علــى شــيء مــن املمنوعــات ولــم‬\n           ‫يعثــر علــى املبلــغ احلكومــي املرقــم وقــدره (‪ )1000‬ألــف ريــال‪.‬‬\n‫وباســتجوابه‪ /‬أقــر بأنــه يف يــوم األربعــاء املوافــق ‪1434/5/22‬ه ـ قــام‬\n‫بشــراء قطعــة مــن احلشــيش املخــدر مــن (‪ ).......‬بقصــد التعاطــي ومــن‬\n‫اليــوم نفســه تلقــى اتصــا ًال علــى جوالــه املذكــور أعــاه مــن (‪ )......‬وطلــب‬\n‫منــه أن يقــوم ببيــع قطعــة احلشــيش التــي بحوزتــه علــى املصــدر ووعــده‬\n‫بتوفيــر كميــة بديلــة لــه فوافــق علــى ذلــك ثــم قابــل املصــدر وســلمه‬\n‫قطعــة احلشــيش واســتلم مبلغهــا كمــا أقــر بتعاطيــه للحشــيش املخــدر‬\n                                                                         ‫يف الســابق‪.‬‬\n‫وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ )......‬لعــام ‪1434‬ه ـ‬\n‫ايجابيــة عينــة القطعــة املضبوطــة ملــادة احلشــيش املخــدر املــدرج يف‬\n‫اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لألولــ‪ /‬ببيع قطعة من احلشــيش‬\n‫املخــدر تــزن (‪ )23‬ثالثــة وعشــرون جرام ـ ًا بقصــد االجتــار وتعاطيــه‬\n                                                               ‫لنوعــه يف الســابق ‪.‬‬\n                                                ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n\n\n                                                                                        ‫‪438‬‬\n\f      ‫‪ -1‬ماجــاء يف أقوالــه املدونــة علــى الصفحــات رقــم (‪ )3،2،1‬مــن دفتــر‬\n                                                                  ‫التحقيــق لفــه رقــم(‪.)10‬‬\n      ‫‪ -2‬ماجــاء يف محضــر القبــض املنــوه عنــه املــدون علــى الصفحتــن رقــم‬\n                                        ‫(‪ )13،12‬مــن دفتــر االســتدالل لفــة رقــم (‪.)8‬‬\n      ‫‪ -3‬ماجــاء يف محضــر االتصــال املــدون علــى الصفحــة رقــم (‪ )4‬مــن دفتــر‬\n                                                                  ‫االســتدالل لفــة رقم (‪.)8‬‬\n      ‫‪ -4‬ماجــاء يف محضــر تفتيــش املصــدر وســيارته املــدون علــى الصفحــة‬\n                                      ‫رقــم (‪ )12‬مــن دفتــر االســتدالل لفــة رقــم (‪).8‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا ‪ ،‬فعــل مجــرم ومعاقــب علي ــه شــرع ًا ونظام ـ ًا مبوجــب املــادة (‬\n      ‫الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات‬\n                                             ‫مــا اســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n      ‫‪ - 1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )38‬مــن النظــام‬\n      ‫املشــار إليــه لقــاء مــا أســند إليــه لكونهــا العقوبــة األشــد اســتنادا للفقــرة‬\n          ‫األولــى مــن املــادة (‪ )62‬مــن النظــام املشــار إليــه لقــاء مــا أســند إليــه‪.‬‬\n      ‫‪ -2‬مصــادرة اجلــوال املضبــوط مــع املدعــى عليــه مــن نــوع (‪ )....‬الرقــم‬\n      ‫التسلســلي (‪ ).....‬املســتخدم يف اجلرميــة وفقـ ًا للفقــرة (األولــى) مــن املــادة‬\n      ‫(‪ )53‬مــن النظــام املشــار إليــه وإيــداع املبالــغ يف حســاب إدارة املخــدرات‬\n                   ‫ـاء علــى القــرار الــوزاري رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬ه ـ ‪.‬‬        ‫بنـ ً‬\n      ‫‪ -3‬إلغــاء شــرايحة االتصــال املوصوفــة يف القــرار وفــق برقيــة وزيــر‬\n                ‫الداخليــة رقــم (‪ )9798/4/5/1‬وتاريــخ ‪1428/2/10-9‬هــ‪.‬‬\n      ‫‪-4‬إلزامــه بــرد املبلــغ احلكومــي العائــد ملكافحــة املخــدرات باالحســاء‬\n\n\n‫‪439‬‬\n\f‫وقــدره (‪ )1000‬ألــف ريــال اســتناد َا لتعميــم وزير الداخليــة رقم (‪)65980‬‬\n                                                   ‫وتاريخ ‪1422/10/23-22‬هـ‪.‬‬\n‫‪-5‬معاقبتــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن‬\n     ‫النظــام املشــار إليــه مبنعــه مــن الســفر بعــد تنفيــذ محكوميتــه‪.‬‬\n‫ا مــا ذكــره املدعــي‬    ‫هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n‫العــام مــن أنــه بتاريــخ ‪1434/5/22‬ه ـ قمــت بترويــج قطعــة مــن احلشــيش‬\n‫املخــدر تــزن (‪ )23‬ثالثــة وعشــرون جرامـ ًا بقصــد االجتــار وأنني تعاطيت‬\n‫لنوعــه يف الســابق وأنــه بتاريــخ ‪1434/05/26‬ه ـ مت القبــض علــي مــن‬\n‫قبــل إحــدى فــرق مكافحــة املخــدرات التابعــة حملافظــة األحســاء فهــذا‬\n‫كلــه صحيــح وكذلــك مــا ذكــره املدعــي العــام مــن أنــه اتصــل بــي على‬\n‫هاتفــي اجلــوال رقــم وطلــب منــي حشــيش مخــدر مببلــغ وقــدره ألــف ريــال‬\n‫اســتلمتها فهــذا صحيــح أيض ـ ًا هكــذا أجــاب وباإلطــاع علــى املعاملــة‬\n‫وجــد فيهــا علــى لفــة رقــم ‪ 14‬التقريــر الكيمــاوي الشــرعي رقــم ()‬\n‫لعــام ‪1434‬ه ـ املتضمــن إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‬\n‫واســتهالك جميــع العينــات املرســلة يف التحليــل ا‪.‬ه ـ فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه ببيــع قطعــة مــن احلشــيش‬\n‫املخــدر تــزن (‪ )23‬ثالثــة وعشــرون جرامـ ًا بقصد االجتــار وتعاطيه لنوعه‬\n‫يف الســابق وللتقريــر الكيمــاوي الشــرعي ولنهــي النبــي صلــى اهلل عليــه‬\n‫وســلم عــن كل مســكر ومفتــر كمــا يف حديــث أم ســلمه رضــي اهلل‬\n‫عنهــا وحيــث إن مــا أقــدم عليــه املدعــى عليــه ضــرب من ضروب اإلفســاد‬\n‫بــاألرض وحيــث إن احلشــيش يشــترك مــع اخلمــر يف منــاط احلكــم لذلــك‬\n‫كلــه ثبــت لــدي إدانــة املدعــى عليــه ببيــع قطعــة مــن احلشــيش املخدر تزن‬\n‫(‪ )23‬ثالثــة وعشــرون جرامـ ًا بقصــد االجتــار وتعاطيــه لنوعــه يف الســابق‬\n\n\n                                                                                     ‫‪440‬‬\n\f      ‫وحكمــت عليــه مبــا يلــي ‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه ثمانــون جلــدة دفعــة‬\n      ‫واحــدة حــد املســكر ثاني ـ ًا ‪ :‬ســجن املدعــى عليــه مــدة ثــاث ســنوات‬\n      ‫يحتســب منهــا مــدة بقائــه بالســجن بخصــوص هــذه القضيــة وجلــد‬\n      ‫املدعــى عليــه ثالثمائــة جلــدة تعزيــر ًا مفرقــة علــى ســت دفعــات كل‬\n      ‫دفعــة خمســن جلــدة بــن كل دفعــة واألخــرى مــدة اســبوعني وبغرامــة‬\n      ‫ماليــة قدرهــا ثالثــة آالف ريــال وقــد نزلــت علــى العقوبــة املقــررة نظامـ ًا‬\n      ‫وذلــك مبوجــب املــادة ‪ 60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة نظــر ًا لعــدم وجــود ســوابق علــى املدعــى عليــه وملــا ظهــر عليــه‬\n      ‫مــن عالمــات التوبــة عليــه ثالث ـ ًا ‪ :‬منــع املدعــى عليــه مــن الســفر خــارج‬\n      ‫اململكــة مــدة خمــس ســنوات بعــد تنفيــذ مــدة محكوميتــه وذلــك‬\n      ‫مبوجــب املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫رابع ـ ًا ‪ :‬مصــادرة اجلــوال املضبــوط مــع املدعــى عليــه مــن نــوع (‪)......‬‬\n      ‫الرقــم التسلســلي (‪ ).....‬املســتخدم يف اجلرميــة وفق ـ ًا للفقــرة (األولــى)‬\n      ‫مــن املــادة (‪ )53‬مــن النظــام املشــار إليــه وإيــداع املبالــغ يف حســاب إدارة‬\n      ‫ـاء علــى القــرار الــوزاري رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬ه ـ‬          ‫املخــدرات بنـ ً‬\n      ‫خامسـ ًا ‪ :‬إلغــاء شــرايحة االتصــال املوصوفــة يف القــرار وفــق برقيــة وزيــر‬\n      ‫الداخليــة رقــم (‪ )9798/4/5/1‬وتاريــخ ‪1428/2/10-9‬ه ـ سادس ـ ًا ‪:‬‬\n      ‫إلــزام املدعــى عليــه بــرد املبلــغ احلكومــي العائــد ملكافحــة املخــدرات‬\n      ‫باالحســاء وقــدره (‪ )1000‬ألــف ريــال اســتناد َا لتعميــم وزيــر الداخليــة‬\n      ‫رقــم (‪ )65980‬وتاريــخ ‪1422/10/23-22‬ه ـ وبــه حكمــت وبعــرض‬\n      ‫احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر املدعــي العــام اعتراضــه‬\n      ‫علــى احلكــم وطلــب رفــع املعاملــة إلــى محكمــة اإلســتئناف بــدون الئحة‬\n      ‫فأجبتــه لطلبــه وأمــا املدعــى عليــه قــرر قناعتــه بــه وبــه ختمــت اجللســة يف‬\n\n\n‫‪441‬‬\n\f‫متــام الســاعة ‪ 10 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/15‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/08/30‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 45‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫اإلســتئناف باملنطقــة الشــرقية برقــم يف ‪1434/08/24‬ه ـ واملتعلقــة‬\n‫بدعــوى املدعــي العــام ضــد املــدون هويتــه ســابق ًا يف قضيــة مخــدرات‬\n‫وبرفقهــا القــرار الشــرعي برقــم وتاريــخ ‪1434/08/07‬ه ـ الصــادر‬\n‫مــن الدائــرة اجلزائيــة الثانيــة مبحكمــة االســتئناف باملنطقــة الشــرقية‬\n‫املتضمــن إنــه بدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن‬\n‫فضيلتــه حكــم علــى املدعــى عليــه مبنعــه مــن الســفر ملدة خمس ســنوات‬\n‫بينمــا نصــت املــادة ‪ 56‬علــى أن مــدة املنــع تكــون مماثلــة ملــدة الســجن‬\n‫ملالحظــة مــا ذكــر وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة إلكمــال‬\n‫الزمهــا قاضــي اســتئناف (‪ ).......‬ختمــه وتوقيعــه قاضــي اســتئناف (‪).......‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة (‪ )......‬ختمــه وتوقيعــه وعليــه فإنــي أجيــب‬\n‫أصحــاب الفضيلــة قضــاة محكمــة االســتئناف وفقهــم اهلل لــكل‬\n‫خيــر بأننــي عدلــت عمــا حكمــت بــه مــن منــع املدعــى عليــه مــن الســفر‬\n‫خــارج اململكــة مــدة خمــس ســنوات وحكمــت مبنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة مماثلــة لســجنه وهــي ثــاث ســنوات وبــه ختمــت اجللســة يف‬\n‫متــام الســاعة ‪ 11 : 50‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم وتاريــخ ‪1434/9/20‬ه ـ الــواردة مــن‬\n\n\n                                                                                         ‫‪442‬‬\n\f      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف برقــم‬\n      ‫وتاريــخ ‪1434/9/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪ /‬املســجل برقــم وتاريــخ ‪1434/7/15‬ه ـ اخلــاص‬\n      ‫بدعوى‪/‬املدعــي العــام ضــد(‪ )......‬يف قضيــة مخــدرات وقــد تضمــن‬\n      ‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلتــه‬\n      ‫علــى قرارنــا رقــم وتاريــخ ‪1434/8/7‬ه ـ قررنــا املصادقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/10/20‬هــ‪.‬‬\n\n\n\n\n‫‪443‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":435,"source_page_end":443,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa5321b6f84ac313e9c03ee1e974103b4de579b6aef841bdb8669898894482fc","normalized_text_hash":"4063138d0f99e1fe5a1b3e115cdc1fa3902985261538e3de2b99a2fbfb8f7e7d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p435-34268398"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
